INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87471, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提", "is_correct": true, "explanation": "“提”即本词，指用手拿着东西使其下垂。"}, {"text": "梯", "is_correct": false, "explanation": "“梯”是第一声，与“提”的第二声不同，意思是梯子。"}, {"text": "体", "is_correct": false, "explanation": "“体”是第三声，与“提”的第二声不同，意思是身体。"}, {"text": "替", "is_correct": false, "explanation": "“替”是第四声，与“提”的第二声不同，意思是代替。"}], "explanations": {"提": "“提”即本词，指用手拿着东西使其下垂。", "梯": "“梯”是第一声，与“提”的第二声不同，意思是梯子。", "体": "“体”是第三声，与“提”的第二声不同，意思是身体。", "替": "“替”是第四声，与“提”的第二声不同，意思是代替。"}, "sentence_index": null, "correct_answer": "提"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛掷，不是拿着箱子，句意不通。"}, {"text": "提", "is_correct": true, "explanation": "“提”表示用手拎着东西，与“手里”搭配，符合句意。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”表示用脚撞击，与“手里”的动作相矛盾。"}, {"text": "背", "is_correct": false, "explanation": "搭配：“背”是背在背上，不能与“手里”搭配。"}], "explanations": {"扔": "语义：“扔”表示抛掷，不是拿着箱子，句意不通。", "提": "“提”表示用手拎着东西，与“手里”搭配，符合句意。", "踢": "语义：“踢”表示用脚撞击，与“手里”的动作相矛盾。", "背": "搭配：“背”是背在背上，不能与“手里”搭配。"}, "sentence_index": 0, "correct_answer": "提"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱提在兜里。", "explanation": "这里应该用〈揣〉。“提”需要用手拿着东西使其下垂，不能表示放进口袋。"}, {"text": "他把书提在腋下。", "explanation": "这里应该用〈夹〉。“提”指用手拎着，不能表示夹在胳膊下。"}, {"text": "他把箱子提在肩上。", "explanation": "这里应该用〈扛〉。“提”要用手拎着，不能表示扛在肩上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87471, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "提", "is_correct": true, "explanation": "“提”即本词，指用手拿着东西使其下垂。"}, {"text": "踢", "is_correct": false, "explanation": "“踢”是第一声，与“提”的第二声不同，意思是用脚撞击。"}, {"text": "剃", "is_correct": false, "explanation": "“剃”是第四声，与“提”的第二声不同，意思是用刀去掉毛发。"}, {"text": "剔", "is_correct": false, "explanation": "“剔”是第一声，与“提”的第二声不同，意思是挑出或去掉。"}], "explanations": {"提": "“提”即本词，指用手拿着东西使其下垂。", "踢": "“踢”是第一声，与“提”的第二声不同，意思是用脚撞击。", "剃": "“剃”是第四声，与“提”的第二声不同，意思是用刀去掉毛发。", "剔": "“剔”是第一声，与“提”的第二声不同，意思是挑出或去掉。"}, "sentence_index": null, "correct_answer": "提"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示歌唱，不能与“这么多东西”搭配。"}, {"text": "提", "is_correct": true, "explanation": "“提”表示用手拎着，与“东西”搭配，符合句意。"}, {"text": "叼", "is_correct": false, "explanation": "搭配：“叼”指用嘴咬住，一般只用于一件小东西，不能说“叼着这么多东西”。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”是用牙齿咬住，不能用于“这么多东西”的拿法。"}], "explanations": {"唱": "语义：“唱”表示歌唱，不能与“这么多东西”搭配。", "提": "“提”表示用手拎着，与“东西”搭配，符合句意。", "叼": "搭配：“叼”指用嘴咬住，一般只用于一件小东西，不能说“叼着这么多东西”。", "咬": "搭配：“咬”是用牙齿咬住，不能用于“这么多东西”的拿法。"}, "sentence_index": 6, "correct_answer": "提"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他嘴里提着一根烟。", "explanation": "这里应该用〈叼〉。“提”要用手拿着，不能用嘴含住。"}, {"text": "他头上提着一顶帽子。", "explanation": "这里应该用〈戴〉。“提”表示用手拿着，不能指戴在头上。"}, {"text": "他身上提着一件大衣。", "explanation": "这里应该用〈穿〉。“提”表示用手拿着，不能指穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她着提两个大包去车站。", "corrected_sentence": "她提着两个大包去车站。", "error_description": "错误：动态助词“着”放在了动词“提”之前。“着”应紧跟动词“提”之后，应改为“提着两个大包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人提动不那袋米。", "corrected_sentence": "老人提不动那袋米。", "error_description": "错误：可能补语“不动”的语序颠倒。“不”应放在补语“动”之前，表示不能完成，应改为“提不动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
