INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由艾滋病毒引起、使人体免疫功能严重受损的传染病。", "primary_collocate": null, "pronunciation": "ài zī bìng", "ipa": "aɪ˥˩ tsɿ˥ piŋ˥˩", "syllable_count": 3, "sentences": [{"text": "艾滋病是由病毒引起的传染病。", "target_word": "艾滋病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艾滋病会严重损害人体的免疫功能。", "target_word": "艾滋病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艾滋病可以通过血液和母婴途径传播。", "target_word": "艾滋病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艾滋病会破坏人体的免疫细胞。", "target_word": "艾滋病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用药物控制艾滋病，让病人活得更久。", "target_word": "艾滋病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在二十世纪八十年代发现了艾滋病。", "target_word": "艾滋病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查血液可以早点发现艾滋病。", "target_word": "艾滋病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艾滋病是一种严重的传染病，需要及时治疗。", "target_word": "艾滋病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上每年都有很多人死于艾滋病。", "target_word": "艾滋病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家说，预防艾滋病要避免共用针头。", "target_word": "艾滋病", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "艾滋病毒", "label": "复合词"}, {"form": "艾滋病人", "label": "复合词"}], "register": "书面", "sense_fingerprint": "由病毒引起、严重损害人体免疫功能的传染病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高血压", "is_correct": false, "explanation": "语义：高血压不是传染病，也不是由病毒引起的。"}, {"text": "艾滋病", "is_correct": true, "explanation": "正确：「艾滋病」是由病毒引起的传染病，与句子相符。"}, {"text": "近视", "is_correct": false, "explanation": "语义：近视是视力问题，不是由病毒引起的传染病。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是疾病，不可能由病毒引起。"}], "explanations": {"高血压": "语义：高血压不是传染病，也不是由病毒引起的。", "艾滋病": "正确：「艾滋病」是由病毒引起的传染病，与句子相符。", "近视": "语义：近视是视力问题，不是由病毒引起的传染病。", "书包": "语义：书包是物品，不是疾病，不可能由病毒引起。"}, "sentence_index": 0, "correct_answer": "艾滋病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台显微镜能把艾滋病放大一百倍。", "explanation": "这里应该用〈艾滋病毒〉。艾滋病是疾病，不能被显微镜放大；要放大观察的是病原体，要用“艾滋病毒”。"}, {"text": "护士用艾滋病给病人打针。", "explanation": "这里应该用〈药〉。艾滋病是疾病，不能用来打针；打针用的是药。"}, {"text": "她是一名艾滋病，每天去学校上课。", "explanation": "这里应该用〈艾滋病人〉。艾滋病指疾病，不指人；说患者要用“艾滋病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：血液检查查不出钥匙，钥匙不是病。"}, {"text": "艾滋病", "is_correct": true, "explanation": "正确：「艾滋病」是血液检查能发现的疾病，与句子相符。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包不是疾病，血液检查不能发现它。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被血液检查发现，与句意不符。"}], "explanations": {"钥匙": "语义：血液检查查不出钥匙，钥匙不是病。", "艾滋病": "正确：「艾滋病」是血液检查能发现的疾病，与句子相符。", "钱包": "语义：钱包不是疾病，血液检查不能发现它。", "天气": "语义：天气不能被血液检查发现，与句意不符。"}, "sentence_index": 6, "correct_answer": "艾滋病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都要吃艾滋病。", "explanation": "这里应该用〈药〉。艾滋病是疾病，不能吃；吃的是药。"}, {"text": "他下周要参加艾滋病。", "explanation": "这里应该用〈比赛〉。“参加”后面接比赛、活动，艾滋病不是可以参加的活动。"}, {"text": "弟弟最喜欢艾滋病。", "explanation": "这里应该用〈小熊〉。“喜欢”的对象可以是玩具或动物，艾滋病是疾病，没有人会喜欢它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人得了一只艾滋病，需要长期吃药。", "corrected_sentence": "这位老人得了艾滋病，需要长期吃药。", "error_description": "错误形式：“一只艾滋病”；正确形式：“得了艾滋病”（不加量词）。“只”是动物的量词，不能用来修饰疾病。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生已经确诊他艾滋病。", "corrected_sentence": "医生已经确诊他得了艾滋病。", "error_description": "错误形式：“医生已经确诊他艾滋病”，缺少动词；正确形式：“医生已经确诊他得了艾滋病”。“确诊”可直接以疾病为宾语（确诊艾滋病），但以人为宾语时需加“得了”等动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
