INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猪是农场里养的动物，身体胖胖的，鼻子长长的。", "primary_collocate": null, "pronunciation": "zhū", "ipa": "ʈʂu˥", "syllable_count": 1, "sentences": [{"text": "农场里有三头猪，它们正在吃东西。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那头猪的鼻子长长的，身体也很胖。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天早上给猪喂饲料。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头猪太胖了，走路很慢。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猪喜欢在泥里玩儿。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家养了五头猪和十只鸡。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，猪都睡在自己的圈里。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说猪的耳朵大大的，鼻子长长的。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在农场看见了一头很大的猪。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一头猪跑出了圈，农民急忙去追。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头", "label": "量词"}, {"form": "猪肉", "label": "复合"}, {"form": "野猪", "label": "复合"}, {"form": "豬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农场里养的动物，身体胖，鼻子长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e62db1-d0f4-433b-9204-45f7851b2ab7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确答案：猪（zhū），农场里养的家畜。"}, {"text": "竹", "is_correct": false, "explanation": "竹（zhú，第二声）与猪（zhū，第一声）声调不同，意思是竹子。"}, {"text": "主", "is_correct": false, "explanation": "主（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是主人。"}, {"text": "煮", "is_correct": false, "explanation": "煮（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是把食物加热。"}, {"text": "书", "is_correct": false, "explanation": "书（shū）与猪（zhū）声母不同（sh 与 zh），意思是书本。"}, {"text": "出", "is_correct": false, "explanation": "出（chū）与猪（zhū）声母不同（ch 与 zh），意思是出去。"}, {"text": "租", "is_correct": false, "explanation": "租（zū）与猪（zhū）声母不同（z 与 zh），意思是出租或租用。"}], "explanations": {"猪": "正确答案：猪（zhū），农场里养的家畜。", "竹": "竹（zhú，第二声）与猪（zhū，第一声）声调不同，意思是竹子。", "主": "主（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是主人。", "煮": "煮（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是把食物加热。", "书": "书（shū）与猪（zhū）声母不同（sh 与 zh），意思是书本。", "出": "出（chū）与猪（zhū）声母不同（ch 与 zh），意思是出去。", "租": "租（zū）与猪（zhū）声母不同（z 与 zh），意思是出租或租用。"}, "sentence_index": null, "correct_answer": "猪"}, "level_3": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确：猪，与“三头”搭配，指农场里的家畜。"}, {"text": "狮子", "is_correct": false, "explanation": "语义：狮子是野生动物，不是农场里养的家畜，与“农场里有”不符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“头”是牲畜的量词，书要用“本”，不能说“三头书”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不是农场里常养的家畜，与“农场里”冲突。"}], "explanations": {"猪": "正确：猪，与“三头”搭配，指农场里的家畜。", "狮子": "语义：狮子是野生动物，不是农场里养的家畜，与“农场里有”不符。", "书": "搭配：“头”是牲畜的量词，书要用“本”，不能说“三头书”。", "大象": "语义：大象不是农场里常养的家畜，与“农场里”冲突。"}, "sentence_index": 0, "correct_answer": "猪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家养了一条猪，很胖。", "explanation": "这里应该用〈头〉。猪作为家畜要用量词“头”，“条”多用于鱼、狗等，不用于猪。"}, {"text": "我们村的农民养了一匹猪。", "explanation": "这里应该用〈头〉。匹用于马、驴、骡等，猪不用匹。"}, {"text": "我昨天买了两斤猪。", "explanation": "这里应该用〈猪肉〉。猪指活的家畜，称重量的是肉，买肉要说猪肉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确答案：猪（zhū），农场里养的家畜。"}, {"text": "住", "is_correct": false, "explanation": "住（zhù，第四声）与猪（zhū，第一声）声调不同，意思是居住。"}, {"text": "祝", "is_correct": false, "explanation": "祝（zhù，第四声）与猪（zhū，第一声）声调不同，意思是祝愿。"}, {"text": "初", "is_correct": false, "explanation": "初（chū）与猪（zhū）声母不同（ch 与 zh），意思是开始。"}, {"text": "舒", "is_correct": false, "explanation": "舒（shū）与猪（zhū）声母不同（sh 与 zh），意思是舒服。"}, {"text": "粗", "is_correct": false, "explanation": "粗（cū）与猪（zhū）声母不同（c 与 zh），意思是粗细。"}], "explanations": {"猪": "正确答案：猪（zhū），农场里养的家畜。", "住": "住（zhù，第四声）与猪（zhū，第一声）声调不同，意思是居住。", "祝": "祝（zhù，第四声）与猪（zhū，第一声）声调不同，意思是祝愿。", "初": "初（chū）与猪（zhū）声母不同（ch 与 zh），意思是开始。", "舒": "舒（shū）与猪（zhū）声母不同（sh 与 zh），意思是舒服。", "粗": "粗（cū）与猪（zhū）声母不同（c 与 zh），意思是粗细。"}, "sentence_index": null, "correct_answer": "猪"}, "level_3": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确：猪，指睡在圈里的家畜。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不会睡在动物的圈里，与“圈”不符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“睡”要求有生命的主语，石头不能睡。"}, {"text": "花", "is_correct": false, "explanation": "配价：“睡”要求有生命的主语，花不能睡。"}], "explanations": {"猪": "正确：猪，指睡在圈里的家畜。", "老师": "语义：老师不会睡在动物的圈里，与“圈”不符。", "石头": "配价：“睡”要求有生命的主语，石头不能睡。", "花": "配价：“睡”要求有生命的主语，花不能睡。"}, "sentence_index": 6, "correct_answer": "猪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家买了一块猪，准备养起来。", "explanation": "这里应该用〈头〉。“块”用于块状的东西，不用于猪。"}, {"text": "我们农场买了一把猪。", "explanation": "这里应该用〈头〉。“把”用于有柄的东西，不用于猪。"}, {"text": "农场里有一张猪，很大。", "explanation": "这里应该用〈头〉。“张”用于平面的东西，不用于猪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷家的院子里养着一条猪。", "corrected_sentence": "爷爷家的院子里养着一头猪。", "error_description": "量词错误：应改为“一头猪”。猪作为家畜用量词“头”，“条”不用于猪。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我叔叔的两个猪养得很胖，他每天都很忙。", "corrected_sentence": "我叔叔的两头猪养得很胖，他每天都很忙。", "error_description": "量词错误：应改为“两头猪”。猪作为家畜用量词“头”，“个”不用于猪。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
