INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花会是大家一起看花的集会。", "primary_collocate": null, "pronunciation": "huā huì", "ipa": "xua˥ xuei˥˩", "syllable_count": 2, "sentences": [{"text": "春天公园里有一场花会，很多人去看花。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们全家一起去参加花会。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花会每年三月在城南的公园举行。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花会上有红的、黄的、白的各种花。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在花会上拍了很多漂亮的照片。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们约好明天一起去花会。", "target_word": "花会", "complexity_tier": "T3", "furigana": "huā huì", "sentence_source": "generated"}, {"text": "今年的花会比去年热闹，来了很多游客。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次逛花会，就爱上了兰花。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，今天的花会改到下周了。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友请我去花会，我们在花前喝茶聊天。", "target_word": "花会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "大家聚在一起看花的集会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地震", "is_correct": false, "explanation": "语义：地震是灾害，不是人们去看花的活动，与“很多人去看花”矛盾。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“一场”用于活动或事件，不能修饰“花瓶”。"}, {"text": "雷雨", "is_correct": false, "explanation": "语义：雷雨是天气，人们不会为了看花去“一场雷雨”，与句意矛盾。"}, {"text": "花会", "is_correct": true, "explanation": "正确：花会是大家一起看花的集会，与“一场”和“去看花”相符。"}], "explanations": {"地震": "语义：地震是灾害，不是人们去看花的活动，与“很多人去看花”矛盾。", "花瓶": "搭配：“一场”用于活动或事件，不能修饰“花瓶”。", "雷雨": "语义：雷雨是天气，人们不会为了看花去“一场雷雨”，与句意矛盾。", "花会": "正确：花会是大家一起看花的集会，与“一场”和“去看花”相符。"}, "sentence_index": 0, "correct_answer": "花会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年的花会很短，一个星期就谢了。", "explanation": "这里应该用〈花期〉。花会是大家一起看花的集会，不是花开的时间长短。"}, {"text": "我把花会摘下来，插进了花瓶。", "explanation": "这里应该用〈花朵〉。花会是大家一起看花的集会，不能摘下来插进花瓶。"}, {"text": "这棵大树一直长在花会里。", "explanation": "这里应该用〈花园〉。花会是临时的集会，不是可以让树扎根生长的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墓地", "is_correct": false, "explanation": "语义：墓地不是热闹的游览场所，与“来了很多游客”矛盾。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“热闹”形容场面或活动，不能形容手术。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房不是游客去的地方，与“来了很多游客”矛盾。"}, {"text": "花会", "is_correct": true, "explanation": "正确：花会是集会，今年比去年热闹，来了很多游客，与句意相符。"}], "explanations": {"墓地": "语义：墓地不是热闹的游览场所，与“来了很多游客”矛盾。", "手术": "搭配：“热闹”形容场面或活动，不能形容手术。", "病房": "语义：病房不是游客去的地方，与“来了很多游客”矛盾。", "花会": "正确：花会是集会，今年比去年热闹，来了很多游客，与句意相符。"}, "sentence_index": 6, "correct_answer": "花会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我捡起一片花会，夹进了书里。", "explanation": "这里应该用〈花瓣〉。花会是集会，不能一片片捡起来夹进书里。"}, {"text": "门口挂着一个花会。", "explanation": "这里应该用〈花篮〉。花会是集会，不能挂在门口。"}, {"text": "春天的花粉飘在空中，到处都是花会。", "explanation": "这里应该用〈花粉〉。花会是看花的集会，不会飘在空中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家花会上拍了很多照片。", "corrected_sentence": "大家在花会上拍了很多照片。", "error_description": "错误：表示地点要用“在……上”，应说“在花会上”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把花会安排很好。", "corrected_sentence": "妈妈把花会安排得很好。", "error_description": "错误：“把”字句中动作后接程度补语要用“得”，应说“安排得很好”，不能说“安排很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。"}, {"text": "坐下", "is_correct": false, "explanation": "与“退出”没有反义关系，二者不构成一对相对的词。"}, {"text": "打扫", "is_correct": false, "explanation": "与“退出”没有反义关系，“打扫”是清洁房间，不是与“退出”相对的动作。"}, {"text": "等候", "is_correct": false, "explanation": "与“退出”没有反义关系，“等候”是等待，不是与“退出”相对的动作。"}], "correct_answer": "进入", "explanations": {"进入": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。", "坐下": "与“退出”没有反义关系，二者不构成一对相对的词。", "打扫": "与“退出”没有反义关系，“打扫”是清洁房间，不是与“退出”相对的动作。", "等候": "与“退出”没有反义关系，“等候”是等待，不是与“退出”相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。"}, {"text": "到达", "is_correct": false, "explanation": "与“退出”没有反义关系，“到达”是抵达某地，不是与“退出”相对的动作。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“退出”没有反义关系，“洗澡”是清洗身体，不是与“退出”相对的动作。"}, {"text": "待命", "is_correct": false, "explanation": "与“退出”没有反义关系，“待命”是等待行动的命令，不是与“退出”相对的动作。"}], "correct_answer": "进入", "explanations": {"进入": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。", "到达": "与“退出”没有反义关系，“到达”是抵达某地，不是与“退出”相对的动作。", "洗澡": "与“退出”没有反义关系，“洗澡”是清洗身体，不是与“退出”相对的动作。", "待命": "与“退出”没有反义关系，“待命”是等待行动的命令，不是与“退出”相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "退出是从里面走出来，不再待在里面。", "primary_collocate": null, "pronunciation": "tuì chū", "ipa": "tʰuei̯˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他轻轻退出房间，随手关上了门。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员鞠了躬，慢慢退出了舞台。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人都坐好后，服务员退出了包间。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到有人敲门，便悄悄退出了办公室。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，妈妈轻轻退出了卧室。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理放下文件，向大家点点头，退出了会议室。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先退出教室，在门外等我。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得无聊，中途悄悄退出了会场。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太闷，我们先退出了房间，到外面透透气。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请大家马上退出这间屋子。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退出了", "label": "体标"}, {"form": "退出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从房间、舞台等空间里走出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指从房间里走出，与“轻轻”“随手关上了门”的动作相符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能接“房间”，与“轻轻……房间”不搭。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的是歌曲，与“房间”不搭，也不符合“随手关上了门”的情境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，与“房间”无关，句子不成立。"}], "explanations": {"退出": "“退出”指从房间里走出，与“轻轻”“随手关上了门”的动作相符。", "吃": "配价：“吃”的宾语应是食物，不能接“房间”，与“轻轻……房间”不搭。", "唱": "语义：唱的是歌曲，与“房间”不搭，也不符合“随手关上了门”的情境。", "喝": "语义：“喝”的对象是液体，与“房间”无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到有人敲门，便悄悄退出了钥匙。", "explanation": "这里应该用〈拿〉：拿起钥匙说“拿”；“退出”只用于离开场所、组织或活动，不能接物品。"}, {"text": "他站起来，悄悄退出了那块蛋糕。", "explanation": "这里应该用〈端〉：端起蛋糕说“端”；“退出”只用于离开场所、组织或活动，不能接食物。"}, {"text": "他把借来的书退出了图书馆。", "explanation": "这里应该用〈还〉：归还借的书说“还”；“退出”指离开场所，不能用于书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指从教室出去，与“在门外等我”的安排相符。"}, {"text": "进入", "is_correct": false, "explanation": "语义：“进入”与“在门外等我”矛盾，前后意思不一致。"}, {"text": "占领", "is_correct": false, "explanation": "语义：“占领”指强行占据，与“请你先……在门外等我”的语境不搭。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”的宾语应是可以咬的东西，不能接“教室”。"}], "explanations": {"退出": "“退出”指从教室出去，与“在门外等我”的安排相符。", "进入": "语义：“进入”与“在门外等我”矛盾，前后意思不一致。", "占领": "语义：“占领”指强行占据，与“请你先……在门外等我”的语境不搭。", "咬": "配价：“咬”的宾语应是可以咬的东西，不能接“教室”。"}, "sentence_index": 6, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋天到了，树叶慢慢退出了绿色。", "explanation": "这里应该用〈褪去〉：颜色消退说“褪去”；“退出”指离开场所、组织或活动，不能用于颜色。"}, {"text": "春天到了，树上退出了新芽。", "explanation": "这里应该用〈长出〉：草木生出新芽说“长出”；“退出”指离开场所、组织或活动，不说“退出新芽”。"}, {"text": "他把嘴里的饭退出来了。", "explanation": "这里应该用〈吐出〉：把嘴里的东西吐出来说“吐出”；“退出”不能用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们刚才悄悄退出在会议室。", "corrected_sentence": "我们刚才悄悄退出了会议室。", "error_description": "介词错误：“退出在会议室”。“退出”后不能用“在”引出所离开的场所，应说“退出了会议室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚退出着房间，马上又回来了。", "corrected_sentence": "他刚退出了房间，马上又回来了。", "error_description": "体标错误：“退出”表示已经完成的离开，应该用“了”，不能用“着”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加入", "is_correct": true, "explanation": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。"}, {"text": "发展", "is_correct": false, "explanation": "与“退出”没有反义关系，“发展”指事物壮大或进步，不与“退出”相对。"}, {"text": "购买", "is_correct": false, "explanation": "与“退出”没有反义关系，“购买”指花钱获得物品，不与“退出”相对。"}, {"text": "聚会", "is_correct": false, "explanation": "与“退出”没有反义关系，“聚会”指人们相聚，不是与“退出”相对的动作。"}], "correct_answer": "加入", "explanations": {"加入": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。", "发展": "与“退出”没有反义关系，“发展”指事物壮大或进步，不与“退出”相对。", "购买": "与“退出”没有反义关系，“购买”指花钱获得物品，不与“退出”相对。", "聚会": "与“退出”没有反义关系，“聚会”指人们相聚，不是与“退出”相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加入", "is_correct": true, "explanation": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。"}, {"text": "维持", "is_correct": false, "explanation": "与“退出”没有反义关系，“维持”指保持原状，不与“退出”相对。"}, {"text": "筹备", "is_correct": false, "explanation": "与“退出”没有反义关系，“筹备”指事先做准备，不与“退出”相对。"}, {"text": "研发", "is_correct": false, "explanation": "与“退出”没有反义关系，“研发”指研究开发，不与“退出”相对。"}], "correct_answer": "加入", "explanations": {"加入": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。", "维持": "与“退出”没有反义关系，“维持”指保持原状，不与“退出”相对。", "筹备": "与“退出”没有反义关系，“筹备”指事先做准备，不与“退出”相对。", "研发": "与“退出”没有反义关系，“研发”指研究开发，不与“退出”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从某个场所、组织或活动中离开，不再参加。", "primary_collocate": null, "pronunciation": "tuì chū", "ipa": "tʰuei̯˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他不想再踢球了，决定退出足球队。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王因为工作太忙，退出了读书会。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很早就退出了那个微信群。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为受伤，他退出了比赛。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，已经退出了公司。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太累了，我想退出这个活动。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个同学退出了学校的篮球队。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退出过两次比赛，这次一定要坚持。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她退出了合唱团，专心准备考试。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不赚钱，老板决定退出这个市场。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退出了", "label": "体标"}, {"form": "退出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "离开组织、比赛、活动，不再参加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指离开球队，与“不想再踢球了，决定……”的意思一致。"}, {"text": "加入", "is_correct": false, "explanation": "语义：“加入”与“不想再踢球了”矛盾，前后意思不一致。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所，不能接“足球队”。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，不能接“足球队”。"}], "explanations": {"退出": "“退出”指离开球队，与“不想再踢球了，决定……”的意思一致。", "加入": "语义：“加入”与“不想再踢球了”矛盾，前后意思不一致。", "打扫": "搭配：“打扫”的对象是场所，不能接“足球队”。", "喝": "配价：“喝”的宾语应是饮品，不能接“足球队”。"}, "sentence_index": 0, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为受伤，他退出了那瓶水。", "explanation": "这里的“退出”被当成了拿走物品，应该用〈拿〉：拿起水说“拿”；“退出”只用于离开组织或活动，不能接物品。"}, {"text": "他觉得不满意，就把衣服退出了商店。", "explanation": "这里应该用〈退货〉：把买的东西还回去说“退货”；“退出”指离开组织或活动，不能用于商品。"}, {"text": "他终于退出了危险，松了一口气。", "explanation": "这里应该用〈脱离〉：脱离危险、困境；“退出”用于组织和活动，不说“退出危险”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指离开学校的篮球队，与“三个同学”的语境相符。"}, {"text": "打破", "is_correct": false, "explanation": "语义：“打破”指打碎或突破，不用于人员组织，与“篮球队”不搭。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能接“篮球队”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用于组织或团队，与“篮球队”不搭。"}], "explanations": {"退出": "“退出”指离开学校的篮球队，与“三个同学”的语境相符。", "打破": "语义：“打破”指打碎或突破，不用于人员组织，与“篮球队”不搭。", "吃": "配价：“吃”的宾语应是食物，不能接“篮球队”。", "洗": "搭配：“洗”不能用于组织或团队，与“篮球队”不搭。"}, "sentence_index": 6, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近的头发退出得很厉害。", "explanation": "这里应该用〈脱落〉：头发掉下来说“脱落”；“退出”指离开场所、组织或活动。"}, {"text": "这棵老树今年又退出了好多新叶。", "explanation": "这里应该用〈长出〉：草木生出新叶说“长出”；“退出”指离开场所、组织或活动，不说“退出新叶”。"}, {"text": "他用力把牙膏里的膏退出来了。", "explanation": "这里应该用〈挤出〉：用力把膏状物从管子里压出来说“挤出”；“退出”不能用于膏状物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上个月就退出在合唱团。", "corrected_sentence": "她上个月就退出了合唱团。", "error_description": "介词错误：“退出在合唱团”。“退出”后不能用“在”引出所退出的团体，应说“退出了合唱团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们决定退出来这个项目。", "corrected_sentence": "他们决定退出这个项目。", "error_description": "补语错误：“退出”直接带宾语时不能再接“来”，应说“退出这个项目”；若要用“来”，须说“从这个项目退出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
