INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花被是包在花外面的花瓣和绿叶片。", "primary_collocate": null, "pronunciation": "huā bèi", "ipa": "xua˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "花被包在花的外面。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花的花被是白色的。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小花的花被又薄又软。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，这朵花的花被慢慢打开了。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我摸了摸那朵花的花被。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花被下面是绿色的小叶子。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的花被有五片。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，那朵花的花被轻轻动了起来。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在看花被里面的小虫子。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的花被呈鲜红色，十分美丽。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花被片", "label": "复合"}, {"form": "花被筒", "label": "复合"}], "register": "书面", "sense_fingerprint": "包在花外面的花瓣和绿色叶片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花被", "is_correct": true, "explanation": "正确：花被是包在花外面的花瓣和绿叶片，“包在花的外面”符合定义。"}, {"text": "花蕊", "is_correct": false, "explanation": "语义：花蕊长在花心，不在花的外面。"}, {"text": "花粉", "is_correct": false, "explanation": "搭配：花粉是细小颗粒，不能说“包在花的外面”。"}, {"text": "树皮", "is_correct": false, "explanation": "语义：树皮属于树干，不是花的部件。"}], "explanations": {"花被": "正确：花被是包在花外面的花瓣和绿叶片，“包在花的外面”符合定义。", "花蕊": "语义：花蕊长在花心，不在花的外面。", "花粉": "搭配：花粉是细小颗粒，不能说“包在花的外面”。", "树皮": "语义：树皮属于树干，不是花的部件。"}, "sentence_index": 0, "correct_answer": "花被"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜蜂把花被从一朵花带到另一朵花上。", "explanation": "这里应该用〈花粉〉。花粉才会被蜜蜂带去传粉，花被是包在花外面的花瓣和绿叶片，不会离开花。"}, {"text": "我在地上捡到一粒花被。", "explanation": "这里〈花被〉是整圈的花瓣和绿叶片，不能按小颗粒来数，应说“一朵花的花被”。"}, {"text": "园子里有一只花被在晒太阳。", "explanation": "这里〈花被〉是植物的部分，不能像动物那样计数，应说“一朵花的花被”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花被", "is_correct": true, "explanation": "正确：花被是花的外围部分，可以按“片”计数，符合“有五片”。"}, {"text": "花枝", "is_correct": false, "explanation": "搭配：花枝是长条状，应按〈根〉或〈条〉计量，不能用“片”。"}, {"text": "花坛", "is_correct": false, "explanation": "语义：花坛是种花的地方，不是花的一部分。"}, {"text": "花蜜", "is_correct": false, "explanation": "搭配：花蜜是液体，不用“片”计量，不能说“有五片”。"}], "explanations": {"花被": "正确：花被是花的外围部分，可以按“片”计数，符合“有五片”。", "花枝": "搭配：花枝是长条状，应按〈根〉或〈条〉计量，不能用“片”。", "花坛": "语义：花坛是种花的地方，不是花的一部分。", "花蜜": "搭配：花蜜是液体，不用“片”计量，不能说“有五片”。"}, "sentence_index": 6, "correct_answer": "花被"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花被会产生很多花粉，让蜜蜂带走。", "explanation": "这里应该用〈花蕊〉。花粉由花蕊产生，花被是包在花外面的部分，不产生花粉。"}, {"text": "蝴蝶每天来吸花被的甜汁。", "explanation": "这里应该用〈花蜜〉。甜汁来自花心的蜜腺，花被是外围部分，不提供花蜜。"}, {"text": "这棵大树的花被扎得很深。", "explanation": "这里应该用〈根〉。根才会扎入土里，花被是花的外围部分，不能用来说扎深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵月季的花被有五朵。", "corrected_sentence": "这朵月季的花被有五片。", "error_description": "“五朵”应为“五片”：〈朵〉用于整朵花，花被的各个部分要按〈片〉计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没见过这种花的花被了。", "corrected_sentence": "我还没见过这种花的花被。", "error_description": "“还没见过这种花的花被了”应删去句末的“了”：“还没见过”表示经历尚未发生，句末表示变化的“了”与之矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
