INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花的外围部分，花瓣和花萼的合称。", "primary_collocate": null, "pronunciation": "huā bèi", "ipa": "xua˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "百合的花被由六片组成。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "郁金香的花被颜色很鲜艳。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些花的花萼和花瓣很像，合起来叫花被。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一朵花的花被。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桃花的花被分成花瓣和花萼。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花被保护着里面的花蕊。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花的花被已经慢慢张开了。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用放大镜观察花被的形状。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花被的外面一层是绿色的。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些植物的花被很小，不容易看见。", "target_word": "花被", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花被片", "label": "复合"}, {"form": "花被筒", "label": "复合"}], "register": "书面", "sense_fingerprint": "花瓣和花萼的合称，植物学上指花的外围部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花被", "is_correct": true, "explanation": "正确：花被是花瓣和花萼的合称，“百合的花被由六片组成”符合句意。"}, {"text": "种子", "is_correct": false, "explanation": "语义：种子是植物的繁殖体，不是由片组成的花的外围部分。"}, {"text": "根", "is_correct": false, "explanation": "语义：根长在地下，不属于花，也不按“片”计数。"}, {"text": "花粉", "is_correct": false, "explanation": "搭配：花粉是细小颗粒，不用“片”计量，不能说“由六片组成”。"}], "explanations": {"花被": "正确：花被是花瓣和花萼的合称，“百合的花被由六片组成”符合句意。", "种子": "语义：种子是植物的繁殖体，不是由片组成的花的外围部分。", "根": "语义：根长在地下，不属于花，也不按“片”计数。", "花粉": "搭配：花粉是细小颗粒，不用“片”计量，不能说“由六片组成”。"}, "sentence_index": 0, "correct_answer": "花被"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她摘下一瓣花被，夹进了书里。", "explanation": "这里〈花被〉是整圈的花瓣和花萼，不能按单片来数，应说“一朵花的花被”。"}, {"text": "园丁剪下一根花被，插进了花瓶。", "explanation": "这里〈花被〉是整圈的花瓣和花萼，不能按细长条来数，应说“一朵花的花被”。"}, {"text": "他抱着一只花被走过来。", "explanation": "这里〈花被〉是植物的部分，不能像动物那样计数，应说“一朵花的花被”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花被", "is_correct": true, "explanation": "正确：花被是花的外围部分，能够慢慢张开，符合“这朵花的……已经慢慢张开了”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户属于房屋，不是花的部分，“这朵花的窗户”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的用品，不是花的部分，“这朵花的书包”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会展开，与“慢慢张开”的变化不符。"}], "explanations": {"花被": "正确：花被是花的外围部分，能够慢慢张开，符合“这朵花的……已经慢慢张开了”。", "窗户": "语义：窗户属于房屋，不是花的部分，“这朵花的窗户”说不通。", "书包": "语义：书包是装书的用品，不是花的部分，“这朵花的书包”说不通。", "石头": "语义：石头不会展开，与“慢慢张开”的变化不符。"}, "sentence_index": 6, "correct_answer": "花被"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摘下一颗花被夹在书里。", "explanation": "这里〈花被〉是整圈的花瓣和花萼，不能按小颗粒来数，应说“一朵花的花被”。"}, {"text": "蜜蜂一直在采花被的蜜。", "explanation": "这里应该用〈花蜜〉。花蜜在花心的蜜腺里，花被是花的外围部分，不产蜜。"}, {"text": "这棵树的花被扎进了土里。", "explanation": "这里应该用〈根〉。扎进土里的是根，花被是花的外围部分，长在花上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵百合的花被有六只。", "corrected_sentence": "这朵百合的花被有六片。", "error_description": "“六只”应为“六片”：花被由花瓣、花萼组成，片状的部分用〈片〉计量，〈只〉用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花被还没有张开了。", "corrected_sentence": "花被还没有张开。", "error_description": "“还没有张开了”应为“还没有张开”：“还没有”表示变化尚未发生，句末的“了”表示变化已经发生，两者矛盾，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
