INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87483, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "适用是可以拿来用，用起来合适。", "primary_collocate": null, "pronunciation": "shì yòng", "ipa": "ʂɻ̩˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这把伞又大又轻，很适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工具简单适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种椅子便宜，也很适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我的笔很适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小厨房里的东西要小而适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套餐具不好看，但是很适用。", "target_word": "适用", "complexity_tier": "T3", "furigana": "zhè tào cān jù bù hǎo kàn, dàn shì hěn shì yòng.", "sentence_source": "generated"}, {"text": "对学生来说，这本词典最适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法简单，大家都觉得适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套工具买得很对，真适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张办公桌不大，但是很适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适用", "label": "否定式"}, {"form": "适用范围", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：东西拿来用很合适、好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "适用", "is_correct": true, "explanation": "“适用”指东西拿来用很合适、好用，正是这里的意思。"}, {"text": "食用", "is_correct": false, "explanation": "shí 与 shì 声调不同（第二声与第四声），意思是供人吃用，如“食用油”，与“好用”无关。"}, {"text": "日用", "is_correct": false, "explanation": "r 与 sh 声母不同，意思是日常使用，如“日用品”。"}, {"text": "饲用", "is_correct": false, "explanation": "s 与 sh 声母不同（sì 与 shì），意思是用于喂养牲畜。"}], "explanations": {"适用": "“适用”指东西拿来用很合适、好用，正是这里的意思。", "食用": "shí 与 shì 声调不同（第二声与第四声），意思是供人吃用，如“食用油”，与“好用”无关。", "日用": "r 与 sh 声母不同，意思是日常使用，如“日用品”。", "饲用": "s 与 sh 声母不同（sì 与 shì），意思是用于喂养牲畜。"}, "sentence_index": null, "correct_answer": "适用"}, "level_3": {"options": [{"text": "适用", "is_correct": true, "explanation": "“适用”指东西好用，与“又大又轻，很适用”一致。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”指分量大，与“又轻”矛盾。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”指又大又沉，与“又轻”相反。"}, {"text": "复杂", "is_correct": false, "explanation": "搭配：评价一把伞好用与否，不说“复杂”，这样搭配不当。"}], "explanations": {"适用": "“适用”指东西好用，与“又大又轻，很适用”一致。", "沉重": "语义：“沉重”指分量大，与“又轻”矛盾。", "笨重": "语义：“笨重”指又大又沉，与“又轻”相反。", "复杂": "搭配：评价一把伞好用与否，不说“复杂”，这样搭配不当。"}, "sentence_index": 0, "correct_answer": "适用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很适用做这份工作。", "explanation": "这里应该用〈合适〉。适用多形容东西、方法好不好用，说人适合某件事要用合适。"}, {"text": "这个颜色很适用。", "explanation": "这里应该用〈好看〉。适用形容东西拿来用合不合适，说颜色美观要用好看。"}, {"text": "他很适用地完成了工作。", "explanation": "这里应该用〈称职〉。适用形容东西拿来用合不合适，不用来评价人的工作能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适用", "is_correct": true, "explanation": "“适用”指东西好用，与“对学生来说，这本词典最适用”一致。"}, {"text": "使用", "is_correct": false, "explanation": "词性：“使用”是动词，需要带宾语，不能受“最”修饰单独作谓语。"}, {"text": "用途", "is_correct": false, "explanation": "词性：“用途”是名词，不能受“最”修饰作谓语。"}, {"text": "利用", "is_correct": false, "explanation": "词性：“利用”是动词，须带宾语，“这本词典最利用”不通。"}], "explanations": {"适用": "“适用”指东西好用，与“对学生来说，这本词典最适用”一致。", "使用": "词性：“使用”是动词，需要带宾语，不能受“最”修饰单独作谓语。", "用途": "词性：“用途”是名词，不能受“最”修饰作谓语。", "利用": "词性：“利用”是动词，须带宾语，“这本词典最利用”不通。"}, "sentence_index": 6, "correct_answer": "适用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很适用，做事很快。", "explanation": "这里应该用〈能干〉。适用形容东西拿来用合不合适，形容人的能力要用能干。"}, {"text": "她长得很适用。", "explanation": "这里应该用〈漂亮〉。适用不形容人的外貌，说人好看要用漂亮。"}, {"text": "他对客人很适用。", "explanation": "这里应该用〈热情〉。适用只用于东西或方法，不能形容人的待人态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞不适用于，我们换一把吧。", "corrected_sentence": "这把伞不适用，我们换一把吧。", "error_description": "“适用”作形容词时不带宾语，后面不能接“于”而没有对象。写成“不适用于，……”是错误的，应说“这把伞不适用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套工具虽然小，但是很的适用。", "corrected_sentence": "这套工具虽然小，但是很适用。", "error_description": "程度副词“很”后直接接形容词，中间不能加“的”。写成“很的适用”是错误的，应说“很适用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
