INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "适合使用；在某一范围内可以使用。", "primary_collocate": null, "pronunciation": "shì yòng", "ipa": "ʂɻ̩˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个规定适用于所有学生。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法不适用于小孩。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规则对大家都适用。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书适用于初学者。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法只适用于家里。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价格只适用于新客人。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药不适用于老人。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧方法在这里已经不适用了。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡适用于全市的地铁。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词适用的范围很小。", "target_word": "适用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适用", "label": "否定式"}, {"form": "适用范围", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：规定、方法等在某一范围或对象内可以使用，常说适用于", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87484, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "适用", "is_correct": true, "explanation": "“适用”指规定、方法在某一范围内可以使用，正是这里的意思。"}, {"text": "食用", "is_correct": false, "explanation": "shí 与 shì 声调不同（第二声与第四声），意思是供人吃用，如“食用油”，与“可用于某范围”无关。"}, {"text": "日用", "is_correct": false, "explanation": "r 与 sh 声母不同，意思是日常使用，如“日用品”。"}, {"text": "饲用", "is_correct": false, "explanation": "s 与 sh 声母不同（sì 与 shì），意思是用于喂养牲畜。"}], "explanations": {"适用": "“适用”指规定、方法在某一范围内可以使用，正是这里的意思。", "食用": "shí 与 shì 声调不同（第二声与第四声），意思是供人吃用，如“食用油”，与“可用于某范围”无关。", "日用": "r 与 sh 声母不同，意思是日常使用，如“日用品”。", "饲用": "s 与 sh 声母不同（sì 与 shì），意思是用于喂养牲畜。"}, "sentence_index": null, "correct_answer": "适用"}, "level_3": {"options": [{"text": "适用", "is_correct": true, "explanation": "“适用于”指规定可以用于某范围，与“这个规定适用于所有学生”一致。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业于”后接学校，规定不能“毕业于所有学生”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生于”后接时间地点，主语须是人，规定不能出生。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生于”后接时间地点，不能接“所有学生”。"}], "explanations": {"适用": "“适用于”指规定可以用于某范围，与“这个规定适用于所有学生”一致。", "毕业": "语义：“毕业于”后接学校，规定不能“毕业于所有学生”。", "出生": "语义：“出生于”后接时间地点，主语须是人，规定不能出生。", "诞生": "语义：“诞生于”后接时间地点，不能接“所有学生”。"}, "sentence_index": 0, "correct_answer": "适用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很适用于做老师。", "explanation": "这里应该用〈适合〉。适用用于规定、方法等可以使用的范围，说人适合做某事要用适合。"}, {"text": "这次考试我很适用，考得不错。", "explanation": "这里应该用〈发挥〉。适用指规定、方法可用于某范围，不能形容考试时的表现，应说发挥。"}, {"text": "我们适用这把钥匙开门。", "explanation": "这里应该用〈使用〉。适用指规定、方法可用于某范围，不能直接接具体工具作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适用", "is_correct": true, "explanation": "“不适用于老人”指这种药不能用于老人，与该语境一致。"}, {"text": "位于", "is_correct": false, "explanation": "语义：“位于”表示处在某个地方，后接地点；药不能“位于老人”。"}, {"text": "成立", "is_correct": false, "explanation": "语义：“成立于”说机构建立的时间，主语是组织，药不能成立。"}, {"text": "定居", "is_correct": false, "explanation": "语义：“定居”的主语须是人，后接地点；药不能定居，也不能接“老人”。"}], "explanations": {"适用": "“不适用于老人”指这种药不能用于老人，与该语境一致。", "位于": "语义：“位于”表示处在某个地方，后接地点；药不能“位于老人”。", "成立": "语义：“成立于”说机构建立的时间，主语是组织，药不能成立。", "定居": "语义：“定居”的主语须是人，后接地点；药不能定居，也不能接“老人”。"}, "sentence_index": 6, "correct_answer": "适用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快适用了新环境。", "explanation": "这里应该用〈适应〉。适用指规定、方法可用于某范围，人接受新环境要用适应。"}, {"text": "他适用这个方法解决了问题。", "explanation": "这里应该用〈运用〉。适用的主语是规定或方法，不能用于人主动地“用”。"}, {"text": "吃饭要适用，别吃太多。", "explanation": "这里应该用〈适度〉。适用指可用于某范围，说分寸合适要用适度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法不适用于于小型公司。", "corrected_sentence": "这个办法不适用于小型公司。", "error_description": "错误形式：“这个办法不适用于于小型公司”；正确形式：“这个办法不适用于小型公司”。“于”在“适用”后只能出现一次，重复写成“于于”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个标准的适用了范围很大。", "corrected_sentence": "这个标准的适用范围很大。", "error_description": "“适用范围”是固定的复合词，中间不能插入“了”。写成“适用了范围”是错误的，应说“适用范围”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
