INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用粮食、水果等发酵或蒸馏制成的含酒精的饮料。", "primary_collocate": null, "pronunciation": "jiǔ", "ipa": "tɕjoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这种酒是用粮食做的。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "葡萄可以做成酒。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，我们家喜欢自己做酒。", "target_word": "酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酒是用水果做的，很甜。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在饭店点了一瓶酒。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种酒的味道很特别。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把酒倒进了杯子里。", "target_word": "酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，爸爸拿出一瓶好酒。", "target_word": "酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的酒很贵。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们一起举杯，喝了这杯酒。", "target_word": "酒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一杯酒", "label": "量词"}, {"form": "一瓶酒", "label": "量词"}, {"form": "白酒", "label": "复合"}], "register": "中性", "sense_fingerprint": "粮食水果发酵或蒸馏制成的含酒精饮料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '934308b8-5ea3-4b86-bc2c-3ae9d4ecc7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：jiǔ（第三声）指用粮食或水果发酵、蒸馏制成的含酒精饮料。"}, {"text": "旧", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“旧”。"}, {"text": "救", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“救”。"}, {"text": "纠", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“纠正”。"}, {"text": "揪", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“揪住”。"}], "explanations": {"酒": "正确：jiǔ（第三声）指用粮食或水果发酵、蒸馏制成的含酒精饮料。", "旧": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“旧”。", "救": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“救”。", "纠": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“纠正”。", "揪": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“揪住”。"}, "sentence_index": null, "correct_answer": "酒"}, "level_3": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：“这种酒是用粮食做的”说明饮品的原料，符合句意。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是用粮食做的，句子不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能用粮食做，句子不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌不能用粮食做，句子不通。"}], "explanations": {"酒": "正确：“这种酒是用粮食做的”说明饮品的原料，符合句意。", "音乐": "语义：音乐不是用粮食做的，句子不通。", "电脑": "语义：电脑不能用粮食做，句子不通。", "诗歌": "语义：诗歌不能用粮食做，句子不通。"}, "sentence_index": 0, "correct_answer": "酒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种酒是用面粉烤出来的。", "explanation": "这里应该用〈面包〉。酒要用粮食、水果等发酵或蒸馏制成，用面粉烤出来的是面包，不是酒。"}, {"text": "这杯酒是用咖啡豆磨的。", "explanation": "这里应该用〈咖啡〉。酒要用粮食、水果等发酵或蒸馏制成，咖啡豆磨出来的是咖啡，不是酒。"}, {"text": "这种酒是用水果压碎后直接喝的，没有发酵。", "explanation": "这里应该用〈果汁〉。酒要经过发酵或蒸馏，压碎后直接喝的是果汁，不是酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87486, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：jiǔ（第三声）指用粮食或水果发酵、蒸馏制成的含酒精饮料。"}, {"text": "就", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“就”。"}, {"text": "舅", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“舅舅”。"}, {"text": "究", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“追究、研究”。"}], "explanations": {"酒": "正确：jiǔ（第三声）指用粮食或水果发酵、蒸馏制成的含酒精饮料。", "就": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“就”。", "舅": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“舅舅”。", "究": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“追究、研究”。"}, "sentence_index": null, "correct_answer": "酒"}, "level_3": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：“把酒倒进杯子里”中的“酒”是液体，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能被倒进杯子，句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“倒”一般用于液体或颗粒，不能说“倒空气”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能倒进杯子里，与“倒”的语境不合。"}], "explanations": {"酒": "正确：“把酒倒进杯子里”中的“酒”是液体，符合句意。", "钥匙": "语义：钥匙不能被倒进杯子，句子不通。", "空气": "搭配：“倒”一般用于液体或颗粒，不能说“倒空气”。", "石头": "语义：石头不能倒进杯子里，与“倒”的语境不合。"}, "sentence_index": 6, "correct_answer": "酒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种酒是用蔬菜炒出来的，很香。", "explanation": "这里应该用〈炒菜〉。酒要用粮食、水果等发酵或蒸馏制成，用蔬菜炒出来的是菜，不是酒。"}, {"text": "这种酒是用石油炼出来的，不能喝。", "explanation": "这里应该用〈汽油〉。酒要用粮食、水果等发酵或蒸馏制成，石油炼出来的是汽油，不是酒。"}, {"text": "这种酒是用牛肉熏出来的。", "explanation": "这里应该用〈腊肉〉。酒要用粮食、水果等发酵或蒸馏制成，熏出来的是腊肉，不是酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸每年春节都会自己酿一个酒。", "corrected_sentence": "爸爸每年春节都会自己酿一缸酒。", "error_description": "量词错误：酒不能用“个”计量，应说“一缸酒”“一瓶酒”或“一杯酒”。正确说法是“爸爸每年春节都会自己酿一缸酒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把酒洒。", "corrected_sentence": "他把酒洒了。", "error_description": "把字句错误：“把”字句中的单音节动词后必须带“了”或其他补足成分，不能说“他把酒洒”，应说“他把酒洒了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
