INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大妈是年纪比妈妈大一点的女人。大家这样叫她，是为了表示尊敬。", "primary_collocate": null, "pronunciation": "dà mā", "ipa": "tɑ˥˩ ma˥", "syllable_count": 2, "sentences": [{"text": "大妈，请问去超市怎么走？", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下的大妈每天早上都去买菜。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多大妈在跳舞。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们叫她大妈，因为她比妈妈大几岁。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大妈给我们送来了一盘水果。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大妈帮我拿了很重的包。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大妈笑着对我说：“慢点儿走。”", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口的大妈在卖菜。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大妈，您坐这儿吧，这里有位子。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁的大妈常常帮我们看孩子。", "target_word": "大妈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "大媽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对比妈妈年纪大的女人的尊称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87487, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大妈", "is_correct": true, "explanation": "正确答案。“大妈”指年纪比妈妈大一点的女人，是对她的尊称。"}, {"text": "大骂", "is_correct": false, "explanation": "mà（第四声）与 mā（第一声）声调不同，意思是大声责骂。"}, {"text": "大巴", "is_correct": false, "explanation": "bā 与 mā 声母不同（b / m），意思是大型客车。"}, {"text": "大发", "is_correct": false, "explanation": "fā 与 mā 声母不同（f / m），意思是发大财、非常多。"}], "explanations": {"大妈": "正确答案。“大妈”指年纪比妈妈大一点的女人，是对她的尊称。", "大骂": "mà（第四声）与 mā（第一声）声调不同，意思是大声责骂。", "大巴": "bā 与 mā 声母不同（b / m），意思是大型客车。", "大发": "fā 与 mā 声母不同（f / m），意思是发大财、非常多。"}, "sentence_index": null, "correct_answer": "大妈"}, "level_3": {"options": [{"text": "大妈", "is_correct": true, "explanation": "正确。“大妈”是对年纪比妈妈大的女人的尊称，可以用来向她问路。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能被人问路。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会回答问路，“请问”的对象必须是人。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“请问”后面的称呼要指人，不能用“书包”。"}], "explanations": {"大妈": "正确。“大妈”是对年纪比妈妈大的女人的尊称，可以用来向她问路。", "桌子": "语义：桌子是家具，不能被人问路。", "小狗": "语义：小狗不会回答问路，“请问”的对象必须是人。", "书包": "搭配：“请问”后面的称呼要指人，不能用“书包”。"}, "sentence_index": 0, "correct_answer": "大妈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位大妈才三十多岁，很能干。", "explanation": "这里应该用〈阿姨〉。“大妈”指年纪比妈妈大的女人，三十多岁的人比妈妈年轻，不能叫大妈。"}, {"text": "那位大妈是我的表妹，比我小两岁。", "explanation": "这里应该用〈表妹〉。“大妈”指年长的女人，比我小的女孩不能叫大妈。"}, {"text": "那位大妈才比我大两岁，我们是大学同学。", "explanation": "这里应该用〈大姐〉。“大妈”指年纪比妈妈大的女人，只比我大两岁的大学同学不能叫大妈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大妈", "is_correct": true, "explanation": "正确。“大妈”是对年长女人的尊称，她可以笑着和我说话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会笑，也不会说话。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能笑着对人说话。"}, {"text": "盘子", "is_correct": false, "explanation": "配价：“说”的主语必须能发出话语，盘子不能充当。"}], "explanations": {"大妈": "正确。“大妈”是对年长女人的尊称，她可以笑着和我说话。", "石头": "语义：石头不会笑，也不会说话。", "窗户": "语义：窗户不能笑着对人说话。", "盘子": "配价：“说”的主语必须能发出话语，盘子不能充当。"}, "sentence_index": 6, "correct_answer": "大妈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位大妈的喉结很明显。", "explanation": "这里应该用〈大叔〉。“大妈”指年长的女人，喉结明显的男性要用〈大叔〉。"}, {"text": "那位大妈今年八岁，很喜欢画画。", "explanation": "这里应该用〈小妹妹〉。“大妈”指年长的女人，八岁的小女孩不能叫大妈。"}, {"text": "那位大妈留着一脸大胡子，很威严。", "explanation": "这里应该用〈老爷爷〉。“大妈”指年长的女人，留胡子的男性要用〈老爷爷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上，三只大妈在河边练太极。", "corrected_sentence": "早上，三位大妈在河边练太极。", "error_description": "“三只大妈”用错了量词。“只”用于动物，指人要用“位”或“个”，应为“三位大妈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位大妈们在河边洗衣服。", "corrected_sentence": "那位大妈在河边洗衣服。", "error_description": "“那位大妈们”错在“们”。“那位”指单独的一个人，不能与表示复数的“们”连用，应为“那位大妈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
