INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "大小介于大号与小号之间的型号。", "primary_collocate": null, "pronunciation": "zhōng hào", "ipa": "ʈʂʊŋ˥ xau˥˩", "syllable_count": 2, "sentences": [{"text": "大号太大，小号太小，我要中号。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服有大号、中号和小号。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中号比小号大，比大号小。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的中号卖完了。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把中号的箱子放在这里。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子不高，穿中号的。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的中号是四十码。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中号的价格在大号和小号之间。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只有大号和小号，没有中号。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要大号还是中号？", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大小排在大号与小号之间的型号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e50ef452-9f17-49b2-bfd5-efaaf3235ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中号", "is_correct": true, "explanation": "中号：大小介于大号与小号之间的型号，符合“我要”的选择。"}, {"text": "大号", "is_correct": false, "explanation": "语义：前一分句说“大号太大”，填“大号”会与之矛盾。"}, {"text": "小号", "is_correct": false, "explanation": "语义：前一分句说“小号太小”，填“小号”会与之矛盾。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：“我要”后接的应是尺码，西瓜不是尺码，搭配不当。"}], "explanations": {"中号": "中号：大小介于大号与小号之间的型号，符合“我要”的选择。", "大号": "语义：前一分句说“大号太大”，填“大号”会与之矛盾。", "小号": "语义：前一分句说“小号太小”，填“小号”会与之矛盾。", "西瓜": "搭配：“我要”后接的应是尺码，西瓜不是尺码，搭配不当。"}, "sentence_index": 0, "correct_answer": "中号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中号比大号大。", "explanation": "这里误把〈中号〉当成最大的号码；〈中号〉大小居中，不会比最大的号码还大。"}, {"text": "中号比小号还小。", "explanation": "这里误把〈中号〉当成最小的号码；〈中号〉大小居中，应比最小的号码大。"}, {"text": "中号比特大号还大。", "explanation": "这里误把〈中号〉当成超大的号码；〈中号〉大小居中，不会比超大的号码还大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中号", "is_correct": true, "explanation": "中号：这里指鞋的尺码，大小介于大号与小号之间。"}, {"text": "鞋带", "is_correct": false, "explanation": "语义：鞋带不是尺寸，“是四十码”说的应是尺码。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不能用“码”计量，不搭配“四十码”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不以码计，与“四十码”的说法冲突。"}], "explanations": {"中号": "中号：这里指鞋的尺码，大小介于大号与小号之间。", "鞋带": "语义：鞋带不是尺寸，“是四十码”说的应是尺码。", "颜色": "搭配：颜色不能用“码”计量，不搭配“四十码”。", "价格": "语义：价格不以码计，与“四十码”的说法冲突。"}, "sentence_index": 6, "correct_answer": "中号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中号和小号一样大。", "explanation": "这里误用了〈中号〉的尺寸义，把它当成与最小的号码相同；〈中号〉大小居中，比最小的号码大。"}, {"text": "中号是最大的号。", "explanation": "这里的〈中号〉不是最大的号，大号才是，三者顺序是大号、中号、小号。"}, {"text": "他的成绩在班里是中号。", "explanation": "这里应该用〈中等〉。中号只指衣服、鞋等物品的尺寸型号，评价成绩等水平应说“中等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换一台中号的衣服。", "corrected_sentence": "我想换一件中号的衣服。", "error_description": "量词错误：“衣服”应用量词“件”，“台”用于机器、电器等。正确说法是“一件中号的衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋的中号把是三十八码。", "corrected_sentence": "这双鞋的中号是三十八码。", "error_description": "多用了“把”：“把”是介词，这里不能用，应删去。正确说法是“这双鞋的中号是三十八码”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
