INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87491, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大数是很大很大的一个数目。", "primary_collocate": null, "pronunciation": "dà shù", "ipa": "ta˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "一后面有二十个零，这是个大数。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上写了一个大数。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一千万亿是大数，不容易读。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能读出这个大数吗？", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明问：“比大数还大的数有吗？”", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大数的零太多，数起来很麻烦。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先学会一百以内的数，再学大数。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的答案是个大数。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计算大数时，我习惯用计算器。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读大数时，要从右往左分组。", "target_word": "大数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很大很大的一个数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大数", "is_correct": true, "explanation": "正确：“大数”指很大的数目。"}, {"text": "大叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，“大叔”指中年男子。"}, {"text": "大暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，“大暑”是二十四节气之一。"}, {"text": "答数", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，“答数”指算术题的得数。"}], "explanations": {"大数": "正确：“大数”指很大的数目。", "大叔": "shū（第一声）与 shù（第四声）声调不同，“大叔”指中年男子。", "大暑": "shǔ（第三声）与 shù（第四声）声调不同，“大暑”是二十四节气之一。", "答数": "dá（第二声）与 dà（第四声）声调不同，“答数”指算术题的得数。"}, "sentence_index": null, "correct_answer": "大数"}, "level_3": {"options": [{"text": "大数", "is_correct": true, "explanation": "正确：“大数”指很大的数目，符合“一后面有二十个零”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是数目，不能说“这是个歌曲”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是数目，与“二十个零”的语境不符。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指外形，不是数目，不能用在这里。"}], "explanations": {"大数": "正确：“大数”指很大的数目，符合“一后面有二十个零”。", "歌曲": "语义：“歌曲”不是数目，不能说“这是个歌曲”。", "房子": "语义：“房子”不是数目，与“二十个零”的语境不符。", "外貌": "语义：“外貌”指外形，不是数目，不能用在这里。"}, "sentence_index": 0, "correct_answer": "大数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一双大数的鞋，穿着很舒服。", "explanation": "这里应该用〈大号〉。大数指很大的数目，不能用来指鞋子的尺码。"}, {"text": "0.5 是一个大数，很容易读。", "explanation": "这里应该用〈小数〉。“大数”指很大的数目，0.5 是小数，不能称为大数。"}, {"text": "8 是一个大数。", "explanation": "这里应该用〈整数〉。“大数”指很大的数目，8 很小，不能称为大数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大数", "is_correct": true, "explanation": "正确：“大数”是数学内容，承接“一百以内的数”。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“学”的对象是知识或技能，不能说“学厨房”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”不是数学内容，与“一百以内的数”不相符。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“学”不能接“火车”这类物品。"}], "explanations": {"大数": "正确：“大数”是数学内容，承接“一百以内的数”。", "厨房": "搭配：“学”的对象是知识或技能，不能说“学厨房”。", "体温": "语义：“体温”不是数学内容，与“一百以内的数”不相符。", "火车": "搭配：“学”不能接“火车”这类物品。"}, "sentence_index": 6, "correct_answer": "大数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只有五块钱，这笔钱是大数。", "explanation": "这里应该用〈小数目〉。大数指很大的数目，五块钱只是小数目，不能称为大数。"}, {"text": "这个号码只有两位，是大数。", "explanation": "这里应该用〈小数目〉。大数指很大的数目，只有两位的号码数目很小，不能称为大数。"}, {"text": "他身高一米八，是个大数。", "explanation": "这里的用法不对。大数指很大的数目，身高一米八是身体的高度，不是一个很大的数目，不能称为大数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在本子上写下了一条大数。", "corrected_sentence": "他在本子上写下了一个大数。", "error_description": "量词错误：“大数”是数目，应说“一个大数”，不能说“一条大数”。“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
