INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "与「除了」搭配使用，表示把某个人或事物排除在外，不包括在内。", "primary_collocate": null, "pronunciation": "yǐ wài", "ipa": "i˨˩˦ wai˥˩", "syllable_count": 2, "sentences": [{"text": "除了苹果以外，我什么都吃。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了他以外，大家都来了。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了中文以外，她还会说法语。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了星期天以外，商店天天开门。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了这本书以外，我还买了一支笔。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了猫以外，我家没有别的动物。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了我以外，没有人知道这件事。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了打球以外，他还喜欢游泳。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了工作以外，她还要照顾孩子。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了地铁以外，你还可以坐公共汽车。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "与“除了”搭配，指出某个范围之外的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e50ef452-9f17-49b2-bfd5-efaaf3235ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以内", "is_correct": false, "explanation": "语义：以内表示范围之内，与“除了”引出被排除对象的意思不符。"}, {"text": "之下", "is_correct": false, "explanation": "搭配：之下不能用在“除了……”的排除结构里。"}, {"text": "之前", "is_correct": false, "explanation": "语义：之前表示时间先后，不能引出被排除的对象。"}, {"text": "以外", "is_correct": true, "explanation": "正确。“除了……以外”表示排除某个对象，与句意相符。"}], "explanations": {"以内": "语义：以内表示范围之内，与“除了”引出被排除对象的意思不符。", "之下": "搭配：之下不能用在“除了……”的排除结构里。", "之前": "语义：之前表示时间先后，不能引出被排除的对象。", "以外": "正确。“除了……以外”表示排除某个对象，与句意相符。"}, "sentence_index": 0, "correct_answer": "以外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "除了下雨以外，我们才会取消比赛。", "explanation": "这里应该用〈除非〉。除了……以外表示排除，表示“只有在某种条件下”要用除非。"}, {"text": "除了他以外，他也来了。", "explanation": "“除了……以外”排除的对象不能同时是句子陈述的对象，他既被排除又来了，逻辑上自相矛盾。"}, {"text": "除了苹果以外，我只吃苹果。", "explanation": "“除了苹果以外”已经排除了苹果，后面又说只吃苹果，二者互相抵触。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之后", "is_correct": false, "explanation": "语义：之后表示时间先后，不能引出被排除的人。"}, {"text": "之中", "is_correct": false, "explanation": "搭配：之中指在某个范围里面，不能与“除了我”组成排除结构。"}, {"text": "上面", "is_correct": false, "explanation": "语义：上面指位置在高处，与排除的意思无关。"}, {"text": "以外", "is_correct": true, "explanation": "正确。“除了我以外”表示排除我，与句意相符。"}], "explanations": {"之后": "语义：之后表示时间先后，不能引出被排除的人。", "之中": "搭配：之中指在某个范围里面，不能与“除了我”组成排除结构。", "上面": "语义：上面指位置在高处，与排除的意思无关。", "以外": "正确。“除了我以外”表示排除我，与句意相符。"}, "sentence_index": 6, "correct_answer": "以外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "关于地铁以外，你还可以坐公共汽车。", "explanation": "这里应该用〈除了〉。“关于”表示涉及的对象，不能和“以外”组成排除结构；表示排除要说“除了地铁以外”。"}, {"text": "只有地铁停运以外，你才可以坐公共汽车。", "explanation": "这里应该用〈除非〉。“只有……才”表示条件，不能与“以外”组合；以外表示排除时，前面要用除了。"}, {"text": "除了地铁以外，你只能坐地铁。", "explanation": "「除了地铁以外」已经排除了地铁，后面又说只能坐地铁，二者互相抵触。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除了跑步，以外她还喜欢游泳。", "corrected_sentence": "除了跑步以外，她还喜欢游泳。", "error_description": "“以外”位置错误。它应紧接被排除的成分，不能放在逗号之后，正确说法是“除了跑步以外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除了老师以外了，没有人知道这件事。", "corrected_sentence": "除了老师以外，没有人知道这件事。", "error_description": "“以外”后面多加了“了”。“了”是动态助词，不能接在表示排除的“以外”后面；正确说法是“除了老师以外”，去掉“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
