INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雨量大、雨势猛的雨。", "primary_collocate": null, "pronunciation": "dà yǔ", "ipa": "ta˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "天气预报说明天有大雨。", "target_word": "大雨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大雨把路面都淹了。", "target_word": "大雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区连下三天大雨，河水涨得很高。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气象台提醒大家，今晚有大雨，请少出门。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨打在窗户上，声音特别大。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是今年夏天最猛的一场大雨。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨使河水涨得很高，大家都很担心。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大雨来得突然，街上的人四处躲雨。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车遇到大雨时，要打开灯慢慢走。", "target_word": "大雨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民盼着一场大雨，好让干了很久的地喝足水。", "target_word": "大雨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场大雨", "label": "量词"}], "register": "中性", "sense_fingerprint": "雨量大、雨势猛的雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87496, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大雨", "is_correct": true, "explanation": "正确答案：大雨（dà yǔ）指雨量大、雨势猛的雨。"}, {"text": "大鱼", "is_correct": false, "explanation": "大鱼（dàyú）与大雨（dà yǔ）第二音节声调不同，意思是大的鱼。"}, {"text": "打鱼", "is_correct": false, "explanation": "打鱼（dǎyú）与大雨（dà yǔ）两个音节声调都不同，意思是捕鱼。"}, {"text": "大于", "is_correct": false, "explanation": "大于（dàyú）与大雨（dà yǔ）第二音节声调不同，意思是比……大。"}], "explanations": {"大雨": "正确答案：大雨（dà yǔ）指雨量大、雨势猛的雨。", "大鱼": "大鱼（dàyú）与大雨（dà yǔ）第二音节声调不同，意思是大的鱼。", "打鱼": "打鱼（dǎyú）与大雨（dà yǔ）两个音节声调都不同，意思是捕鱼。", "大于": "大于（dàyú）与大雨（dà yǔ）第二音节声调不同，意思是比……大。"}, "sentence_index": null, "correct_answer": "大雨"}, "level_3": {"options": [{"text": "大雨", "is_correct": true, "explanation": "“天气预报说明天有……”后接天气现象，大雨符合预报内容。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是地壳运动，不属于天气预报的内容。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不是天气现象，与天气预报的内容不搭。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“有”后接的是天气现象，不能接眼镜，句子不通。"}], "explanations": {"大雨": "“天气预报说明天有……”后接天气现象，大雨符合预报内容。", "地震": "语义：地震是地壳运动，不属于天气预报的内容。", "钱": "语义：钱不是天气现象，与天气预报的内容不搭。", "眼镜": "搭配：“有”后接的是天气现象，不能接眼镜，句子不通。"}, "sentence_index": 0, "correct_answer": "大雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天下午下了一把大雨。", "explanation": "这里应该用〈场〉。量词“把”用于有柄的器具，不用于雨。"}, {"text": "雨势很弱，大雨下得很轻。", "explanation": "这里应该用〈小雨〉。雨势弱、雨量少要说小雨，“大雨”指雨量大、雨势猛。"}, {"text": "山上积了厚厚一层大雨。", "explanation": "这里应该用〈雪〉。雨不会积成一层，积起来的是雪，应说“山上积了厚厚一层雪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大雨", "is_correct": true, "explanation": "大雨造成河水上涨，“使河水涨得很高”符合句意。"}, {"text": "奶茶", "is_correct": false, "explanation": "语义：奶茶不会使河水上涨，与“涨得很高”矛盾。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是照明用品，无法使河水上涨。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不能使河水上涨，与“使河水涨得很高”的句意矛盾。"}], "explanations": {"大雨": "大雨造成河水上涨，“使河水涨得很高”符合句意。", "奶茶": "语义：奶茶不会使河水上涨，与“涨得很高”矛盾。", "台灯": "语义：台灯是照明用品，无法使河水上涨。", "教室": "语义：教室不能使河水上涨，与“使河水涨得很高”的句意矛盾。"}, "sentence_index": 6, "correct_answer": "大雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台风过境，屋外刮起了大雨。", "explanation": "这里应该用〈下〉。雨用“下”，“刮起”用于风，不说“刮起了大雨”。"}, {"text": "这场大雨很轻，只打湿了一点头发。", "explanation": "这里应该用〈小雨〉。雨量少、雨势弱要说小雨，“大雨”指雨量大、雨势猛。"}, {"text": "农民用两桶大雨浇地。", "explanation": "这里应该用〈水〉。大雨是降水，不用“桶”计量，应说“两桶水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天中午下了一条大雨，学校的操场都积满了水。", "corrected_sentence": "今天中午下了一场大雨，学校的操场都积满了水。", "error_description": "量词错误：“大雨”的量词应为“场”，“条”用于河流、道路等，不用于雨，应说“一场大雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个大雨使河水涨得很高，很多人都很担心。", "corrected_sentence": "一场大雨使河水涨得很高，很多人都很担心。", "error_description": "量词错误：“大雨”的量词应为“场”，“个”不用于雨。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤出", "is_correct": true, "explanation": "正确：“撤出”与“占领”相对，指离开原先控制的地方。"}, {"text": "学习", "is_correct": false, "explanation": "无反义关系：“学习”指获取知识，与“占领”不构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”是一种休闲活动，与“占领”不构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”是动脑活动，与“占领”无关。"}], "correct_answer": "撤出", "explanations": {"撤出": "正确：“撤出”与“占领”相对，指离开原先控制的地方。", "学习": "无反义关系：“学习”指获取知识，与“占领”不构成反义。", "散步": "无反义关系：“散步”是一种休闲活动，与“占领”不构成反义。", "思考": "无反义关系：“思考”是动脑活动，与“占领”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
