INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女郎是年纪轻轻的女孩子。", "primary_collocate": null, "pronunciation": "nǚ láng", "ipa": "ny˨˩˦ lɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "河边坐着一位年轻的女郎。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位年轻的女郎正在店里给客人倒茶。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一张女郎的照片。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个骑自行车的女郎是我的邻居。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位穿白衣服的女郎走进了教室。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里有个女郎在等朋友。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女郎很喜欢旅行，什么都想试一试。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女郎们在草地上跳舞。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女郎戴着一顶大帽子。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说那位女郎的声音像小鸟一样好听。", "target_word": "女郎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "年纪轻轻的女孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女郎", "is_correct": true, "explanation": "正确：“女郎”指年纪轻轻的女孩子，可以“坐”在河边，量词“位”也合适。"}, {"text": "云", "is_correct": false, "explanation": "语义：“云”不会“坐”在河边，语义不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”的量词是“把”，且不能说“年轻的椅子”，“位”不能修饰它。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“坐”着，也不会“年轻”，语义不通。"}], "explanations": {"女郎": "正确：“女郎”指年纪轻轻的女孩子，可以“坐”在河边，量词“位”也合适。", "云": "语义：“云”不会“坐”在河边，语义不通。", "椅子": "搭配：“椅子”的量词是“把”，且不能说“年轻的椅子”，“位”不能修饰它。", "石头": "语义：石头不会“坐”着，也不会“年轻”，语义不通。"}, "sentence_index": 0, "correct_answer": "女郎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个女郎今年八十岁了。", "explanation": "这里应该用〈老奶奶〉。“女郎”指年纪轻轻的女孩子，不能用于八十岁的老人。"}, {"text": "那位女郎是个小伙子。", "explanation": "这里应该用〈男子〉。“女郎”指年纪轻轻的女孩子，不能用于男性。"}, {"text": "那个女郎还在学走路。", "explanation": "这里应该用〈小女孩〉。“女郎”指年纪轻轻的女孩子，不能用于还在学走路的幼儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女郎", "is_correct": true, "explanation": "正确：“女郎”指年轻的女子，可以用“位”，也会喜欢旅行、什么都想试。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”不会“想试一试”，语义不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不会“想试一试”，句子意思不通。"}, {"text": "风", "is_correct": false, "explanation": "搭配：“风”不能用量词“位”，也不会喜欢旅行，语义不通。"}], "explanations": {"女郎": "正确：“女郎”指年轻的女子，可以用“位”，也会喜欢旅行、什么都想试。", "西瓜": "语义：“西瓜”不会“想试一试”，语义不通。", "电脑": "语义：“电脑”不会“想试一试”，句子意思不通。", "风": "搭配：“风”不能用量词“位”，也不会喜欢旅行，语义不通。"}, "sentence_index": 6, "correct_answer": "女郎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位女郎是我的伯伯。", "explanation": "这里应该用〈男士〉。“女郎”指年纪轻轻的女孩子，不能用于男性长辈。"}, {"text": "那个女郎的孙子已经上大学了。", "explanation": "这里应该用〈老奶奶〉。“女郎”指年纪轻轻的女孩子，不能用于有孙子的人。"}, {"text": "那个女郎在养老院里住了二十年。", "explanation": "这里应该用〈老人〉。“女郎”指年纪轻轻的女孩子，不能用于在养老院住了二十年的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆门口站着一只年轻的女郎。", "corrected_sentence": "图书馆门口站着一位年轻的女郎。", "error_description": "错误：“一只年轻的女郎”；正确：“一位年轻的女郎”。“只”用于动物等，女郎指人，应该用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那把女郎刚从火车上下来。", "corrected_sentence": "那位女郎刚从火车上下来。", "error_description": "错误：“那把女郎”；正确：“那位女郎”。“把”用于有柄的东西，女郎指人，应该用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
