INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87501, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "作战是两边的人互相打仗。", "primary_collocate": null, "pronunciation": "zuò zhàn", "ipa": "tsuo˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "两边的人在山上作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家已经作战很多年了。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了土地互相作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时当过兵，在外面作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队士兵在田野里作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方不想再作战，想要和平。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们在大雨中作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国因为边界问题又开始作战了。", "target_word": "作战", "complexity_tier": "T3", "furigana": "liǎng guó yīn wèi biān jiè wèn tí yòu kāi shǐ zuò zhàn le", "sentence_source": "generated"}, {"text": "作战的时候，天气很冷。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那两个国家为什么要作战呢？", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作战了", "label": "体标"}, {"form": "作戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作战：双方的人互相打仗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作战", "is_correct": true, "explanation": "正确：作战指双方的人互相打仗，与句意相符。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：长高说的是身高的变化，不能描述双方互相打仗。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是婚姻行为，与双方互相打仗的情境不符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休是离开工作岗位，不能用于互相打仗的场景。"}], "explanations": {"作战": "正确：作战指双方的人互相打仗，与句意相符。", "长高": "体貌：长高说的是身高的变化，不能描述双方互相打仗。", "结婚": "语义：结婚是婚姻行为，与双方互相打仗的情境不符。", "退休": "语义：退休是离开工作岗位，不能用于互相打仗的场景。"}, "sentence_index": 0, "correct_answer": "作战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国在边境作战，双方都没有开火。", "explanation": "这里应该用〈对峙〉。作战指双方实际交战，而「对峙」只是相持不打，与「没有开火」矛盾。"}, {"text": "工人们在工厂里作战，每天生产很多零件。", "explanation": "这里应该用〈生产〉。“作战”指交战，不指生产劳动。"}, {"text": "他在商店里买了一把作战。", "explanation": "这里应该用〈雨伞〉。“作战”指交战，不是可以买的东西，也不能用量词「把」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作战", "is_correct": true, "explanation": "正确：作战是士兵在雨中交战，与句意相符。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：生锈说的是金属，士兵不会生锈，与句意不符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：出版指印刷发行，与士兵在大雨中的情境无关。"}, {"text": "发挥", "is_correct": false, "explanation": "配价：发挥需要宾语，单用「在大雨中发挥」不成立。"}], "explanations": {"作战": "正确：作战是士兵在雨中交战，与句意相符。", "生锈": "语义：生锈说的是金属，士兵不会生锈，与句意不符。", "出版": "语义：出版指印刷发行，与士兵在大雨中的情境无关。", "发挥": "配价：发挥需要宾语，单用「在大雨中发挥」不成立。"}, "sentence_index": 6, "correct_answer": "作战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车很会作战。", "explanation": "这里应该用〈行驶〉。作战的主体应是军队或战士，汽车不能作战，开车应说「行驶」。"}, {"text": "他每天在书店里作战，卖书很快。", "explanation": "这里应该用〈卖〉。作战只指两边的人互相打仗，不用于卖东西。"}, {"text": "这位老师每天在教室里作战。", "explanation": "这里应该用〈上课〉。作战只指军事上的交战，不能用来指教学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国因为边界问题作战的很久。", "corrected_sentence": "两国因为边界问题作战了很久。", "error_description": "错误：「作战」后带时量补语时，动态助词应为「了」，写成「作战的很久」不通。正确形式：「作战了很久」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国作战的很激烈。", "corrected_sentence": "两国作战得很激烈。", "error_description": "错误：补语标记应为「得」，写成「的」不通。「作战」后接程度补语须用「得」。正确形式：「作战得很激烈」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进行战斗；军队之间交战。", "primary_collocate": null, "pronunciation": "zuò zhàn", "ipa": "tsuo˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "两国军队在山里作战了三天。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们勇敢地作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队在夜里开始作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海上作战，非常辛苦。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支部队很会作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，我们要马上作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们为了保护国家而作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军让大家准备好，明天作战。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两军在河边作战，打得很激烈。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雪地里作战很难。", "target_word": "作战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作战了", "label": "体标"}, {"form": "作戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作战：军队进行战斗、交战", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作战", "is_correct": true, "explanation": "正确：作战指军队之间交战，与「两国军队在山里」和「三天」的语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，与军队交战的情境不符。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：长高说的是身体长大，不能用于描述军队的行动。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是个人的婚姻行为，与两国军队的情境不符。"}], "explanations": {"作战": "正确：作战指军队之间交战，与「两国军队在山里」和「三天」的语境相符。", "散步": "语义：散步是悠闲的活动，与军队交战的情境不符。", "长高": "体貌：长高说的是身体长大，不能用于描述军队的行动。", "结婚": "语义：结婚是个人的婚姻行为，与两国军队的情境不符。"}, "sentence_index": 0, "correct_answer": "作战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在饭店里作战，端菜很快。", "explanation": "这里应该用〈端〉。“作战”指交战，不指端菜。"}, {"text": "我们学校的作战很好，老师教得认真。", "explanation": "这里应该用〈教学〉。“作战”指交战，不指学校的教学工作。"}, {"text": "他把作战放进了书包里。", "explanation": "这里应该用〈书〉。“作战”指交战，不是可以放进书包的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作战", "is_correct": true, "explanation": "正确：作战是军队为保护国家而交战，与句意相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：旅游是休闲活动，与「为了保护国家」的目的相悖。"}, {"text": "发挥", "is_correct": false, "explanation": "配价：发挥需要宾语（如「发挥作用」），单用「而发挥」不成立。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与保护国家的目的无关，句子不通。"}], "explanations": {"作战": "正确：作战是军队为保护国家而交战，与句意相符。", "旅游": "语义：旅游是休闲活动，与「为了保护国家」的目的相悖。", "发挥": "配价：发挥需要宾语（如「发挥作用」），单用「而发挥」不成立。", "跳舞": "语义：跳舞与保护国家的目的无关，句子不通。"}, "sentence_index": 6, "correct_answer": "作战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车每天在路上作战，很辛苦。", "explanation": "这里应该用〈行驶〉。作战的主体应是军队或战士，汽车不能作战，开车应说「行驶」。"}, {"text": "他每天在银行里作战，办理存款很快。", "explanation": "这里应该用〈办理〉。作战只指军事上的交战，不用于办理业务。"}, {"text": "这位老师每天在教室里作战，讲课很认真。", "explanation": "这里应该用〈讲课〉。作战只指军事上的交战，不能用来指上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军队把夜里作战，非常危险。", "corrected_sentence": "军队在夜里作战，非常危险。", "error_description": "错误：「作战」是不及物动词，不能用「把」字结构引出「夜里」。「在夜里」应作状语放在「作战」之前。正确形式：「在夜里作战」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在海上作战得了很辛苦。", "corrected_sentence": "他们在海上作战得很辛苦。", "error_description": "错误：补语标记「得」后不能加「了」，写成「作战得了很辛苦」是错误的。正确形式：「作战得很辛苦」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
