INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87504, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奶粉是用牛奶做成的白色粉末。用水冲一冲就能喝。", "primary_collocate": null, "pronunciation": "nǎi fěn", "ipa": "naɪ˨˩˦ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈给宝宝冲了一杯奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这罐奶粉是用牛奶做成的。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶粉用热水一冲就能喝。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的奶粉快用完了，要去超市买。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上喝一杯用奶粉冲的奶。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柜子里放着两袋奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶粉是白色的粉末，不是糖。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行时，奶奶带着奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝饿了，快去冲点奶粉吧。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶粉要放在干燥的地方。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罐", "label": "量词"}, {"form": "袋", "label": "量词"}, {"form": "婴儿奶粉", "label": "复合"}], "register": "中性", "sense_fingerprint": "牛奶做成的白色粉末，冲水可喝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奶粉", "is_correct": true, "explanation": "正确。“冲”的对象是用水调成饮品的粉末，奶粉符合“冲了一杯”的语境。"}, {"text": "酱油", "is_correct": false, "explanation": "搭配：“冲了一杯”要求能冲成饮品的粉末或固体，酱油是液体调料，不能这样说。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：“冲”和“一杯”要求能溶于水、做成饮品的东西，面粉不能冲成一杯。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：饼干是固体食品，不能用“冲”做成一杯饮料。"}], "explanations": {"奶粉": "正确。“冲”的对象是用水调成饮品的粉末，奶粉符合“冲了一杯”的语境。", "酱油": "搭配：“冲了一杯”要求能冲成饮品的粉末或固体，酱油是液体调料，不能这样说。", "面粉": "搭配：“冲”和“一杯”要求能溶于水、做成饮品的东西，面粉不能冲成一杯。", "饼干": "搭配：饼干是固体食品，不能用“冲”做成一杯饮料。"}, "sentence_index": 0, "correct_answer": "奶粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只奶粉。", "explanation": "这里应该用〈罐〉。奶粉按罐或袋计量，“只”用于动物等，不用于奶粉这类包装食品。"}, {"text": "妈妈用奶粉做了一碗面条。", "explanation": "这里应该用〈面粉〉。面条是用面粉做的；奶粉是用牛奶制成的，不能拿来做面条。"}, {"text": "我每天喝一片奶粉。", "explanation": "这里应该用〈罐〉或〈袋〉。奶粉不用“片”计量，“片”用于薄片状的东西，如药片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奶粉", "is_correct": true, "explanation": "正确。奶粉是白色粉末，句中说它不是糖，符合语境。"}, {"text": "咖啡粉", "is_correct": false, "explanation": "体貌：咖啡粉是棕色的，与句中“白色”的描述相反。"}, {"text": "茶叶", "is_correct": false, "explanation": "语义：茶叶是叶片，不是粉末，与“白色的粉末”不符。"}, {"text": "冰糖", "is_correct": false, "explanation": "语义：冰糖本身就是糖，与“不是糖”直接矛盾。"}], "explanations": {"奶粉": "正确。奶粉是白色粉末，句中说它不是糖，符合语境。", "咖啡粉": "体貌：咖啡粉是棕色的，与句中“白色”的描述相反。", "茶叶": "语义：茶叶是叶片，不是粉末，与“白色的粉末”不符。", "冰糖": "语义：冰糖本身就是糖，与“不是糖”直接矛盾。"}, "sentence_index": 6, "correct_answer": "奶粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把奶粉挂在墙上当装饰。", "explanation": "这里的用法不对。奶粉是用来冲调饮用的食品，不能当作墙上的装饰品。"}, {"text": "我用奶粉擦桌子，很干净。", "explanation": "这里的用法不对。奶粉是食品，不是清洁用品，不能用来擦桌子。"}, {"text": "我每天用奶粉给花浇水。", "explanation": "这里的用法不对。奶粉要用水冲成奶来喝，是食品，不能用来给花浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给宝宝买了两个奶粉。", "corrected_sentence": "她给宝宝买了两罐奶粉。", "error_description": "错误：量词“个”用错。奶粉应用“罐”或“袋”计量，应改为“两罐奶粉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的孩子每天喝一块奶粉。", "corrected_sentence": "他的孩子每天喝一袋奶粉。", "error_description": "错误：量词“块”用错。奶粉应用“罐”或“袋”计量，应改为“一袋奶粉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
