INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87505, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "将牛奶或羊奶脱水干燥后制成的粉末，加水冲调后可饮用。", "primary_collocate": null, "pronunciation": "nǎi fěn", "ipa": "naɪ˨˩˦ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种奶粉是用羊奶制成的。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加水冲调后，奶粉就可以喝了。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让宝宝换了另一种奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的奶粉有牛奶的，也有羊奶的。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶粉是牛奶脱水干燥后做成的。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一罐进口奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开罐后的奶粉要尽快用完。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人也可以喝高钙奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶粉冲得太浓，宝宝会不舒服。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把鲜奶加工成了奶粉。", "target_word": "奶粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罐", "label": "量词"}, {"form": "袋", "label": "量词"}, {"form": "婴儿奶粉", "label": "复合"}], "register": "中性", "sense_fingerprint": "牛奶或羊奶脱水干燥制成的粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奶粉", "is_correct": true, "explanation": "正确。奶粉是用羊奶脱水制成的，句中说“用羊奶制成的”，符合语境。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是用小麦做的，不是用羊奶制成的，与句中的材料冲突。"}, {"text": "豆浆", "is_correct": false, "explanation": "语义：豆浆是用豆子做的，不能用羊奶制成，与句中的材料冲突。"}, {"text": "方便面", "is_correct": false, "explanation": "搭配：方便面是面条类食品，“羊奶”不能作它的原料，搭配不当。"}], "explanations": {"奶粉": "正确。奶粉是用羊奶脱水制成的，句中说“用羊奶制成的”，符合语境。", "面粉": "语义：面粉是用小麦做的，不是用羊奶制成的，与句中的材料冲突。", "豆浆": "语义：豆浆是用豆子做的，不能用羊奶制成，与句中的材料冲突。", "方便面": "搭配：方便面是面条类食品，“羊奶”不能作它的原料，搭配不当。"}, "sentence_index": 0, "correct_answer": "奶粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一块奶粉。", "explanation": "这里应该用〈罐〉。块多用于块状的东西，奶粉要按罐或袋计量。"}, {"text": "妈妈把奶粉打发，做了一个蛋糕的裱花。", "explanation": "这里应该用〈奶油〉。奶油可以打发后用来裱花；奶粉是干燥的粉末，不能打发。"}, {"text": "他把奶粉当成墨水，用来写字。", "explanation": "这里的用法不对。奶粉是食品，不能当墨水用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奶粉", "is_correct": true, "explanation": "正确。开罐后的应是奶粉，要尽快用完，符合语境。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包不是罐装食品，不能说“开罐后的面包”。"}, {"text": "砖块", "is_correct": false, "explanation": "搭配：砖块是建材，不装在罐里，“开罐后”和“尽快用完”都说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能开罐，也谈不上“尽快用完”，与句中语境冲突。"}], "explanations": {"奶粉": "正确。开罐后的应是奶粉，要尽快用完，符合语境。", "面包": "搭配：面包不是罐装食品，不能说“开罐后的面包”。", "砖块": "搭配：砖块是建材，不装在罐里，“开罐后”和“尽快用完”都说不通。", "汽车": "语义：汽车不能开罐，也谈不上“尽快用完”，与句中语境冲突。"}, "sentence_index": 6, "correct_answer": "奶粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈炒菜时，用奶粉代替盐来调味。", "explanation": "这里的用法不对。奶粉是冲调饮用的乳制品，不能代替盐用来调味。"}, {"text": "我每天用奶粉刷牙。", "explanation": "这里的用法不对。奶粉是食品，不能用来刷牙。"}, {"text": "他把奶粉当成面条下锅煮。", "explanation": "这里的用法不对。奶粉要用水冲调，不是用来像面条一样下锅煮的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
