INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全民是一个国家里所有的人。", "primary_collocate": null, "pronunciation": "quán mín", "ipa": "tɕʰɥɛn˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "这次比赛，全民都在看电视。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步是全民都能做的运动。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事全民都知道了。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全民都希望经济早日好转。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防疫，全民都要戴口罩。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队赢了冠军，全民都在庆祝。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏太有名了，几乎全民都玩过。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全民看着电视，等着开幕式开始。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，全民都想帮助灾区的人。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这是全民的事，不是一个人的事。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个国家里所有的人（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87507, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全民", "is_correct": true, "explanation": "正确。全民指一国里所有的人，读 quán mín。"}, {"text": "全名", "is_correct": false, "explanation": "míng 与 mín 韵尾不同（ng 与 n），意思是全名，指完整的姓名。"}, {"text": "全面", "is_correct": false, "explanation": "miàn（第四声）与 mín（第二声）韵母和声调都不同，意思是全面、各个方面。"}, {"text": "全棉", "is_correct": false, "explanation": "mián 比 mín 多一个元音 a，意思是全棉，指纯棉织物。"}, {"text": "全免", "is_correct": false, "explanation": "miǎn（第三声）与 mín 韵母和声调不同，意思是全部免除（费用）。"}], "explanations": {"全民": "正确。全民指一国里所有的人，读 quán mín。", "全名": "míng 与 mín 韵尾不同（ng 与 n），意思是全名，指完整的姓名。", "全面": "miàn（第四声）与 mín（第二声）韵母和声调都不同，意思是全面、各个方面。", "全棉": "mián 比 mín 多一个元音 a，意思是全棉，指纯棉织物。", "全免": "miǎn（第三声）与 mín 韵母和声调不同，意思是全部免除（费用）。"}, "sentence_index": null, "correct_answer": "全民"}, "level_3": {"options": [{"text": "全民", "is_correct": true, "explanation": "正确。全民指一国所有人，比赛时全国人都在看电视。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有视觉和兴趣，不会在比赛时看电视。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“空调”不能作“看电视”的主体，与动词搭配不当。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不会在比赛时看电视，这里的主体应是人。"}], "explanations": {"全民": "正确。全民指一国所有人，比赛时全国人都在看电视。", "石头": "语义：石头没有视觉和兴趣，不会在比赛时看电视。", "空调": "搭配：“空调”不能作“看电视”的主体，与动词搭配不当。", "老虎": "语义：老虎不会在比赛时看电视，这里的主体应是人。"}, "sentence_index": 0, "correct_answer": "全民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的全民都在加班。", "explanation": "这里应该用〈员工〉。全民指全国人民，不能用来指一家公司的人。"}, {"text": "全民都在院子里聊天。", "explanation": "这里应该用〈邻居〉。全民的范围是全国，只有几户人家的人应说〈邻居〉。"}, {"text": "全民都在柜台后面忙着。", "explanation": "这里应该用〈大家〉。全民指一国全体人民，柜台后的人应说〈大家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全民", "is_correct": true, "explanation": "正确。全民指一国所有人，符合“几乎全民都玩过”的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会玩游戏，这里的主体应是人。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是游戏的玩家，不能“玩过”游戏。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“玩过”需要能玩游戏的主体，“桌子”与“玩过”搭配不当。"}], "explanations": {"全民": "正确。全民指一国所有人，符合“几乎全民都玩过”的语境。", "冰箱": "语义：冰箱不会玩游戏，这里的主体应是人。", "空气": "语义：空气不是游戏的玩家，不能“玩过”游戏。", "桌子": "搭配：“玩过”需要能玩游戏的主体，“桌子”与“玩过”搭配不当。"}, "sentence_index": 6, "correct_answer": "全民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全民都在地里干活。", "explanation": "这里应该用〈农民〉。全民指一国所有人，不能用来指在地里干活的人。"}, {"text": "全民在训练场上跑步。", "explanation": "这里应该用〈士兵〉。全民指全国人民，训练场上的队伍应说〈士兵〉。"}, {"text": "全民在教室里上课。", "explanation": "这里应该用〈学生〉。全民指全国人民，不能用来指某间教室里的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末所有全民都可以去公园散步。", "corrected_sentence": "周末全民都可以去公园散步。", "error_description": "错误在“所有”。“全民”本身已包含全体的意思，前面再加“所有”语义重复；应说“全民都可以……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "球队赢了冠军，全民们都很兴奋。", "corrected_sentence": "球队赢了冠军，全民都很兴奋。", "error_description": "错误在“们”。“全民”已指全体人民，是集合名词，不能再加复数后缀“们”；应说“全民都很兴奋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
