INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国全体的人民。", "primary_collocate": null, "pronunciation": "quán mín", "ipa": "tɕʰɥɛn˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "春节是全民的节日。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法律关系到全民的利益。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要为全民提供医疗保障。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全民都关心这次选举的结果。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育是全民的权利。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境是全民的责任。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息让全民都很高兴。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的发展要靠全民的努力。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家公园属于全民，不属于个人。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆节是全民放假的日子。", "target_word": "全民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个国家全体的人民（正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87508, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全民", "is_correct": true, "explanation": "正确。全民指一国全体人民，读 quán mín。"}, {"text": "全名", "is_correct": false, "explanation": "míng 与 mín 韵尾不同（ng 与 n），意思是全名，指完整的姓名。"}, {"text": "全面", "is_correct": false, "explanation": "miàn（第四声）与 mín（第二声）韵母和声调都不同，意思是全面、各个方面。"}, {"text": "全棉", "is_correct": false, "explanation": "mián 比 mín 多一个元音 a，意思是全棉，指纯棉织物。"}, {"text": "全免", "is_correct": false, "explanation": "miǎn（第三声）与 mín 韵母和声调不同，意思是全部免除（费用）。"}], "explanations": {"全民": "正确。全民指一国全体人民，读 quán mín。", "全名": "míng 与 mín 韵尾不同（ng 与 n），意思是全名，指完整的姓名。", "全面": "miàn（第四声）与 mín（第二声）韵母和声调都不同，意思是全面、各个方面。", "全棉": "mián 比 mín 多一个元音 a，意思是全棉，指纯棉织物。", "全免": "miǎn（第三声）与 mín 韵母和声调不同，意思是全部免除（费用）。"}, "sentence_index": null, "correct_answer": "全民"}, "level_3": {"options": [{"text": "全民", "is_correct": true, "explanation": "正确。全民指全国人民，春节是全民共享的节日。"}, {"text": "病人", "is_correct": false, "explanation": "语义：春节是全民共享的节日，不能说只属于病人。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：春节是中国的传统节日，不能说只属于外国人。"}, {"text": "个人", "is_correct": false, "explanation": "搭配：“个人”指单一的人，与“节日”面向群体的搭配不合，应说“全民的节日”。"}], "explanations": {"全民": "正确。全民指全国人民，春节是全民共享的节日。", "病人": "语义：春节是全民共享的节日，不能说只属于病人。", "外国人": "语义：春节是中国的传统节日，不能说只属于外国人。", "个人": "搭配：“个人”指单一的人，与“节日”面向群体的搭配不合，应说“全民的节日”。"}, "sentence_index": 0, "correct_answer": "全民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全民同学都到了。", "explanation": "这里应该用〈全体〉。全民指一国全体人民，不能用来指一个班的同学。"}, {"text": "会场里的全民都在鼓掌。", "explanation": "这里应该用〈群众〉。全民指一国全体人民，会场里的人应说〈群众〉。"}, {"text": "这个小区的全民都很友好。", "explanation": "这里应该用〈居民〉。全民指全国人民，不能用来指某个小区的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全民", "is_correct": true, "explanation": "正确。全民指全国人民，“让全民都很高兴”符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不会因为好消息而“都很高兴”。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不会有高兴的感受，这里的主体应是有感情的人。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能作“高兴”的主体，与“让……都很高兴”搭配不当。"}], "explanations": {"全民": "正确。全民指全国人民，“让全民都很高兴”符合句意。", "石头": "语义：石头没有感情，不会因为好消息而“都很高兴”。", "机器": "语义：机器不会有高兴的感受，这里的主体应是有感情的人。", "空气": "搭配：“空气”不能作“高兴”的主体，与“让……都很高兴”搭配不当。"}, "sentence_index": 6, "correct_answer": "全民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "音乐厅里的全民都站起来鼓掌。", "explanation": "这里应该用〈听众〉。全民指一国全体人民，音乐厅里的人应说〈听众〉。"}, {"text": "车里的全民都系好了安全带。", "explanation": "这里应该用〈乘客〉。全民指一国全体人民，车里的人应说〈乘客〉。"}, {"text": "全民在景区里排队。", "explanation": "这里应该用〈游客〉。全民的范围是全国人民，景区里的人应说〈游客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节约用水是全民们的责任。", "corrected_sentence": "节约用水是全民的责任。", "error_description": "错误在“全民们”。“全民”本身已指全体人民，是集合名词，不能再加复数后缀“们”；应说“全民的责任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个全民都应该遵守交通规则。", "corrected_sentence": "全民都应该遵守交通规则。", "error_description": "错误在“每个”。“全民”是集合名词，指全体人民，不能受“每个”修饰；应去掉“每个”，说“全民都应该遵守交通规则”（或说“每个公民”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
