INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姐是比你早出生的女孩子，和你有同一个爸爸妈妈。", "primary_collocate": null, "pronunciation": "jiě", "ipa": "tɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我姐今年上大学了。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只有一个姐，没有哥哥。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐和我是一个爸爸妈妈生的。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐小时候常常带我玩。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐，妈妈叫我们吃饭。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐比我早出生三年。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和我姐住在同一个房间。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐会做蛋糕，很好吃。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上我姐都送我去学校。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐的生日在五月。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姐姐", "label": "重叠"}, {"form": "姐妹", "label": "复合"}, {"form": "姐夫", "label": "复合"}], "register": "口语", "sense_fingerprint": "同父母、比自己早出生的女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”读 jiě（第三声），指同父母、比自己早出生的女孩。"}, {"text": "介", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是节日。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是迎接、接电话。"}, {"text": "写", "is_correct": false, "explanation": "xiě 与 jiě 声母不同（x 与 j），意思是写。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ 与 jiě 韵母不同（a 与 e），意思是假。"}], "explanations": {"姐": "正确。“姐”读 jiě（第三声），指同父母、比自己早出生的女孩。", "介": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍。", "节": "jié（第二声）与 jiě（第三声）声调不同，意思是节日。", "接": "jiē（第一声）与 jiě（第三声）声调不同，意思是迎接、接电话。", "写": "xiě 与 jiě 声母不同（x 与 j），意思是写。", "假": "jiǎ 与 jiě 韵母不同（a 与 e），意思是假。"}, "sentence_index": null, "correct_answer": "姐"}, "level_3": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”指同父母的姐姐，可以指上大学的姐姐。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能上大学。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“上大学”的主语须是人，不说“房子上大学”。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不能上大学。"}], "explanations": {"姐": "正确。“姐”指同父母的姐姐，可以指上大学的姐姐。", "汽车": "语义：汽车不能上大学。", "房子": "搭配：“上大学”的主语须是人，不说“房子上大学”。", "狗": "语义：狗不能上大学。"}, "sentence_index": 0, "correct_answer": "姐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐是我妈妈的妹妹。", "explanation": "这里应该用〈姨妈〉。“姐”指同父母的年长姐姐，不能用来称呼母亲的妹妹，应说“姨妈”。"}, {"text": "我哥哥是我的姐。", "explanation": "这里误把〈姐〉用于男性。“姐”指女性，哥哥是男性，指兄长要用〈哥〉。"}, {"text": "我姐比我晚出生两年，今年才五岁。", "explanation": "这里应该用〈妹妹〉。“姐”指比自己早出生的女孩，比自己晚出生要说“妹妹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87509, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”读 jiě（第三声），指同父母、比自己早出生的女孩。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是结束或打结。"}, {"text": "戒", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒掉。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是借。"}], "explanations": {"姐": "正确。“姐”读 jiě（第三声），指同父母、比自己早出生的女孩。", "街": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。", "结": "jié（第二声）与 jiě（第三声）声调不同，意思是结束或打结。", "戒": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒掉。", "借": "jiè（第四声）与 jiě（第三声）声调不同，意思是借。"}, "sentence_index": null, "correct_answer": "姐"}, "level_3": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”指同父母的姐姐，与“住在同一个房间”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能和人“住在”同一个房间。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是机构，不能与人同住一个房间。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“和我……住在同一个房间”的对象须是人，不能说“和花园”。"}], "explanations": {"姐": "正确。“姐”指同父母的姐姐，与“住在同一个房间”相符。", "桌子": "语义：桌子不能和人“住在”同一个房间。", "公司": "语义：公司是机构，不能与人同住一个房间。", "花园": "搭配：“和我……住在同一个房间”的对象须是人，不能说“和花园”。"}, "sentence_index": 6, "correct_answer": "姐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐比我小三岁，我们常一起玩。", "explanation": "这里应该用〈妹妹〉。“姐”指同父母的年长姐姐，比自己小要说“妹妹”。"}, {"text": "我爸爸是我的姐。", "explanation": "这里误把〈姐〉用于男性长辈。“姐”指同父母、比自己早出生的女孩，爸爸是男性长辈，应该说“爸爸”。"}, {"text": "我外婆是我的姐。", "explanation": "这里误把〈姐〉用于长辈。“姐”指同辈的姐姐，外婆属于长辈，不能说是我的姐姐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只姐，她在上海工作。", "corrected_sentence": "我有一个姐，她在上海工作。", "error_description": "量词错误：“姐”指人，应用量词“个”。“只”用于动物，说“一只姐”错误，应说“一个姐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很姐聪明，比我懂事。", "corrected_sentence": "我姐很聪明，比我懂事。", "error_description": "语序错误：“很”修饰形容词，应放在形容词前，“姐”作主语要在“很”之前。错误：“我很姐聪明”，正确：“我姐很聪明”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
