INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用在姓后面或单独使用，亲切地称呼比自己年长的女子。", "primary_collocate": null, "pronunciation": "jiě", "ipa": "tɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "姐，你今天几点回家？", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刘姐在楼下开了一家小店。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王，这位是李姐。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐，帮我拿一下那本书好吗？", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里大家都叫她陈姐。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王姐今天给大家带来了水果。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赵姐比我大十岁，对我很好。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐，这个字怎么读？", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张姐是我们公司最会做饭的人。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李姐昨天给我买了一件新衣服。", "target_word": "姐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姐姐", "label": "重叠"}, {"form": "姐妹", "label": "复合"}, {"form": "姐夫", "label": "复合"}], "register": "口语", "sense_fingerprint": "称呼年长女子，如“李姐、王姐”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”读 jiě（第三声），指姐姐，也可称呼比自己年长的女子。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是接。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是借。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是节日。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ 与 jiě 韵母不同（a 与 e），意思是假。"}, {"text": "写", "is_correct": false, "explanation": "xiě 与 jiě 声母不同（x 与 j），意思是写。"}], "explanations": {"姐": "正确。“姐”读 jiě（第三声），指姐姐，也可称呼比自己年长的女子。", "接": "jiē（第一声）与 jiě（第三声）声调不同，意思是接。", "借": "jiè（第四声）与 jiě（第三声）声调不同，意思是借。", "节": "jié（第二声）与 jiě（第三声）声调不同，意思是节日。", "假": "jiǎ 与 jiě 韵母不同（a 与 e），意思是假。", "写": "xiě 与 jiě 声母不同（x 与 j），意思是写。"}, "sentence_index": null, "correct_answer": "姐"}, "level_3": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”是对姐姐或年长女子的称呼，放在句首合适。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是地点，不能被称呼，也不会回家。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，无法被称呼，也不能“回家”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“回家”需要人作主语，不说“天气回家”。"}], "explanations": {"姐": "正确。“姐”是对姐姐或年长女子的称呼，放在句首合适。", "教室": "语义：“教室”是地点，不能被称呼，也不会回家。", "手机": "语义：“手机”是物品，无法被称呼，也不能“回家”。", "天气": "搭配：“回家”需要人作主语，不说“天气回家”。"}, "sentence_index": 0, "correct_answer": "姐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都叫那个三岁的小女孩王姐。", "explanation": "这里误把〈姐〉用于年幼的孩子。“姐”用来称呼比自己年长的女子，三岁的小女孩不能叫“王姐”。"}, {"text": "大家都叫新来的男同事张姐。", "explanation": "这里误把〈姐〉用于男性。“姐”只称呼女子，男同事应叫“张哥”。"}, {"text": "赵姐比我小二十岁，还在上小学。", "explanation": "这里误用了〈姐〉。“姐”称呼比自己年长的女子，比自己小很多的孩子不能叫“姐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87510, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“姐”读 jiě（第三声），指姐姐，也可称呼比自己年长的女子。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是结束或打结。"}, {"text": "介", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍。"}, {"text": "戒", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒掉。"}], "explanations": {"姐": "正确。“姐”读 jiě（第三声），指姐姐，也可称呼比自己年长的女子。", "街": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。", "结": "jié（第二声）与 jiě（第三声）声调不同，意思是结束或打结。", "介": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍。", "戒": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒掉。"}, "sentence_index": null, "correct_answer": "姐"}, "level_3": {"options": [{"text": "姐", "is_correct": true, "explanation": "正确。“赵姐”称呼比我年长的女子，与“比我大十岁”相符。"}, {"text": "妹", "is_correct": false, "explanation": "语义：“妹”指比自己小的女子，与“比我大十岁”矛盾。"}, {"text": "弟", "is_correct": false, "explanation": "语义：“弟”指比自己小的男子，与“比我大十岁”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“对我很好”的主语须是人，“赵房子”不成立。"}], "explanations": {"姐": "正确。“赵姐”称呼比我年长的女子，与“比我大十岁”相符。", "妹": "语义：“妹”指比自己小的女子，与“比我大十岁”矛盾。", "弟": "语义：“弟”指比自己小的男子，与“比我大十岁”矛盾。", "房子": "搭配：“对我很好”的主语须是人，“赵房子”不成立。"}, "sentence_index": 6, "correct_answer": "姐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的小狗是我的姐。", "explanation": "这里误把〈姐〉用于动物。“姐”只指人，不能用来指宠物。"}, {"text": "大家都叫王先生王姐。", "explanation": "这里误把〈姐〉用于男性。“姐”只称呼女子，王先生应叫“王哥”。"}, {"text": "我叫隔壁五岁的小女孩李姐。", "explanation": "这里误用了〈姐〉。“姐”称呼比自己年长的女子，五岁的小女孩不能叫“李姐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只李姐在我们公司工作。", "corrected_sentence": "这位李姐在我们公司工作。", "error_description": "量词错误：“李姐”指人，应用量词“位”或“个”。“只”用于动物，不能说“这只李姐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王姐高很，比我高五公分。", "corrected_sentence": "王姐很高，比我高五公分。", "error_description": "语序错误：程度副词“很”要放在形容词前，应说“很高”，不说“高很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
