INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87511, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每个地方都有，什么地方都有。", "primary_collocate": null, "pronunciation": "dào chù", "ipa": "tau˥˩ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "春天到了，公园里到处是花。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到处找手机，都没找到。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里到处是玩具。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到处问路，才找到那家店。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上到处是水。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，街上到处都是人。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我到处都买不到。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把水洒得到处都是。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，山上到处是绿色的树。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到处旅行，去过很多地方。", "target_word": "到处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个地方，什么地方都有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87511, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到处", "is_correct": true, "explanation": "正确答案：到处（dào chù），表示每个地方都有。"}, {"text": "倒数", "is_correct": false, "explanation": "dào shù（倒数）与 dào chù（到处）的声母不同：ch 与 sh，倒数意思是数学中的倒数。"}, {"text": "道出", "is_correct": false, "explanation": "dào chū（道出）与 dào chù（到处）的第二个音节声调不同：第一声与第四声，道出意思是说出、表达。"}, {"text": "导出", "is_correct": false, "explanation": "dǎo chū（导出）与 dào chù（到处）两个音节的声调都不同：第三声与第四声、第一声与第四声，导出意思是引出、输出。"}, {"text": "倒出", "is_correct": false, "explanation": "dào chū（倒出）与 dào chù（到处）的第二个音节声调不同：第一声与第四声，倒出意思是把东西从容器里倒出来。"}], "explanations": {"到处": "正确答案：到处（dào chù），表示每个地方都有。", "倒数": "dào shù（倒数）与 dào chù（到处）的声母不同：ch 与 sh，倒数意思是数学中的倒数。", "道出": "dào chū（道出）与 dào chù（到处）的第二个音节声调不同：第一声与第四声，道出意思是说出、表达。", "导出": "dǎo chū（导出）与 dào chù（到处）两个音节的声调都不同：第三声与第四声、第一声与第四声，导出意思是引出、输出。", "倒出": "dào chū（倒出）与 dào chù（到处）的第二个音节声调不同：第一声与第四声，倒出意思是把东西从容器里倒出来。"}, "sentence_index": null, "correct_answer": "到处"}, "level_3": {"options": [{"text": "到处", "is_correct": true, "explanation": "“到处”是副词，表示每个地方都有，与“公园里……是花”搭配。"}, {"text": "很少", "is_correct": false, "explanation": "语义：“春天到了”与“很少是花”矛盾，春天的公园不会说花很少。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”说始终如此，与“春天到了”所说的变化相冲突。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”后接动作或变化，不接“是花”这样的判断句。"}], "explanations": {"到处": "“到处”是副词，表示每个地方都有，与“公园里……是花”搭配。", "很少": "语义：“春天到了”与“很少是花”矛盾，春天的公园不会说花很少。", "从来": "语义：“从来”说始终如此，与“春天到了”所说的变化相冲突。", "忽然": "搭配：“忽然”后接动作或变化，不接“是花”这样的判断句。"}, "sentence_index": 0, "correct_answer": "到处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他到处同意了吗？", "explanation": "这里应该用〈到底〉。问最终结果要用到底，到处只表示地点范围，不能修饰“同意”。"}, {"text": "这些书到处都是我的。", "explanation": "这里应该用〈全部〉。“到处”指地点范围，说所有东西都属于某人要用“全部”，不能说“到处都是我的”。"}, {"text": "会议室里到处坐着一个人。", "explanation": "这里应该用〈只〉。“到处”强调很多地方都有，只有一个人时要说“只”，不能用“到处”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到处", "is_correct": true, "explanation": "“这本书我到处都买不到”表示任何地方都买不到，与“这本书”相符。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”表示总计，不能与“都买不到”的全面否定搭配。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同做某事，“我”单独买书的语境不搭。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”说时间短，与“都买不到”表示的范围不合。"}], "explanations": {"到处": "“这本书我到处都买不到”表示任何地方都买不到，与“这本书”相符。", "一共": "搭配：“一共”表示总计，不能与“都买不到”的全面否定搭配。", "一起": "搭配：“一起”表示共同做某事，“我”单独买书的语境不搭。", "很快": "语义：“很快”说时间短，与“都买不到”表示的范围不合。"}, "sentence_index": 6, "correct_answer": "到处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他到处八点就起床了。", "explanation": "这里应该用〈早上〉。“到处”指地点范围，表示时间要说“早上”，不能用“到处”。"}, {"text": "他到处三天没吃饭。", "explanation": "这里应该用〈整整〉。“到处”只表示地点范围，表示持续时间要用“整整”，不能说“到处三天”。"}, {"text": "我的成绩到处很好。", "explanation": "这里应该用〈各科〉。“到处”指地点，不能修饰“成绩”这类抽象的性质，要说各科成绩都很好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书放到处都是。", "corrected_sentence": "他把书放得到处都是。", "error_description": "错误形式：他把书放到处都是；正确形式：他把书放得到处都是；原因：“放”与表示状态的补语“到处都是”之间需要用“得”连接，漏掉“得”则句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里到处书。", "corrected_sentence": "教室里到处是书。", "error_description": "错误：漏掉了动词“是”。正确：应为“到处是书”，“到处是＋名词”表示遍布，缺“是”则句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：“白天”与“晚上”相对，分别指太阳出来与下山的时段，且原句“与白天相对”。"}, {"text": "中午", "is_correct": false, "explanation": "“中午”是白天的一个时刻，不与“晚上”构成反义关系。"}, {"text": "春天", "is_correct": false, "explanation": "“春天”是季节，与“晚上”没有反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周的末尾，与“晚上”没有反义关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：“白天”与“晚上”相对，分别指太阳出来与下山的时段，且原句“与白天相对”。", "中午": "“中午”是白天的一个时刻，不与“晚上”构成反义关系。", "春天": "“春天”是季节，与“晚上”没有反义关系。", "周末": "“周末”指一周的末尾，与“晚上”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：“白天”与“晚上”相对，分别指太阳出来与下山的时段。"}, {"text": "上午", "is_correct": false, "explanation": "“上午”是白天的一段，但与“晚上”不是相对关系。"}, {"text": "夏天", "is_correct": false, "explanation": "“夏天”是季节，与“晚上”没有反义关系。"}, {"text": "星期一", "is_correct": false, "explanation": "“星期一”是一周中的一天，与“晚上”没有反义关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：“白天”与“晚上”相对，分别指太阳出来与下山的时段。", "上午": "“上午”是白天的一段，但与“晚上”不是相对关系。", "夏天": "“夏天”是季节，与“晚上”没有反义关系。", "星期一": "“星期一”是一周中的一天，与“晚上”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚上是太阳下山以后，天黑了的时候。", "primary_collocate": null, "pronunciation": "wǎn shang", "ipa": "wan˨˩ ʂaŋ", "syllable_count": 2, "sentences": [{"text": "冬天晚上五点天就黑了。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山了，晚上就来了。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上路上的灯都亮了。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，晚上就凉快了。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上天黑，你一个人要小心。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上星星和月亮都出来了。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们关灯睡觉。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子晚上不能出去玩太久。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的晚上可以在外面散步。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上很黑，我不敢一个人走。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "今天晚上", "label": "时间复合"}], "register": "中性", "sense_fingerprint": "晚上：太阳下山、天黑以后的时候，与白天相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：晚上（wǎn shang）指太阳下山、天黑以后的时候。"}, {"text": "晚场", "is_correct": false, "explanation": "晚场（wǎn chǎng）的第二音节声母是 ch，不是 sh，且为第三声，意思是晚间的一场演出或放映。"}, {"text": "网上", "is_correct": false, "explanation": "网上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是在互联网上。"}, {"text": "完善", "is_correct": false, "explanation": "完善（wán shàn）的第一音节为第二声（wán，不是 wǎn），第二音节韵母是 an，意思是使更加完备。"}], "explanations": {"晚上": "正确：晚上（wǎn shang）指太阳下山、天黑以后的时候。", "晚场": "晚场（wǎn chǎng）的第二音节声母是 ch，不是 sh，且为第三声，意思是晚间的一场演出或放映。", "网上": "网上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是在互联网上。", "完善": "完善（wán shàn）的第一音节为第二声（wán，不是 wǎn），第二音节韵母是 an，意思是使更加完备。"}, "sentence_index": null, "correct_answer": "晚上"}, "level_3": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：“冬天晚上五点”指冬季的夜间五点，天已经黑了。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午阳光正强，与“天就黑了”矛盾。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“五点天就黑了”一般说夜间或傍晚，不与“上午”连用。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天是天亮的时候，与“天就黑了”矛盾。"}], "explanations": {"晚上": "正确：“冬天晚上五点”指冬季的夜间五点，天已经黑了。", "中午": "语义：中午阳光正强，与“天就黑了”矛盾。", "上午": "搭配：“五点天就黑了”一般说夜间或傍晚，不与“上午”连用。", "白天": "语义：白天是天亮的时候，与“天就黑了”矛盾。"}, "sentence_index": 0, "correct_answer": "晚上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上的阳光很刺眼，我们都戴上了墨镜。", "explanation": "这里应该用〈白天〉或〈中午〉。晚上指太阳下山、天黑以后，不会有刺眼的阳光。"}, {"text": "太阳还高挂着，晚上已经到了。", "explanation": "这里应该用〈白天〉。太阳还没下山时不是晚上，晚上指天黑以后。"}, {"text": "他的事业已经进入了晚上，需要重新开始。", "explanation": "这里应该用〈晚年〉或〈后期〉。“晚上”只指一天中天黑以后的时段，不指事业或人生的后期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：晚上（wǎn shang）指太阳下山、天黑以后的时候。"}, {"text": "往上", "is_correct": false, "explanation": "往上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是向高处。"}, {"text": "腕上", "is_correct": false, "explanation": "腕上（wàn shàng）的第一音节为第四声（wàn，不是 wǎn），意思是手腕上。"}, {"text": "玩赏", "is_correct": false, "explanation": "玩赏（wán shǎng）两个音节的声调都与晚上不同，意思是游玩观赏。"}], "explanations": {"晚上": "正确：晚上（wǎn shang）指太阳下山、天黑以后的时候。", "往上": "往上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是向高处。", "腕上": "腕上（wàn shàng）的第一音节为第四声（wàn，不是 wǎn），意思是手腕上。", "玩赏": "玩赏（wán shǎng）两个音节的声调都与晚上不同，意思是游玩观赏。"}, "sentence_index": null, "correct_answer": "晚上"}, "level_3": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：“晚上我们关灯睡觉”指夜间关灯休息。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午阳光最强，不需要关灯睡觉，与句中语境矛盾。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨天已经亮了，与“关灯睡觉”矛盾。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“晚饭”是餐食，不说“晚饭我们关灯睡觉”，搭配不当。"}], "explanations": {"晚上": "正确：“晚上我们关灯睡觉”指夜间关灯休息。", "正午": "语义：正午阳光最强，不需要关灯睡觉，与句中语境矛盾。", "清晨": "语义：清晨天已经亮了，与“关灯睡觉”矛盾。", "晚饭": "搭配：“晚饭”是餐食，不说“晚饭我们关灯睡觉”，搭配不当。"}, "sentence_index": 6, "correct_answer": "晚上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们今天去吃晚上吧。", "explanation": "这里应该用〈晚饭〉。“晚上”是时间名词，不能吃；吃的东西要说“晚饭”。"}, {"text": "我的书包在晚上的桌子下面。", "explanation": "这里应该用〈房间〉之类的地点词。“晚上”是时间词，不能表示地点。"}, {"text": "这个房间很晚上，我们开灯吧。", "explanation": "这里应该用〈暗〉或〈黑〉。「晚上」是时间名词，不能当形容词描写房间的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在朋友家住了三条晚上。", "corrected_sentence": "我在朋友家住了三个晚上。", "error_description": "错误：「晚上」的量词应为「个」，说「三个晚上」；「条」用于细长的东西，不能修饰「晚上」，是量词用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上时候，我们很早就睡觉了。", "corrected_sentence": "晚上的时候，我们很早就睡觉了。", "error_description": "错误：“晚上”修饰“时候”时要加“的”，说“晚上的时候”；去掉“的”成“晚上时候”，是修饰语缺少“的”的常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：“白天”与“晚上”是一天中相对的两段时间，构成反义关系。"}, {"text": "中午", "is_correct": false, "explanation": "“中午”指白天正中的时候，是白天的一部分，不与“晚上”构成反义关系。"}, {"text": "下午", "is_correct": false, "explanation": "“下午”也是白天的一段，但与“晚上”不是相对关系。"}, {"text": "春天", "is_correct": false, "explanation": "“春天”是季节，与“晚上”没有反义关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：“白天”与“晚上”是一天中相对的两段时间，构成反义关系。", "中午": "“中午”指白天正中的时候，是白天的一部分，不与“晚上”构成反义关系。", "下午": "“下午”也是白天的一段，但与“晚上”不是相对关系。", "春天": "“春天”是季节，与“晚上”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：“白天”与“晚上”是一天中相对的两段时间，构成反义关系。"}, {"text": "上午", "is_correct": false, "explanation": "“上午”是白天的一段，但与“晚上”不是相对关系。"}, {"text": "星期六", "is_correct": false, "explanation": "“星期六”是一周中的一天，与“晚上”没有反义关系。"}, {"text": "夏天", "is_correct": false, "explanation": "“夏天”是季节，与“晚上”没有反义关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：“白天”与“晚上”是一天中相对的两段时间，构成反义关系。", "上午": "“上午”是白天的一段，但与“晚上”不是相对关系。", "星期六": "“星期六”是一周中的一天，与“晚上”没有反义关系。", "夏天": "“夏天”是季节，与“晚上”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从傍晚到午夜或到天亮之前的时间。", "primary_collocate": null, "pronunciation": "wǎn shang", "ipa": "wan˨˩ ʂaŋ", "syllable_count": 2, "sentences": [{"text": "我每天晚上十点睡觉。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上的风有一点凉。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我们去看电影了。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈晚上要做饭，我来帮忙。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天晚上你有空吗？", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他晚上常常在家看书。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末晚上，我们一起吃饭吧。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天晚上有雨，别忘了带伞。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上七点，学校门口见。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她晚上下班很晚才回家。", "target_word": "晚上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "昨天晚上", "label": "时间复合"}], "register": "中性", "sense_fingerprint": "晚上：傍晚到午夜或天亮前的一段时间，用来说明事情发生的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：晚上（wǎn shang）指傍晚到天亮前的一段时间。"}, {"text": "晚场", "is_correct": false, "explanation": "晚场（wǎn chǎng）的第二音节声母是 ch，不是 sh，且为第三声，意思是晚间的一场演出或放映。"}, {"text": "网上", "is_correct": false, "explanation": "网上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是在互联网上。"}, {"text": "完善", "is_correct": false, "explanation": "完善（wán shàn）的第一音节为第二声（wán，不是 wǎn），第二音节韵母是 an，意思是使更加完备。"}], "explanations": {"晚上": "正确：晚上（wǎn shang）指傍晚到天亮前的一段时间。", "晚场": "晚场（wǎn chǎng）的第二音节声母是 ch，不是 sh，且为第三声，意思是晚间的一场演出或放映。", "网上": "网上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是在互联网上。", "完善": "完善（wán shàn）的第一音节为第二声（wán，不是 wǎn），第二音节韵母是 an，意思是使更加完备。"}, "sentence_index": null, "correct_answer": "晚上"}, "level_3": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：“每天晚上十点”指每天夜间十点，与“睡觉”搭配。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“下午”一般不与“十点”连用来指睡觉的时间。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“每天”表示反复发生，“明天”只指第二天，二者矛盾。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：凌晨指午夜后到天亮前，与“十点”矛盾。"}], "explanations": {"晚上": "正确：“每天晚上十点”指每天夜间十点，与“睡觉”搭配。", "下午": "搭配：“下午”一般不与“十点”连用来指睡觉的时间。", "明天": "语义：“每天”表示反复发生，“明天”只指第二天，二者矛盾。", "凌晨": "语义：凌晨指午夜后到天亮前，与“十点”矛盾。"}, "sentence_index": 0, "correct_answer": "晚上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上太阳很大，我们去游泳吧。", "explanation": "这里应该用〈中午〉或〈白天〉。晚上是傍晚以后，没有太阳。"}, {"text": "我们在山上度过了一整天的晚上。", "explanation": "这里应该用〈白天〉或〈一天〉。“晚上”只指傍晚到天亮前的一段，不能指整天。"}, {"text": "他已经到了人生的晚上，应该多休息。", "explanation": "这里应该用〈晚年〉。“晚上”只指一天中的时段，不指人生的后期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：晚上（wǎn shang）指傍晚到天亮前的一段时间。"}, {"text": "往上", "is_correct": false, "explanation": "往上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是向高处。"}, {"text": "腕上", "is_correct": false, "explanation": "腕上（wàn shàng）的第一音节为第四声（wàn，不是 wǎn），意思是手腕上。"}, {"text": "玩赏", "is_correct": false, "explanation": "玩赏（wán shǎng）两个音节的声调都与晚上不同，意思是游玩观赏。"}], "explanations": {"晚上": "正确：晚上（wǎn shang）指傍晚到天亮前的一段时间。", "往上": "往上（wǎng shàng）的第一音节韵母是 ang，不是 an，意思是向高处。", "腕上": "腕上（wàn shàng）的第一音节为第四声（wàn，不是 wǎn），意思是手腕上。", "玩赏": "玩赏（wán shǎng）两个音节的声调都与晚上不同，意思是游玩观赏。"}, "sentence_index": null, "correct_answer": "晚上"}, "level_3": {"options": [{"text": "晚上", "is_correct": true, "explanation": "正确：“周末晚上”指周末的夜间，表示约吃饭的时间。"}, {"text": "工作日", "is_correct": false, "explanation": "语义：“周末”与“工作日”互相矛盾，周末不是工作日。"}, {"text": "平日", "is_correct": false, "explanation": "语义：“周末”与“平日”互相矛盾，平日指非周末的日子。"}, {"text": "寒假", "is_correct": false, "explanation": "搭配：“周末”后不接“寒假”这样的长假期，二者不搭配。"}], "explanations": {"晚上": "正确：“周末晚上”指周末的夜间，表示约吃饭的时间。", "工作日": "语义：“周末”与“工作日”互相矛盾，周末不是工作日。", "平日": "语义：“周末”与“平日”互相矛盾，平日指非周末的日子。", "寒假": "搭配：“周末”后不接“寒假”这样的长假期，二者不搭配。"}, "sentence_index": 6, "correct_answer": "晚上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们今天去吃晚上吧。", "explanation": "这里应该用〈晚饭〉。“晚上”是时间名词，不能吃；吃的东西要说“晚饭”。"}, {"text": "我把作业放在晚上的书桌上。", "explanation": "这里应该用〈房间〉之类的地点词。“晚上”是时间词，不能表示地点。"}, {"text": "这个房间很晚上，我们开灯吧。", "explanation": "这里应该用〈暗〉或〈黑〉。「晚上」是时间名词，不能当形容词描写房间的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条晚上我们去看电影吧。", "corrected_sentence": "这个晚上我们去看电影吧。", "error_description": "错误：“晚上”的量词应为“个”，说“这个晚上”；“这条”用于细长的物品，不能修饰“晚上”，是量词用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每只晚上都复习一个小时。", "corrected_sentence": "我每个晚上都复习一个小时。", "error_description": "错误：“晚上”的量词应为“个”，说“每个晚上”；“只”多用于动物等，“每只晚上”是量词用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
