INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "安全性是说一样东西会不会伤到人。不会伤到人，就是很安全。", "primary_collocate": null, "pronunciation": "ān quán xìng", "ipa": "an˥ t͡ɕʰɥɛn˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "买玩具时，我最看重安全性。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种儿童椅的安全性很好。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说这条路的安全性不太高。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游乐设施的安全性怎么样？", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈先问了奶粉的安全性。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车头盔能提高骑车的安全性。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种电热水壶的安全性让人放心。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用的东西，安全性一定要高。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个梯子的安全性吗？", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全性差的玩具会伤到孩子。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一样东西会不会伤到人，不伤人就是安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全性", "is_correct": true, "explanation": "正确答案。“买玩具时，我最看重安全性”指家长最关心玩具是否会伤人。"}, {"text": "页数", "is_correct": false, "explanation": "语义：页数是书本的数量，玩具没有页数，“看重页数”说不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的经历，玩具没有学历，“看重学历”说不通。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔与玩具的选购毫无关系，句意不通。"}], "explanations": {"安全性": "正确答案。“买玩具时，我最看重安全性”指家长最关心玩具是否会伤人。", "页数": "语义：页数是书本的数量，玩具没有页数，“看重页数”说不通。", "学历": "语义：学历指受教育的经历，玩具没有学历，“看重学历”说不通。", "海拔": "语义：海拔与玩具的选购毫无关系，句意不通。"}, "sentence_index": 0, "correct_answer": "安全性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个游乐设施的安全性很长。", "explanation": "这里应该用〈高〉或〈好〉。“长”说的是长度，安全性不能用长短来形容。"}, {"text": "这个游乐设施的安全性好吃吗？", "explanation": "“安全性”被误用为味觉义。安全性只说是否会伤到人，不说味道。"}, {"text": "这个游乐设施的安全性红不红？", "explanation": "“安全性”被误用为颜色义。安全性没有颜色，不能问“红不红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全性", "is_correct": true, "explanation": "正确答案。“这种电热水壶的安全性让人放心”指它不会伤人，让人安心。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的个数，电热水壶没有字数，“让人放心”说不通。"}, {"text": "书名", "is_correct": false, "explanation": "语义：书名是书的名称，电热水壶没有书名，“让人放心”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或物的岁数，“电热水壶的年龄让人放心”说不通。"}], "explanations": {"安全性": "正确答案。“这种电热水壶的安全性让人放心”指它不会伤人，让人安心。", "字数": "语义：字数是文字的个数，电热水壶没有字数，“让人放心”说不通。", "书名": "语义：书名是书的名称，电热水壶没有书名，“让人放心”说不通。", "年龄": "语义：年龄指人或物的岁数，“电热水壶的年龄让人放心”说不通。"}, "sentence_index": 6, "correct_answer": "安全性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套玩具的安全性很甜。", "explanation": "“安全性”被误用为味觉义。安全性只说会不会伤到人，没有味道，不能说“甜”。"}, {"text": "这套玩具的安全性很软。", "explanation": "“安全性”被误用为质地义。安全性不说软硬，“很软”用错了对象。"}, {"text": "这套玩具的安全性很圆。", "explanation": "“安全性”被误用为形状义。安全性不说圆或方，不能用形状来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车的安全性的怎么样？", "corrected_sentence": "这辆车的安全性怎么样？", "error_description": "错误形式是「安全性的怎么样」，正确形式是「安全性怎么样」。“的”多余，“安全性”后面直接接谓语，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种玩具的安全性的一定要高。", "corrected_sentence": "这种玩具的安全性一定要高。", "error_description": "错误形式是「安全性的一定要高」，正确形式是「安全性一定要高」。“的”多余，“安全性”后面直接接副词与谓语，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
