INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物品、系统或行为不会造成危险或损害的程度。", "primary_collocate": null, "pronunciation": "ān quán xìng", "ipa": "an˥ t͡ɕʰɥɛn˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个软件的安全性很高。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先检查系统的安全性。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的安全性比价格更重要。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新药的安全性还需要再试验。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们提高了网站的安全性。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全性不好的产品不能卖。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机的安全性比开车高。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的安全性已经得到了确认。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在评价这套设备的安全性。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保证安全性，门上装了两把锁。", "target_word": "安全性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物品、系统或行为不造成危险或损害的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validatio