INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全性", "is_correct": true, "explanation": "正确答案。“这个软件的安全性很高”中，“安全性”说的是程度，可以与“高”搭配。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”说大小，不说“体积很高”，与“很高”搭配不当。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有高低程度之分，“这个软件的颜色很高”语义不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”说大小，不说“面积很高”，搭配不当。"}], "explanations": {"安全性": "正确答案。“这个软件的安全性很高”中，“安全性”说的是程度，可以与“高”搭配。", "体积": "搭配：“体积”说大小，不说“体积很高”，与“很高”搭配不当。", "颜色": "语义：颜色没有高低程度之分，“这个软件的颜色很高”语义不通。", "面积": "搭配：“面积”说大小，不说“面积很高”，搭配不当。"}, "sentence_index": 0, "correct_answer": "安全性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种新药的安全性很胖。", "explanation": "“胖”形容人或动物的身材，不能用来形容安全性的程度。"}, {"text": "这种新药的安全性很多。", "explanation": "这里应该用〈高〉。安全性说程度，不能用“很多”形容数量。"}, {"text": "这种新药的安全性很快。", "explanation": "这里应该用〈高〉。快慢描述的是速度，不用来形容安全性的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全性", "is_correct": true, "explanation": "正确答案。“坐飞机的安全性比开车高”是合理的比较句。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不用来比较交通方式的安全程度，句意不通。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“长度”说长短，不能与“比……高”搭配比较安全程度。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度说明明暗，“坐飞机的亮度比开车高”说不通。"}], "explanations": {"安全性": "正确答案。“坐飞机的安全性比开车高”是合理的比较句。", "体重": "语义：体重不用来比较交通方式的安全程度，句意不通。", "长度": "搭配：“长度”说长短，不能与“比……高”搭配比较安全程度。", "亮度": "语义：亮度说明明暗，“坐飞机的亮度比开车高”说不通。"}, "sentence_index": 6, "correct_answer": "安全性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇门的安全性很快乐。", "explanation": "“安全性”被误用为情绪义。安全性只指是否会伤人，没有情感，不能“快乐”。"}, {"text": "这扇门的安全性很粗糙。", "explanation": "“安全性”被误用为表面质地义。安全性不说质地的粗细。"}, {"text": "这扇门的安全性很香。", "explanation": "“安全性”被误用为气味义。安全性没有气味，不能说“香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
