INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "月月是每一个月，一个月也不少。", "primary_collocate": null, "pronunciation": "yuè yuè", "ipa": "ɥɛ˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他月月给家里寄钱。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我月月都去看奶奶。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她月月都买新书。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸月月按时交房租。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杂志月月都有新的一期。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班月月开一次会。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她月月都会去医院检查身体。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他月月把工资的一半存起来。", "target_word": "月月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我月月都去图书馆借三本书。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司月月发工资，从来没有晚过。", "target_word": "月月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月月·每个月·一个月也不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月月", "is_correct": true, "explanation": "月月表示每个月，符合“每个月都寄钱”的句意。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”不能单独表示“每个月”的重复，“他星期给家里寄钱”不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能表示寄钱的时间，句子不通。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生指人，不能作寄钱的时间状语，句意不通。"}], "explanations": {"月月": "月月表示每个月，符合“每个月都寄钱”的句意。", "星期": "搭配：“星期”不能单独表示“每个月”的重复，“他星期给家里寄钱”不通。", "月亮": "语义：月亮是天体，不能表示寄钱的时间，句子不通。", "学生": "语义：学生指人，不能作寄钱的时间状语，句意不通。"}, "sentence_index": 0, "correct_answer": "月月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天月月去看了奶奶。", "explanation": "这里月月误作〈某一天〉的意思。月月表示“每个月”的反复，不能用于只发生在某一天的事。"}, {"text": "她月月出生了。", "explanation": "这里月月误作〈只发生一次〉的意思。月月表示“每个月”的反复，不能用于出生这种只发生一次的事。"}, {"text": "我们公司月月开了一次创立大会。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于创立大会这种一次性的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月月", "is_correct": true, "explanation": "月月表示每个月，符合“每个月都去检查”的句意。"}, {"text": "院子", "is_correct": false, "explanation": "语义：院子是场所，不能作“去医院检查”的主语，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会去医院检查身体，句子不通。"}, {"text": "日子", "is_correct": false, "explanation": "搭配：“日子”不能与“都会去医院”搭配作主语，句意不通。"}], "explanations": {"月月": "月月表示每个月，符合“每个月都去检查”的句意。", "院子": "语义：院子是场所，不能作“去医院检查”的主语，句子不通。", "石头": "语义：石头不会去医院检查身体，句子不通。", "日子": "搭配：“日子”不能与“都会去医院”搭配作主语，句意不通。"}, "sentence_index": 6, "correct_answer": "月月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他月月去世了。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于去世这种只发生一次的事。"}, {"text": "他明天月月去北京。", "explanation": "这里月月误作〈某一天〉的意思。月月表示“每个月”的反复，不能用于只发生在某一天的事。"}, {"text": "他那天月月生病了。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于生病这类偶发的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他月月很给爸妈寄钱。", "corrected_sentence": "他月月都给爸妈寄钱。", "error_description": "错误：“月月”后应用“都”表示每个月都如此，不能用“很”。“很”不能修饰“给爸妈寄钱”，应说“月月都给爸妈寄钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的水果一个月月都会降价。", "corrected_sentence": "这家店的水果月月都会降价。", "error_description": "“月月”前面不能加数量词“一个”，表示逐月要直接说“月月都会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
