INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "每个月；逐月。", "primary_collocate": null, "pronunciation": "yuè yuè", "ipa": "ɥɛ˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他的成绩月月都在进步。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的客人月月增加。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的体重月月都在下降。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子月月长高，衣服都小了。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的房价月月上涨。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的收入月月都比上个月多。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树月月都在长大，现在已经很高了。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语水平月月提高，老师很满意。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的游客月月变多，生意越来越好。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的存款月月变多，他心里很高兴。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月月·逐月·逐月变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月月", "is_correct": true, "explanation": "月月表示每个月，与“都”搭配，说成绩逐月都在进步，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮指天体，不能表示逐月的重复，句子不通。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：星期不能单独表示“每个星期”，要说“每星期”，不能直接作逐期的时间状语。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生指人，不能充当时间状语修饰“都在进步”，句意不通。"}], "explanations": {"月月": "月月表示每个月，与“都”搭配，说成绩逐月都在进步，符合句意。", "月亮": "语义：月亮指天体，不能表示逐月的重复，句子不通。", "星期": "搭配：星期不能单独表示“每个星期”，要说“每星期”，不能直接作逐期的时间状语。", "学生": "语义：学生指人，不能充当时间状语修饰“都在进步”，句意不通。"}, "sentence_index": 0, "correct_answer": "月月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他月月毕业了。", "explanation": "这里月月误作〈只发生一次〉的意思。月月表示“每个月”的反复，不能用于毕业这种只发生一次的事。"}, {"text": "上个星期月月去了一次北京。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用来指某一次的出行。"}, {"text": "我们月月结了一次婚。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于结婚这种一生只一次的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月月", "is_correct": true, "explanation": "月月表示每个月，与“都”搭配，说小树逐月长大，符合句意。"}, {"text": "院子", "is_correct": false, "explanation": "语义：院子是场所，不会“长大”，与主语“小树”不能组合，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不会长大，句子不通。"}, {"text": "日子", "is_correct": false, "explanation": "搭配：“日子”指日期或生活，不能与“在长大”搭配作主语，句意不通。"}], "explanations": {"月月": "月月表示每个月，与“都”搭配，说小树逐月长大，符合句意。", "院子": "语义：院子是场所，不会“长大”，与主语“小树”不能组合，句子不通。", "石头": "语义：石头是无生命的东西，不会长大，句子不通。", "日子": "搭配：“日子”指日期或生活，不能与“在长大”搭配作主语，句意不通。"}, "sentence_index": 6, "correct_answer": "月月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我月月考上了大学。", "explanation": "这里月月误作〈只发生一次〉的意思。月月表示“每个月”的反复，不能用于考上大学这种只发生一次的事。"}, {"text": "妈妈昨天月月给我打了电话。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于只发生在某一天的事。"}, {"text": "我们班月月举办了一次毕业典礼。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于毕业典礼这种一次性的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的利润月月很在增长。", "corrected_sentence": "这家公司的利润月月都在增长。", "error_description": "错误：“月月”后应用“都”表示每个月都如此，不能用“很”。“很”不能修饰“在增长”，应说“月月都在增长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的工资每月月都在增加。", "corrected_sentence": "他的工资月月都在增加。", "error_description": "月月本身已含“每月”的意思，前面不能再加“每”，应直接说“月月都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "反义：“同一”指是同一个，“不同”指不是同一个，二者在此义上相对。"}, {"text": "新鲜", "is_correct": false, "explanation": "无关：“新鲜”形容事物刚产生或未变质，与“同一”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容头脑灵活，与“同一”没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "无关：“巨大”形容体积或数量很大，与“同一”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "反义：“同一”指是同一个，“不同”指不是同一个，二者在此义上相对。", "新鲜": "无关：“新鲜”形容事物刚产生或未变质，与“同一”没有反义关系。", "聪明": "无关：“聪明”形容头脑灵活，与“同一”没有反义关系。", "巨大": "无关：“巨大”形容体积或数量很大，与“同一”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "反义：“同一”指是同一个，“不同”指不是同一个，二者在此义上相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外表好看，与“同一”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容没有声音或不吵闹，与“同一”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "无关：“热情”形容待人友好，与“同一”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "反义：“同一”指是同一个，“不同”指不是同一个，二者在此义上相对。", "漂亮": "无关：“漂亮”形容外表好看，与“同一”没有反义关系。", "安静": "无关：“安静”形容没有声音或不吵闹，与“同一”没有反义关系。", "热情": "无关：“热情”形容待人友好，与“同一”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "同一是同样的，就是那一个。", "primary_collocate": null, "pronunciation": "tóng yī", "ipa": "tʰʊŋ˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "这两张照片拍的是同一个人。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说的是同一件事。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天和今天，我在同一个地方见到他。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那两个名字其实是同一个人。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在同一张桌子旁。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个电话是同一个号码。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每次都走同一条路回家。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信和那封信是同一个人寄的。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人说着同一种语言。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我又去了同一家商店，买了同一种茶。", "target_word": "同一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指同样的、就是那一个，强调前后所指相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同一", "is_correct": true, "explanation": "正确。“同一个人”指两张照片拍的是同一个人，与句意相符。"}, {"text": "每一", "is_correct": false, "explanation": "语义：“每一”指每个都包括在内，与“这两张照片”只拍了一个人不合。"}, {"text": "哪一", "is_correct": false, "explanation": "语义：“哪一”用于疑问或选择，陈述句中不能这样用。"}, {"text": "任一", "is_correct": false, "explanation": "语法：“任一”是书面语，不说“任一个人”，且它表示随便哪一个，与特指照片里的人不合。"}], "explanations": {"同一": "正确。“同一个人”指两张照片拍的是同一个人，与句意相符。", "每一": "语义：“每一”指每个都包括在内，与“这两张照片”只拍了一个人不合。", "哪一": "语义：“哪一”用于疑问或选择，陈述句中不能这样用。", "任一": "语法：“任一”是书面语，不说“任一个人”，且它表示随便哪一个，与特指照片里的人不合。"}, "sentence_index": 0, "correct_answer": "同一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次他被同一地选中了。", "explanation": "这里应该用〈同样〉。“同一”不能用作状语修饰动词；表示“一样地”要用“同样”。"}, {"text": "同一位同学都应该按时交作业。", "explanation": "这里应该用〈每位〉。同一表示是同一个、没有分别，泛指每个同学要用每位，不能说同一位同学。"}, {"text": "两家公司的做法很同一。", "explanation": "这里应该用〈类似〉。同一表示是同一个、没有分别，说做法相近要用类似，不能说很同一。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同一", "is_correct": true, "explanation": "正确。“同一条路”指每次都走的是这一条路，与句意相符。"}, {"text": "整个", "is_correct": false, "explanation": "语法：「整个」后不能直接接「一条」，「整个一条路」不成话，且与句意不合。"}, {"text": "另一", "is_correct": false, "explanation": "语义：“另一”指别的一条，与“每次都走”同一条路的说法矛盾。"}, {"text": "任意", "is_correct": false, "explanation": "语义：「任意」指随便哪一条，与“每次都走同一条路”的固定重复意思相反。"}], "explanations": {"同一": "正确。“同一条路”指每次都走的是这一条路，与句意相符。", "整个": "语法：「整个」后不能直接接「一条」，「整个一条路」不成话，且与句意不合。", "另一": "语义：“另一”指别的一条，与“每次都走”同一条路的说法矛盾。", "任意": "语义：「任意」指随便哪一条，与“每次都走同一条路”的固定重复意思相反。"}, "sentence_index": 6, "correct_answer": "同一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们对这个问题的看法非常同一。", "explanation": "这里应该用〈一致〉。“同一”不能受程度副词“非常”修饰；说看法相同要用“一致”。"}, {"text": "他同一地回答了老师的问题。", "explanation": "这里应该用〈同样〉。“同一”不能直接修饰动词作状语；表示用同样的方式要用“同样”。"}, {"text": "这三个方案的内容有点同一。", "explanation": "这里应该用〈相似〉。“同一”不能受“有点”修饰；说内容接近要用“相似”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两张照片里的人是同一只人。", "corrected_sentence": "这两张照片里的人是同一个人。", "error_description": "量词用错：“人”不能用量词“只”，应说“同一个人”，不能说“同一只人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每次都走同一个小路去学校。", "corrected_sentence": "她每次都走同一条小路去学校。", "error_description": "量词用错：“小路”应用量词“条”，应说“同一条小路”，不能说“同一个小路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
