INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年轻的男子。", "primary_collocate": null, "pronunciation": "xiǎo huǒ zi", "ipa": "ɕiɑʊ˨˩ xuɔ˨˩ tsɨ", "syllable_count": 3, "sentences": [{"text": "我问路时，一个小伙子热情地告诉了我。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小伙子是新来的老师。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子今年二十五岁，在银行工作。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车上，小伙子给老人让了座。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位小伙子在饭店做服务员。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子笑着说：“欢迎你来我们公司！”", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的邻居是个爱笑的小伙子。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小伙子走进商店，买了一瓶水。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子有点儿不好意思，红着脸走了。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她喜欢的小伙子要会做饭。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小伙子们", "label": "复数"}, {"form": "小伙儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "泛指年轻的男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路灯", "is_correct": false, "explanation": "语义：“路灯”是照明的设施，不会“热情地告诉”别人路。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“告诉”要求能说话的人作施事，“小猫”不能充当。"}, {"text": "小伙子", "is_correct": true, "explanation": "正确。小伙子泛指年轻的男子，这里指问路时帮我指路的那个年轻人。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”不能开口说话，不能“热情地告诉”我。"}], "explanations": {"路灯": "语义：“路灯”是照明的设施，不会“热情地告诉”别人路。", "小猫": "配价：“告诉”要求能说话的人作施事，“小猫”不能充当。", "小伙子": "正确。小伙子泛指年轻的男子，这里指问路时帮我指路的那个年轻人。", "电视": "语义：“电视”不能开口说话，不能“热情地告诉”我。"}, "sentence_index": 0, "correct_answer": "小伙子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妹妹是个小伙子，很喜欢画画。", "explanation": "这里应该用〈姑娘〉。“小伙子”指年轻的男子，不能用于女性。"}, {"text": "我父亲是个中年小伙子，每天很早起床。", "explanation": "这里应该用〈男人〉。“小伙子”指年轻的男子，不能用来形容中年人。"}, {"text": "那位小伙子八十岁了，每天去公园。", "explanation": "这里应该用〈老人〉。“小伙子”指年轻的男子，不能用于八十岁的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不能是“爱笑的”邻居。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“爱笑”要求人作主语，“窗户”不能。"}, {"text": "小伙子", "is_correct": true, "explanation": "正确。小伙子泛指年轻的男子，这里指我的年轻男性邻居。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有表情，不会“爱笑”。"}], "explanations": {"花园": "语义：“花园”是地方，不能是“爱笑的”邻居。", "窗户": "配价：“爱笑”要求人作主语，“窗户”不能。", "小伙子": "正确。小伙子泛指年轻的男子，这里指我的年轻男性邻居。", "石头": "语义：“石头”没有表情，不会“爱笑”。"}, "sentence_index": 6, "correct_answer": "小伙子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那台冰箱很能干，是个小伙子。", "explanation": "这里应该用〈机器〉，指物品。“小伙子”指年轻的男子，不能用于冰箱这样的物品。"}, {"text": "那个小伙子才两岁，就会背唐诗。", "explanation": "这里应该用〈婴儿〉。“小伙子”指年轻的男子，不能用于两岁的幼儿。"}, {"text": "那个小伙子才七岁，每天自己上学。", "explanation": "这里应该用〈小学生〉。“小伙子”指年轻的男子，不能用于七岁的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小伙子在路边帮我捡起了掉落的书。", "corrected_sentence": "一个小伙子在路边帮我捡起了掉落的书。", "error_description": "“小伙子”指人，量词应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班来了一个小伙子们，大家都很喜欢他。", "corrected_sentence": "我们班来了一个小伙子，大家都很喜欢他。", "error_description": "“一个”表示单数，“小伙子们”是复数，二者不能搭配，应说“一个小伙子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87527, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
