INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87527, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正常是和平时一样，没有什么不对。", "primary_collocate": null, "pronunciation": "zhèng cháng", "ipa": "ʈʂɤŋ˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "今天的火车正常运行。", "target_word": "正常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校下周一正常上课。", "target_word": "正常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过了节，商店明天正常开门。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，比赛正常进行。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停电结束后，工厂又正常生产了。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络恢复了，我们可以正常上网。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然下雨，航班还是正常起飞。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放假期间，图书馆正常开放。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯修好后，又恢复正常运行了。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，下午的课正常上。", "target_word": "正常", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正常", "label": "否定形式"}, {"form": "正常化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指事情或人的情况与平时一样，照常进行，没有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb8d477-42ee-4005-b0c4-97766b2fc790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正常", "is_correct": true, "explanation": "“正常”表示照常、和平时一样，与“火车运行”及“今天”的语境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容好看，不修饰“运行”这类动作。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”说明情况很糟，与“今天的火车”照常运行的语境不符。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”形容明白、不含糊，不修饰“运行”。"}], "explanations": {"正常": "“正常”表示照常、和平时一样，与“火车运行”及“今天”的语境相符。", "漂亮": "搭配：“漂亮”形容好看，不修饰“运行”这类动作。", "严重": "语义：“严重”说明情况很糟，与“今天的火车”照常运行的语境不符。", "清楚": "搭配：“清楚”形容明白、不含糊，不修饰“运行”。"}, "sentence_index": 0, "correct_answer": "正常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在正常医院看病。", "explanation": "这里应该用〈正规〉。正规指符合规范、合法，用于医院、公司；正常说情况照常，不用来说机构是否合规。"}, {"text": "老师说他的回答很正常，全都对了。", "explanation": "这里应该用〈正确〉。正确用于对错、答案；正常说情况照常，不用来评价回答是否对。"}, {"text": "我买的是正常书，不是盗版。", "explanation": "这里应该用〈正版〉。正版指合法出版的，用于书、软件；正常说情况照常，不用来说明版权是否合法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正常", "is_correct": true, "explanation": "“正常”表示照常、和平时一样，与“虽然下雨，航班还是”的转折语境相符。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序，不修饰“起飞”这一动作。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”描述气温，不能用来说明起飞的状态。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容清洁，不修饰“起飞”。"}], "explanations": {"正常": "“正常”表示照常、和平时一样，与“虽然下雨，航班还是”的转折语境相符。", "整齐": "搭配：“整齐”形容排列有序，不修饰“起飞”这一动作。", "寒冷": "语义：“寒冷”描述气温，不能用来说明起飞的状态。", "干净": "搭配：“干净”形容清洁，不修饰“起飞”。"}, "sentence_index": 6, "correct_answer": "正常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜很正常，是地道的四川味。", "explanation": "这里应该用〈正宗〉。正宗指真正的、地道的，用于菜、味道；正常说情况照常，不表示是否地道。"}, {"text": "他的字写得很正常，一笔一画都清楚。", "explanation": "这里应该用〈工整〉。工整指字迹端正、有条理，用于字、画；正常说情况照常，不用来评价字迹是否端正。"}, {"text": "这台仪器测量得很正常，误差很小。", "explanation": "这里应该用〈精确〉。精确指准确、没有误差，用于测量、计算；正常说情况照常，不用来评价测量的准确度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末的音乐会进行的很正常。", "corrected_sentence": "周末的音乐会进行得很正常。", "error_description": "补语标记误用：“进行”与后面的“很正常”之间应用“得”连接，不能用“的”，应说“进行得很正常”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "虽然下大雨，演出还是正常得进行了。", "corrected_sentence": "虽然下大雨，演出还是正常进行了。", "error_description": "“正常”直接修饰动词“进行”作状语，不能加“得”；应说“正常进行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异常", "is_correct": true, "explanation": "反义：“异常”指不符合一般情况，与这一义项的“正常”相对。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”指速度快，与这一义项的“正常”无近义或反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”指好看，与这一义项的“正常”无近义或反义关系。"}, {"text": "重要", "is_correct": false, "explanation": "“重要”指作用或价值大，与这一义项的“正常”无近义或反义关系。"}], "correct_answer": "异常", "explanations": {"异常": "反义：“异常”指不符合一般情况，与这一义项的“正常”相对。", "迅速": "“迅速”指速度快，与这一义项的“正常”无近义或反义关系。", "漂亮": "“漂亮”指好看，与这一义项的“正常”无近义或反义关系。", "重要": "“重要”指作用或价值大，与这一义项的“正常”无近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异常", "is_correct": true, "explanation": "反义：“异常”指不符合一般情况，与这一义项的“正常”相对。"}, {"text": "明显", "is_correct": false, "explanation": "“明显”指容易看出，与这一义项的“正常”无近义或反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”指空间大，与这一义项的“正常”无近义或反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”指态度严肃踏实，与这一义项的“正常”无近义或反义关系。"}], "correct_answer": "异常", "explanations": {"异常": "反义：“异常”指不符合一般情况，与这一义项的“正常”相对。", "明显": "“明显”指容易看出，与这一义项的“正常”无近义或反义关系。", "宽敞": "“宽敞”指空间大，与这一义项的“正常”无近义或反义关系。", "认真": "“认真”指态度严肃踏实，与这一义项的“正常”无近义或反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "符合一般的情况；没有异常的。", "primary_collocate": null, "pronunciation": "zhèng cháng", "ipa": "ʈʂɤŋ˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你的体温很正常，不用担心。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他的血压完全正常。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数字在正常范围内。", "target_word": "正常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子这个年纪爱哭是正常现象。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水温正常的时候，机器才能开。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "检查结果一切正常，你可以回家了。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天睡七八个小时是正常的。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种情况很正常，别太紧张。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的心跳比正常的时候快很多。", "target_word": "正常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化验结果都在正常水平。", "target_word": "正常", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正常", "label": "否定形式"}, {"form": "正常化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指数值、状态、现象等符合一般标准，没有异常", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb8d477-42ee-4005-b0c4-97766b2fc790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正常", "is_correct": true, "explanation": "“正常”指符合一般情况，与“不用担心”的语境相符。"}, {"text": "异常", "is_correct": false, "explanation": "语义：“异常”指不符合一般情况，“体温很异常”与“不用担心”相矛盾。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”说明情况很糟，与“不用担心”冲突。"}, {"text": "奇怪", "is_correct": false, "explanation": "搭配：“奇怪”多用于人的言行或事情，不用来描述体温。"}], "explanations": {"正常": "“正常”指符合一般情况，与“不用担心”的语境相符。", "异常": "语义：“异常”指不符合一般情况，“体温很异常”与“不用担心”相矛盾。", "严重": "语义：“严重”说明情况很糟，与“不用担心”冲突。", "奇怪": "搭配：“奇怪”多用于人的言行或事情，不用来描述体温。"}, "sentence_index": 0, "correct_answer": "正常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的答案完全正常。", "explanation": "这里应该用〈正确〉。正确用于对错、答案；正常说情况符合一般标准，不用来评价答案的对错。"}, {"text": "我对这座城市很正常。", "explanation": "这里应该用〈熟悉〉。熟悉指了解、常见，“正常”不能用来说明人对某地的了解程度。"}, {"text": "这家餐厅做的菜很正常，一吃就是四川味道。", "explanation": "这里应该用〈正宗〉。正宗指真正的、地道的，用于菜、味道、来源；正常说情况不异常，不表示是否地道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正常", "is_correct": true, "explanation": "“正常”指符合一般标准，说睡七八个小时属于一般情况，与句意相符。"}, {"text": "危险", "is_correct": false, "explanation": "语义：“危险”指有生命或安全的威胁，睡七八个小时不能说是危险的。"}, {"text": "荒谬", "is_correct": false, "explanation": "语义：“荒谬”指不合道理、极其可笑，与常见的睡眠时长相悖。"}, {"text": "紧张", "is_correct": false, "explanation": "搭配：“紧张”形容心情或局势，不用来描述睡眠时长。"}], "explanations": {"正常": "“正常”指符合一般标准，说睡七八个小时属于一般情况，与句意相符。", "危险": "语义：“危险”指有生命或安全的威胁，睡七八个小时不能说是危险的。", "荒谬": "语义：“荒谬”指不合道理、极其可笑，与常见的睡眠时长相悖。", "紧张": "搭配：“紧张”形容心情或局势，不用来描述睡眠时长。"}, "sentence_index": 6, "correct_answer": "正常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数字计算得非常正常。", "explanation": "这里应该用〈精确〉。精确指准确、没有误差，用于计算、测量；正常说情况符合一般标准，不用来评价计算的准确度。"}, {"text": "这个房间收拾得很正常。", "explanation": "这里应该用〈整齐〉。整齐形容排列有序，用于房间、物品；正常不用来描述收拾后的样子。"}, {"text": "这家小店经营很正常，营业执照都没有。", "explanation": "这里应该用〈正规〉。正规指符合规范、合法，用于店铺、经营；正常说情况符合一般标准，不用来说经营是否合法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检查结果没正常，需要再做一次检查。", "corrected_sentence": "检查结果不正常，需要再做一次检查。", "error_description": "“正常”的否定形式用“不”，应说“不正常”，不说“没正常”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的检查结果很正常化，别担心。", "corrected_sentence": "这次的检查结果很正常，别担心。", "error_description": "“正常化”是动词性复合词，表示“使…变得正常”，不能直接被“很”修饰；应说“很正常”，去掉“化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87529, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶化", "is_correct": true, "explanation": "恶化：情况向坏的方向变化，与“向好”的意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“向好”没有反义关系，不能表示情况变坏。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“向好”没有反义关系，不能表示情况变坏。"}, {"text": "写信", "is_correct": false, "explanation": "与“向好”没有反义关系，不能表示情况变坏。"}], "correct_answer": "恶化", "explanations": {"恶化": "恶化：情况向坏的方向变化，与“向好”的意思相反。", "唱歌": "与“向好”没有反义关系，不能表示情况变坏。", "睡觉": "与“向好”没有反义关系，不能表示情况变坏。", "写信": "与“向好”没有反义关系，不能表示情况变坏。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
