INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87529, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "向好是事情在变好，朝着好的方向走。", "primary_collocate": null, "pronunciation": "xiàng hǎo", "ipa": "ɕiaŋ˥˩ xau˨˩˦", "syllable_count": 2, "sentences": [{"text": "天气慢慢向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病情向好了。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的生活正在向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济开始向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情会向好的。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的环境一年比一年向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场的情况向好了。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩慢慢向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她的身体向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的关系正在向好。", "target_word": "向好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "经济、形势、市场、病情、关系等情况朝好的方向发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e50ef452-9f17-49b2-bfd5-efaaf3235ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87529, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向好", "is_correct": true, "explanation": "向好：情况朝好的方向变化，这里指天气逐渐转好。"}, {"text": "出发", "is_correct": false, "explanation": "语义：天气不会出发，“出发”只用于人或交通工具。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”的主语应是人，不能说“天气报名”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：天气不会参加考试，与句子的语境不符。"}], "explanations": {"向好": "向好：情况朝好的方向变化，这里指天气逐渐转好。", "出发": "语义：天气不会出发，“出发”只用于人或交通工具。", "报名": "搭配：“报名”的主语应是人，不能说“天气报名”。", "考试": "语义：天气不会参加考试，与句子的语境不符。"}, "sentence_index": 0, "correct_answer": "向好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间打扫以后向好了。", "explanation": "这里应该用〈变好〉。向好多用于天气、病情、形势等情况，房间是具体事物，应说“变好”。"}, {"text": "这把椅子修好以后向好了。", "explanation": "这里应该用〈变好〉。椅子是具体物品，不说“向好”，应说“变好”。"}, {"text": "这件衣服洗完以后向好了。", "explanation": "这里应该用〈变好〉。衣服是具体物品，状态变化应说“变好”，不说“向好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向好", "is_correct": true, "explanation": "向好：情况朝好的方向发展，这里指市场的情况转好。"}, {"text": "生病", "is_correct": false, "explanation": "语义：只有人或动物会生病，市场的情况不会生病。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：只有学生能毕业，与主语“市场的情况”不符。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：退休只用于人，不能说“市场的情况退休”。"}], "explanations": {"向好": "向好：情况朝好的方向发展，这里指市场的情况转好。", "生病": "语义：只有人或动物会生病，市场的情况不会生病。", "毕业": "语义：只有学生能毕业，与主语“市场的情况”不符。", "退休": "搭配：退休只用于人，不能说“市场的情况退休”。"}, "sentence_index": 6, "correct_answer": "向好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字练了一个月，向好了很多。", "explanation": "这里应该用〈进步〉。向好用于天气、病情、形势等情况，字的水平应说“进步”。"}, {"text": "这盘菜加了盐以后向好了。", "explanation": "这里应该用〈好吃〉。向好用于情况的发展，菜的口味应说“好吃”。"}, {"text": "我的手机换了电池以后向好了。", "explanation": "这里应该用〈变好〉。手机是具体事物，状态变化应说“变好”，不说“向好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经济很向好。", "corrected_sentence": "经济正在向好。", "error_description": "副词误用：“向好”是表示变化趋势的动词，不能受程度副词“很”修饰，应用“正在”“开始”等表示变化进行。错误形式“很向好”，正确形式“正在向好”，应为“经济正在向好。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市场的情况逐渐向好过。", "corrected_sentence": "市场的情况逐渐向好了。", "error_description": "体标记错误：表示变化已经出现应用“了”，“过”表示过去的经历，不能与“逐渐”这种持续发展的变化连用。错误形式“向好过”，正确形式“向好了”，应为“市场的情况逐渐向好了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
