INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87531, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带头是走在最前面，让别人跟着你做。", "primary_collocate": null, "pronunciation": "dài tóu", "ipa": "taɪ˥˩ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "爬山的时候，老李带头走在前面，我们跟着他。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗带头跑进了树林，大家都跟了上去。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时，老师带头走，学生们排队跟着。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雁飞向南方，总是老雁带头飞在前面。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，导游带头走进山洞，我们一个接一个跟着。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带头走出教室，同学们也跟着出去了。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪的路很滑，爸爸带头走，我们踩着他的脚印。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路太窄，请你带头走，我们跟在后面。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍出发了，旗手带头走在最前面。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有一条河，小王带头过河，大家慢慢跟上。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带了头", "label": "体标"}, {"form": "带头人", "label": "复合"}], "register": "中性", "sense_fingerprint": "走在队伍最前面，别人跟随", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87531, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。带头 dài tóu：走在最前面，让别人跟着。"}, {"text": "大头", "is_correct": false, "explanation": "大头 dàtóu 与 dài 的韵母不同（a 与 ai），意思是大脑袋。"}, {"text": "抬头", "is_correct": false, "explanation": "抬头 táitóu 与 dài 的声母和声调都不同（t 与 d），意思是把头抬起来。"}, {"text": "盖头", "is_correct": false, "explanation": "盖头 gàitóu 与 dài 的声母不同（g 与 d），意思是盖在头上的布。"}, {"text": "地头", "is_correct": false, "explanation": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}], "explanations": {"带头": "正确。带头 dài tóu：走在最前面，让别人跟着。", "大头": "大头 dàtóu 与 dài 的韵母不同（a 与 ai），意思是大脑袋。", "抬头": "抬头 táitóu 与 dài 的声母和声调都不同（t 与 d），意思是把头抬起来。", "盖头": "盖头 gàitóu 与 dài 的声母不同（g 与 d），意思是盖在头上的布。", "地头": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}, "sentence_index": null, "correct_answer": "带头"}, "level_3": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。“带头”表示走在最前面，带着大家走，与“走在前面”“跟着他”相符。"}, {"text": "落后", "is_correct": false, "explanation": "语义：落后是走在后面，与句中“走在前面”相反。"}, {"text": "殿后", "is_correct": false, "explanation": "语义：殿后是走在队伍最后，与“走在前面”矛盾。"}, {"text": "尾随", "is_correct": false, "explanation": "配价：尾随要跟在别人身后，“尾随走在前面”的搭配不当。"}], "explanations": {"带头": "正确。“带头”表示走在最前面，带着大家走，与“走在前面”“跟着他”相符。", "落后": "语义：落后是走在后面，与句中“走在前面”相反。", "殿后": "语义：殿后是走在队伍最后，与“走在前面”矛盾。", "尾随": "配价：尾随要跟在别人身后，“尾随走在前面”的搭配不当。"}, "sentence_index": 0, "correct_answer": "带头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他带头走在队伍的末尾，大家都跟着他。", "explanation": "这里应该用〈殿后〉。“带头”指走在最前面引路，与“末尾”矛盾；走在队伍最后应说〈殿后〉。"}, {"text": "他带头躲在队伍中间，不肯走在前面。", "explanation": "这里应该用〈故意〉。“带头”要求走在最前面，躲在中间、不肯走在前面，应说“他故意躲在队伍中间”。"}, {"text": "小王带头躲在树后，不让别人看见。", "explanation": "这里应该用〈藏〉。“带头”是走在前面引路，躲在树后不让人看见应说〈藏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87531, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。带头 dài tóu：走在最前面，让别人跟着。"}, {"text": "盖头", "is_correct": false, "explanation": "盖头 gàitóu 与 dài 的声母不同（g 与 d），意思是盖在头上的布。"}, {"text": "对头", "is_correct": false, "explanation": "对头 duìtóu 与 dài 的韵母不同（ui 与 ai），意思是仇敌。"}, {"text": "来头", "is_correct": false, "explanation": "来头 láitóu 与 dài 的声母和声调都不同（l 与 d），意思是背景和来历。"}, {"text": "地头", "is_correct": false, "explanation": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}], "explanations": {"带头": "正确。带头 dài tóu：走在最前面，让别人跟着。", "盖头": "盖头 gàitóu 与 dài 的声母不同（g 与 d），意思是盖在头上的布。", "对头": "对头 duìtóu 与 dài 的韵母不同（ui 与 ai），意思是仇敌。", "来头": "来头 láitóu 与 dài 的声母和声调都不同（l 与 d），意思是背景和来历。", "地头": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}, "sentence_index": null, "correct_answer": "带头"}, "level_3": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。“带头走”指爸爸走在最前面，我们踩着他的脚印，符合语境。"}, {"text": "断后", "is_correct": false, "explanation": "语域：断后是书面、军事用语，与这段口语叙述不协调；语义上也与“踩着他的脚印”不符。"}, {"text": "出走", "is_correct": false, "explanation": "语义：出走是离开家或某处，与“踩着他的脚印”前行矛盾。"}, {"text": "逃走", "is_correct": false, "explanation": "语义：逃走是躲开、跑掉，与“带头走，我们跟着”不符。"}], "explanations": {"带头": "正确。“带头走”指爸爸走在最前面，我们踩着他的脚印，符合语境。", "断后": "语域：断后是书面、军事用语，与这段口语叙述不协调；语义上也与“踩着他的脚印”不符。", "出走": "语义：出走是离开家或某处，与“踩着他的脚印”前行矛盾。", "逃走": "语义：逃走是躲开、跑掉，与“带头走，我们跟着”不符。"}, "sentence_index": 6, "correct_answer": "带头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板带头躲在最后面，员工们都找不到他。", "explanation": "这里应该用〈藏〉。“带头”指走在最前面引路，躲在最后面让人找不到，应说〈藏〉在最后面。"}, {"text": "村长带头走在人群中间，一声不吭。", "explanation": "这里应该用〈混在〉。“带头”要求走在最前面，走在人群中间、一声不吭应说〈混在〉人群里。"}, {"text": "班长带头落在大家后面，一直拖着不动。", "explanation": "这里应该用〈掉队〉。“带头”要求走在最前面，落在大家后面应说“班长掉队了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师带头了走在前面，学生跟着她。", "corrected_sentence": "老师带头走在前面，学生跟着她。", "error_description": "错误：“了”放错了位置。“带头”在这里修饰后面的“走”，中间不能加“了”，应说“老师带头走在前面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸明天带了头走在最前面，我们跟着他。", "corrected_sentence": "爸爸明天带头走在最前面，我们跟着他。", "error_description": "错误：“带了头”表示动作已经完成，与将来时间“明天”矛盾。“带头”后不能加“了”，应改为“爸爸明天带头走在最前面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
