INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "最先行动，给大家做出榜样。", "primary_collocate": null, "pronunciation": "dài tóu", "ipa": "taɪ˥˩ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "打扫教室的时候，班长带头干活，大家也都动手了。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想节约用水，我们先要自己带头做。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理带头加班，同事们谁也不好意思回家。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带头戒烟，全家人都很支持他。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里要修路，村长带头拿出了一千块钱。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护环境，老师带头不用一次性筷子。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是队长，训练时总是带头认真练习。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不愿意先说，最后小李带头发言了。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的老员工带头学新技术，年轻人也很努力。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了少用塑料袋，社区干部带头用布袋买菜。", "target_word": "带头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带了头", "label": "体标"}, {"form": "带头人", "label": "复合"}], "register": "中性", "sense_fingerprint": "率先行动，为大家做榜样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87532, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。带头 dài tóu：率先行动，给大家做榜样。"}, {"text": "大头", "is_correct": false, "explanation": "大头 dàtóu 与 dài 的韵母不同（a 与 ai），意思是大脑袋。"}, {"text": "抬头", "is_correct": false, "explanation": "抬头 táitóu 与 dài 的声母和声调都不同（t 与 d），意思是把头抬起来。"}, {"text": "盖头", "is_correct": false, "explanation": "盖头 gàitóu 与 dài 的声母不同（g 与 d），意思是盖在头上的布。"}, {"text": "地头", "is_correct": false, "explanation": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}], "explanations": {"带头": "正确。带头 dài tóu：率先行动，给大家做榜样。", "大头": "大头 dàtóu 与 dài 的韵母不同（a 与 ai），意思是大脑袋。", "抬头": "抬头 táitóu 与 dài 的声母和声调都不同（t 与 d），意思是把头抬起来。", "盖头": "盖头 gàitóu 与 dài 的声母不同（g 与 d），意思是盖在头上的布。", "地头": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}, "sentence_index": null, "correct_answer": "带头"}, "level_3": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。“带头干活”指率先动手、给大家做表率，与“大家也都动手了”相符。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：拖延是故意慢做，与“大家也都动手了”的积极语境矛盾。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：偷懒是不干活，与“班长带头干活”矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：躲避多接“责任、困难”等，说“躲避干活”搭配不当。"}], "explanations": {"带头": "正确。“带头干活”指率先动手、给大家做表率，与“大家也都动手了”相符。", "拖延": "语义：拖延是故意慢做，与“大家也都动手了”的积极语境矛盾。", "偷懒": "语义：偷懒是不干活，与“班长带头干活”矛盾。", "躲避": "搭配：躲避多接“责任、困难”等，说“躲避干活”搭配不当。"}, "sentence_index": 0, "correct_answer": "带头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他带头最后一个动手，还没做完就走了。", "explanation": "这里应该用〈最后才〉。“带头”指最先行动，最后一个动手应说“他最后才动手”。"}, {"text": "他带头躲在角落里，不肯动手。", "explanation": "这里应该用〈袖手旁观〉。“带头”要求最先动手，躲在角落不肯动手应说〈袖手旁观〉。"}, {"text": "他带头走在最后面，怕大家掉队。", "explanation": "这里应该用〈殿后〉。“带头”是率先行动、走在前面，走在最后面照看队伍应说〈殿后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87532, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。带头 dài tóu：率先行动，给大家做榜样。"}, {"text": "大头", "is_correct": false, "explanation": "大头 dàtóu 与 dài 的韵母不同（a 与 ai），意思是大脑袋。"}, {"text": "对头", "is_correct": false, "explanation": "对头 duìtóu 与 dài 的韵母不同（ui 与 ai），意思是仇敌。"}, {"text": "来头", "is_correct": false, "explanation": "来头 láitóu 与 dài 的声母和声调都不同（l 与 d），意思是背景和来历。"}, {"text": "地头", "is_correct": false, "explanation": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}], "explanations": {"带头": "正确。带头 dài tóu：率先行动，给大家做榜样。", "大头": "大头 dàtóu 与 dài 的韵母不同（a 与 ai），意思是大脑袋。", "对头": "对头 duìtóu 与 dài 的韵母不同（ui 与 ai），意思是仇敌。", "来头": "来头 láitóu 与 dài 的声母和声调都不同（l 与 d），意思是背景和来历。", "地头": "地头 dìtóu 与 dài 的韵母不同（i 与 ai），意思是田地的边上。"}, "sentence_index": null, "correct_answer": "带头"}, "level_3": {"options": [{"text": "带头", "is_correct": true, "explanation": "正确。“带头认真练习”指率先做好榜样，与“队长”和“训练时”的语境相符。"}, {"text": "旁观", "is_correct": false, "explanation": "语义：旁观是站在一旁看，与“认真练习”矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：逃避是躲开应做的事，与“认真练习”矛盾。"}, {"text": "抗拒", "is_correct": false, "explanation": "搭配：抗拒多用于命令、改革等，不能说“抗拒认真练习”。"}], "explanations": {"带头": "正确。“带头认真练习”指率先做好榜样，与“队长”和“训练时”的语境相符。", "旁观": "语义：旁观是站在一旁看，与“认真练习”矛盾。", "逃避": "语义：逃避是躲开应做的事，与“认真练习”矛盾。", "抗拒": "搭配：抗拒多用于命令、改革等，不能说“抗拒认真练习”。"}, "sentence_index": 6, "correct_answer": "带头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带头站在旁边看热闹，不肯动手。", "explanation": "这里应该用〈旁观〉。“带头”要求先动手，站在旁边看热闹应说〈旁观〉。"}, {"text": "他带头等别人都做完了，才慢慢动手。", "explanation": "这里应该用〈跟随〉。“带头”是最先行动，等别人做完才动手应说〈跟随〉。"}, {"text": "班长带头躲在宿舍里，一直不肯干活。", "explanation": "这里应该用〈偷懒〉。“带头”要求最先行动做榜样，躲着不肯干活是偷懒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师带头着做操，学生们都跟着做。", "corrected_sentence": "老师带头做操，学生们都跟着做。", "error_description": "错误：“带头”后面多加了“着”。“带头”不带“着”，应说“老师带头做操”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长明天带了头学习，同学们也都认真读书。", "corrected_sentence": "班长明天带头学习，同学们也都认真读书。", "error_description": "错误：“带了头”表示动作已经完成，与将来时间“明天”矛盾。“带头”后不能加“了”，应改为“班长明天带头学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
