INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "菩萨是庙里受人拜的神，心肠很好，爱帮助别人；也比喻心肠好、乐于帮助人的人。", "primary_collocate": null, "pronunciation": "pú sà", "ipa": "pʰu˧˥ sa˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶每天早上去庙里拜菩萨。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她像菩萨一样好心。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人来庙里给菩萨烧香。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对着菩萨说出了自己的心愿。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她相信菩萨会帮助好人。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人遇到难事，就去求菩萨。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师像菩萨一样，常常帮助穷学生。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在菩萨面前点了三支香。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候不信菩萨，现在也不信。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菩萨保佑你平平安安！", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "菩薩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "庙里受人拜的、心肠好爱帮人的神；也比喻心肠好的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是庙里受人拜的神，句子说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“拜”的对象是神佛或尊长，不能搭配“课本”。"}, {"text": "菩萨", "is_correct": true, "explanation": "正确：菩萨是庙里受人拜的神，与“去庙里拜”的语境一致。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不能被拜，与庙里的宗教场景不符。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不是庙里受人拜的神，句子说不通。", "课本": "搭配：“拜”的对象是神佛或尊长，不能搭配“课本”。", "菩萨": "正确：菩萨是庙里受人拜的神，与“去庙里拜”的语境一致。", "电视": "语义：电视是电器，不能被拜，与庙里的宗教场景不符。"}, "sentence_index": 0, "correct_answer": "菩萨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在希腊神话里，宙斯是最高的菩萨。", "explanation": "这里应该用〈神〉。菩萨是佛教中的人物，希腊神话的主神不属于佛教，要说“神”。"}, {"text": "菩萨在天上打雷。", "explanation": "这里应该用〈雷公〉。菩萨是佛教中救度众生的人物，不掌管雷电；雷公是民间神话中掌管打雷的神。"}, {"text": "月亮上住着一位美丽的菩萨。", "explanation": "这里应该用〈仙女〉。菩萨是佛教中的人物，月宫里的美丽女子属于民间神话，要说“仙女”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有心肠，不会常常帮助穷学生，与句中的善心形象相反。"}, {"text": "菩萨", "is_correct": true, "explanation": "正确：菩萨是心肠好、爱帮助人的神，用来比喻老师的善心。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎凶猛，与“帮助穷学生”的善良形象相悖。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“像……一样”比喻要用有具体善心形象的事物，“数学”不能用来比喻人的心肠。"}], "explanations": {"石头": "语义：石头没有心肠，不会常常帮助穷学生，与句中的善心形象相反。", "菩萨": "正确：菩萨是心肠好、爱帮助人的神，用来比喻老师的善心。", "老虎": "语义：老虎凶猛，与“帮助穷学生”的善良形象相悖。", "数学": "搭配：“像……一样”比喻要用有具体善心形象的事物，“数学”不能用来比喻人的心肠。"}, "sentence_index": 6, "correct_answer": "菩萨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "菩萨掌管着天庭的一切事务。", "explanation": "这里应该用〈玉皇大帝〉。菩萨是佛教中救度众生的人物，不掌管天庭；玉皇大帝是道教天界的主神，管理天庭事务。"}, {"text": "孔子是古代的菩萨。", "explanation": "这里应该用〈圣人〉。菩萨是佛教中救度众生的人物，孔子属于儒家，要说“圣人”。"}, {"text": "教堂里祈祷的是菩萨。", "explanation": "这里应该用〈上帝〉。菩萨属于佛教，教堂里祈祷的对象是基督教的上帝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庙里那只菩萨很灵。", "corrected_sentence": "庙里那位菩萨很灵。", "error_description": "量词错误：“菩萨”作为神，量词应用“位”，不能用“只”。正确说法是“庙里那位菩萨很灵”，“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对孩子菩萨一样耐心。", "corrected_sentence": "她对孩子像菩萨一样耐心。", "error_description": "漏词错误：比喻“像……一样”的句式中，“像”不能省。正确说法是“她对孩子像菩萨一样耐心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
