INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "佛教中指地位仅次于佛、发愿救度众生的人物；泛指神佛的像。", "primary_collocate": null, "pronunciation": "pú sà", "ipa": "pʰu˧˥ sa˥˩", "syllable_count": 2, "sentences": [{"text": "观音是一位很有名的菩萨。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在佛教里，菩萨的地位仅次于佛。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菩萨发愿要帮助所有的人。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙里有一尊很大的菩萨。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把菩萨擦得很干净。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，菩萨可以帮人离开痛苦。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里的菩萨有一千多年的历史。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "佛教里有很多菩萨，观音只是其中一位。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客在大殿里看到了三尊菩萨。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学佛多年，想成为一位菩萨。", "target_word": "菩萨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "尊", "label": "量词"}, {"form": "菩薩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "佛教中地位仅次于佛的人物，也指神佛的像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌星", "is_correct": false, "explanation": "语义：观音是佛教中的人物，不是歌星，句意不通。"}, {"text": "菩萨", "is_correct": true, "explanation": "正确：观音是佛教中地位仅次于佛的人物，与“很有名的菩萨”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是职业，与佛教中发愿救度众生的人物身份不符。"}, {"text": "老头儿", "is_correct": false, "explanation": "语义：观音是佛教中的人物，不是普通的老头儿，句意不通。"}], "explanations": {"歌星": "语义：观音是佛教中的人物，不是歌星，句意不通。", "菩萨": "正确：观音是佛教中地位仅次于佛的人物，与“很有名的菩萨”相符。", "厨师": "语义：厨师是职业，与佛教中发愿救度众生的人物身份不符。", "老头儿": "语义：观音是佛教中的人物，不是普通的老头儿，句意不通。"}, "sentence_index": 0, "correct_answer": "菩萨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "菩萨坐在凌霄宝殿上。", "explanation": "这里应该用〈玉皇大帝〉。菩萨是佛教中救度众生的人物，凌霄宝殿是道教天庭的殿宇，坐在那里的是玉皇大帝。"}, {"text": "希腊神话里的菩萨都住在奥林匹斯山上。", "explanation": "这里应该用〈神〉。菩萨是佛教中的人物，希腊神话的众神属于另一个神话体系，要说“神”。"}, {"text": "教堂的穹顶上画着一位很美的菩萨。", "explanation": "这里应该用〈天使〉。菩萨是佛教的人物，教堂穹顶上画的是基督教的天使。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，保质期很短，不可能有一千多年的历史。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是近代才出现的电子产品，不可能有一千多年的历史。"}, {"text": "菩萨", "is_correct": true, "explanation": "正确：山洞里的菩萨像有一千多年的历史，与“有……历史”的搭配相符。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“有……历史”通常说古迹、文物等事物，不能用来说“小学生”。"}], "explanations": {"牛奶": "语义：牛奶是饮品，保质期很短，不可能有一千多年的历史。", "手机": "语义：手机是近代才出现的电子产品，不可能有一千多年的历史。", "菩萨": "正确：山洞里的菩萨像有一千多年的历史，与“有……历史”的搭配相符。", "小学生": "搭配：“有……历史”通常说古迹、文物等事物，不能用来说“小学生”。"}, "sentence_index": 6, "correct_answer": "菩萨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "菩萨创造了世界。", "explanation": "这里应该用〈上帝〉。菩萨是佛教中救度众生的人物，不是创造世界的神；基督教认为上帝创造了世界。"}, {"text": "孟子是儒家的一位菩萨。", "explanation": "这里应该用〈圣人〉。菩萨是佛教中的人物，孟子属于儒家，要说“圣人”。"}, {"text": "嫦娥是月宫里的菩萨。", "explanation": "这里应该用〈女神〉。菩萨是佛教中的人物，嫦娥属于民间神话，要说“女神”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寺庙的大殿里供着一把很大的菩萨。", "corrected_sentence": "寺庙的大殿里供着一尊很大的菩萨。", "error_description": "量词错误：菩萨像要用“尊”计量，不能用“把”。“把”用于有柄或可以握的东西。正确说法是“寺庙的大殿里供着一尊很大的菩萨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把那只菩萨擦得很亮。", "corrected_sentence": "工人们把那尊菩萨擦得很亮。", "error_description": "量词错误：菩萨像要用“尊”计量，不能用“只”。“只”多用于动物等，正确说法是“那尊菩萨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
