INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87537, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命是人和动物活着的力气，没有了就会死去。", "primary_collocate": null, "pronunciation": "mìng", "ipa": "miŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这只小狗受了伤，但命保住了，没有死。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生救了他一条命。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在火灾中丢了命。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，人只有一条命，要好好活着。", "target_word": "命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼离开水，命就保不住了。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟受了重伤，但命保住了。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没了命，什么都没有了。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了救孩子，不顾自己的命跑进水里。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们常说猫有九条命。", "target_word": "命", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "司机开得太快，差点没了命。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "救命", "label": "复合"}, {"form": "要命", "label": "复合"}], "register": "口语", "sense_fingerprint": "人和动物活着的生命力，失去就会死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87537, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：命（mìng），指人或动物的生命。"}, {"text": "名", "is_correct": false, "explanation": "míng（第二声）与 mìng（第四声）声调不同，意思是名字。"}, {"text": "病", "is_correct": false, "explanation": "b 与 m 声母不同，意思是疾病。"}, {"text": "定", "is_correct": false, "explanation": "d 与 m 声母不同，意思是确定。"}], "explanations": {"命": "正确答案：命（mìng），指人或动物的生命。", "名": "míng（第二声）与 mìng（第四声）声调不同，意思是名字。", "病": "b 与 m 声母不同，意思是疾病。", "定": "d 与 m 声母不同，意思是确定。"}, "sentence_index": null, "correct_answer": "命"}, "level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：「命保住了」指小狗活了下来，没有死。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：尾巴保住了不能说明小狗没有死。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字与生死无关，句意说不通。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵保住了与“没有死”没有关系。"}], "explanations": {"命": "正确答案：「命保住了」指小狗活了下来，没有死。", "尾巴": "语义：尾巴保住了不能说明小狗没有死。", "名字": "语义：名字与生死无关，句意说不通。", "耳朵": "语义：耳朵保住了与“没有死”没有关系。"}, "sentence_index": 0, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗的命是三岁。", "explanation": "这里应该用〈年龄〉。说动物的岁数要用「年龄」，「命」指活着的力气，不指岁数。"}, {"text": "老人说，人只有一只命，要好好活着。", "explanation": "量词不当：这里应该用〈条〉。「命」用「条」计量，「只」多用于动物或成对的器物。"}, {"text": "这台机器的命是白色的。", "explanation": "这里应该用〈颜色〉。形容物体的颜色要用「颜色」，「命」指生命，不能用来说颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87537, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：命（mìng），指人或动物的生命。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 mìng（第四声）声调不同，意思是明亮。"}, {"text": "镜", "is_correct": false, "explanation": "j 与 m 声母不同，声调相同（均为第四声），意思是镜子。"}, {"text": "病", "is_correct": false, "explanation": "b 与 m 声母不同，意思是疾病。"}], "explanations": {"命": "正确答案：命（mìng），指人或动物的生命。", "明": "míng（第二声）与 mìng（第四声）声调不同，意思是明亮。", "镜": "j 与 m 声母不同，声调相同（均为第四声），意思是镜子。", "病": "b 与 m 声母不同，意思是疾病。"}, "sentence_index": null, "correct_answer": "命"}, "level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：「没了命」指人失去了生命。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「没了天气」不能成立，与「什么都没有了」的语境不合。"}, {"text": "影子", "is_correct": false, "explanation": "语义：「没了影子」不等于什么都没有了，句意不合。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：「没了黑板」一般不这样说，与「什么都没有了」的语境不合。"}], "explanations": {"命": "正确答案：「没了命」指人失去了生命。", "天气": "语义：「没了天气」不能成立，与「什么都没有了」的语境不合。", "影子": "语义：「没了影子」不等于什么都没有了，句意不合。", "黑板": "搭配：「没了黑板」一般不这样说，与「什么都没有了」的语境不合。"}, "sentence_index": 6, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的命已经五十岁了，还在工作。", "explanation": "这里应该用〈年龄〉。「命」指生命，说人的岁数要用「年龄」，「命」不能计岁数。"}, {"text": "他只有一根命，一定要珍惜。", "explanation": "量词不当：「根」用于细长的东西，不能计量「命」，应用〈条〉。"}, {"text": "这个人的命有一米八，能扛起一袋米。", "explanation": "这里应该用〈身高〉。「身高」指人的高矮，「命」指生命，不能用来说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只有一只命，所以要小心。", "corrected_sentence": "他只有一条命，所以要小心。", "error_description": "量词错误：正确应为「一条命」。「命」用「条」计量，「只」多用于动物或成对的器物，不能用来计量「命」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了救孩子，差点丢了一只命。", "corrected_sentence": "他为了救孩子，差点丢了一条命。", "error_description": "量词错误：正确应为「一条命」。「命」用「条」计量，「只」多用于动物或成对的器物，不能用来计量「命」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
