INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生命；性命。", "primary_collocate": null, "pronunciation": "mìng", "ipa": "miŋ˥˩", "syllable_count": 1, "sentences": [{"text": "消防员救了三个人的命。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的命是医生救回来的。", "target_word": "命", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场大水要了很多人的命。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保住自己的命，他们跑上了山。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱没了可以再赚，命没了就不行。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大夫说，再晚一点，他的命就没了。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也不能随便拿别人的命开玩笑。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他捡回了一条命。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士们用自己的命保护了村子。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车喝酒是拿自己和别人的命冒险。", "target_word": "命", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "救命", "label": "复合"}, {"form": "要命", "label": "复合"}], "register": "口语", "sense_fingerprint": "一个人的性命，生死攸关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：命（mìng），指一个人的性命。"}, {"text": "名", "is_correct": false, "explanation": "míng（第二声）与 mìng（第四声）声调不同，意思是名字。"}, {"text": "病", "is_correct": false, "explanation": "b 与 m 声母不同，意思是疾病。"}, {"text": "令", "is_correct": false, "explanation": "l 与 m 声母不同，意思是命令。"}], "explanations": {"命": "正确答案：命（mìng），指一个人的性命。", "名": "míng（第二声）与 mìng（第四声）声调不同，意思是名字。", "病": "b 与 m 声母不同，意思是疾病。", "令": "l 与 m 声母不同，意思是命令。"}, "sentence_index": null, "correct_answer": "命"}, "level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：「救了三个人的命」指救了三个人的性命。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「救」不能与「脾气」搭配，说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「救了三个人的颜色」说不通，颜色不是可以被救的对象。"}, {"text": "方向", "is_correct": false, "explanation": "语义：「方向」不能被救，句子说的是人的性命。"}], "explanations": {"命": "正确答案：「救了三个人的命」指救了三个人的性命。", "脾气": "搭配：「救」不能与「脾气」搭配，说不通。", "颜色": "语义：「救了三个人的颜色」说不通，颜色不是可以被救的对象。", "方向": "语义：「方向」不能被救，句子说的是人的性命。"}, "sentence_index": 0, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的命已经五十岁了，还在工作。", "explanation": "这里应该用〈年龄〉。「命」指生命，说人的岁数要用「年龄」，「命」不能计岁数。"}, {"text": "这个人只有一根命，要好好珍惜。", "explanation": "量词不当：「根」用于细长的东西，不能计量「命」，应用〈条〉。"}, {"text": "这件衣服的命很贵。", "explanation": "这里应该用〈价格〉。说东西的价钱要用「价格」，「命」指生命，不能用来说物品的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87538, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：命（mìng），指一个人的性命。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 mìng（第四声）声调不同，意思是明亮。"}, {"text": "名", "is_correct": false, "explanation": "míng（第二声）与 mìng（第四声）声调不同，意思是名字。"}, {"text": "定", "is_correct": false, "explanation": "d 与 m 声母不同，意思是确定。"}], "explanations": {"命": "正确答案：命（mìng），指一个人的性命。", "明": "míng（第二声）与 mìng（第四声）声调不同，意思是明亮。", "名": "míng（第二声）与 mìng（第四声）声调不同，意思是名字。", "定": "d 与 m 声母不同，意思是确定。"}, "sentence_index": null, "correct_answer": "命"}, "level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "正确答案：「拿别人的命开玩笑」指拿别人的性命当玩笑。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：「筷子」是吃饭的工具，「拿别人的筷子开玩笑」说不通，句子说的是别人的性命。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」不能拿来开玩笑，与句意不合。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：「开玩笑」的对象一般是人的身份、名誉、性命等，「钥匙」不能这样搭配。"}], "explanations": {"命": "正确答案：「拿别人的命开玩笑」指拿别人的性命当玩笑。", "筷子": "语义：「筷子」是吃饭的工具，「拿别人的筷子开玩笑」说不通，句子说的是别人的性命。", "脚步": "语义：「脚步」不能拿来开玩笑，与句意不合。", "钥匙": "搭配：「开玩笑」的对象一般是人的身份、名誉、性命等，「钥匙」不能这样搭配。"}, "sentence_index": 6, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的命有三百公斤，开起来很费力。", "explanation": "这里应该用〈重量〉。说物体的重量要用「重量」，「命」指生命，不能用来说重量。"}, {"text": "他只有一座命，要好好珍惜。", "explanation": "量词不当：「座」用于山、房屋等大型物体，不能计量「命」，应用〈条〉。"}, {"text": "这张桌子的命很深。", "explanation": "这里应该用〈颜色〉。形容物体的颜色要用「颜色」，「命」指生命，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员用绳子救了他一根命。", "corrected_sentence": "消防员用绳子救了他一条命。", "error_description": "量词错误：正确应为「一条命」。「命」用「条」计量，「根」用于细长的东西，不能用来计量「命」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事差点了要他的命。", "corrected_sentence": "这件事差点要了他的命。", "error_description": "语序错误：「了」应紧跟动词「要」，应说「差点要了他的命」，「差点了要他的命」中「了」位置不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
