INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "幅度是说一样东西变化得有多大。", "primary_collocate": null, "pronunciation": "fú dù", "ipa": "fu˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "今年的房价变化幅度很大。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气温下降的幅度不小。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的价格上涨幅度不大。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩提高了，进步幅度很明显。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷的幅度很大。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资增加的幅度只有一点点。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水每天上升的幅度很小。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次变化的幅度比我想的大。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他体重减少的幅度很大。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁票价调整的幅度不大。", "target_word": "幅度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大幅度", "label": "复合"}, {"form": "小幅度", "label": "复合"}], "register": "书面", "sense_fingerprint": "东西变化得有多大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幅度", "is_correct": true, "explanation": "正确。“幅度”指变化的大小，与“房价变化……很大”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“变化”的大小不说“颜色很大”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：这里说的是变化的程度，“价格”只是数额，与“房价变化”不相配，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是变化的对象，“作业变化”不成立。"}], "explanations": {"幅度": "正确。“幅度”指变化的大小，与“房价变化……很大”相符。", "颜色": "搭配：“变化”的大小不说“颜色很大”。", "价格": "语义：这里说的是变化的程度，“价格”只是数额，与“房价变化”不相配，句子不通。", "作业": "语义：“作业”不是变化的对象，“作业变化”不成立。"}, "sentence_index": 0, "correct_answer": "幅度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑步的幅度很快。", "explanation": "这里应该用〈速度〉。“幅度”指变化的大小，说跑得快慢要用“速度”。"}, {"text": "这条路的幅度有五米。", "explanation": "这里应该用〈宽度〉。“幅度”不指物体的宽窄，说宽窄要用“宽度”。"}, {"text": "这座山的幅度很高。", "explanation": "这里应该用〈高度〉。“幅度”不说高矮，说山高要用“高度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幅度", "is_correct": true, "explanation": "正确。“幅度”指变化的大小，与“湖水每天上升的……很小”相符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：说水位的变化，不说“味道”的大小。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有大小变化，“上升的名字”句子不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是水位变化的对象，句子不通。"}], "explanations": {"幅度": "正确。“幅度”指变化的大小，与“湖水每天上升的……很小”相符。", "味道": "搭配：说水位的变化，不说“味道”的大小。", "名字": "语义：名字没有大小变化，“上升的名字”句子不通。", "脚步": "语义：脚步不是水位变化的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "幅度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屏幕的幅度调到中间。", "explanation": "这里应该用〈亮度〉。“幅度”指变化的范围，说屏幕明暗要用“亮度”。"}, {"text": "今天的幅度很高。", "explanation": "这里应该用〈温度〉。“幅度”不指冷热，说天气冷热要用“温度”。"}, {"text": "这根绳子的幅度是两米。", "explanation": "这里应该用〈长度〉。“幅度”不指长短，说绳子有多长要用“长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的气温变化很幅度不小。", "corrected_sentence": "这个月的气温变化幅度不小。", "error_description": "副词位置错误：副词“很”不能放在名词“幅度”前面修饰它。应说“变化幅度不小”或“变化幅度很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调价地幅度很大。", "corrected_sentence": "这次调价的幅度很大。", "error_description": "结构助词误用：修饰名词“幅度”应用“的”，写成“地”不对。“地”用在动词、形容词前面作状语，“调价的幅度”里“调价”修饰名词，要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
