INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "处理能力是把事情或东西弄好的本事。", "primary_collocate": null, "pronunciation": "chǔ lǐ néng lì", "ipa": "tʂʰu˨˩ li˨˩ nɤŋ˧˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "他的处理能力强，什么麻烦事都能弄好。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王刚来公司，处理能力还不太够。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的处理能力很强，家里的事都安排得好好的。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要慢慢学习，提高自己的处理能力。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到大事，他的处理能力让我很佩服。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我的处理能力比去年好多了。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想当班长，要有一定的处理能力。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的处理能力这么强，这件事就交给你吧。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处理能力不错，一个人就把活儿做完了。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的处理能力很好，客人的问题马上就解决了。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把事情或东西弄好的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处理能力", "is_correct": true, "explanation": "正确：处理能力是把事情弄好的本事，与“什么麻烦事都能弄好”相符。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：“嗓门”说“大”，不说“强”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能用“强”形容。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：脸色与“把麻烦事弄好”无关，句子说的是办事的本事。"}], "explanations": {"处理能力": "正确：处理能力是把事情弄好的本事，与“什么麻烦事都能弄好”相符。", "嗓门": "搭配：“嗓门”说“大”，不说“强”。", "身高": "搭配：“身高”不能用“强”形容。", "脸色": "语义：脸色与“把麻烦事弄好”无关，句子说的是办事的本事。"}, "sentence_index": 0, "correct_answer": "处理能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位同学的处理能力很强，听讲一下子就明白了。", "explanation": "这里应该用〈理解能力〉。听讲明白要用“理解能力”，“处理能力”指把事情弄好的本事。"}, {"text": "她的处理能力很好，背课文很快。", "explanation": "这里应该用〈记忆力〉。背课文靠“记忆力”，“处理能力”指把事情弄好的本事。"}, {"text": "他的处理能力很强，文章写得很好。", "explanation": "这里应该用〈写作能力〉。写文章要用“写作能力”，“处理能力”指把事情弄好的本事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处理能力", "is_correct": true, "explanation": "正确：想当班长，要有一定的处理能力，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与当班长的条件无关。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠与当班长的条件无关。"}, {"text": "容貌", "is_correct": false, "explanation": "语义：容貌与当班长需要的能力无关。"}], "explanations": {"处理能力": "正确：想当班长，要有一定的处理能力，与句意相符。", "体重": "语义：体重与当班长的条件无关。", "睡眠": "语义：睡眠与当班长的条件无关。", "容貌": "语义：容貌与当班长需要的能力无关。"}, "sentence_index": 6, "correct_answer": "处理能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的处理能力很强，房间里很亮。", "explanation": "这里应该用〈亮度〉。灯的明亮程度要说“亮度”，“处理能力”指把事情弄好的本事，不能用于灯。"}, {"text": "这件衣服的处理能力很好，穿着很暖和。", "explanation": "这里应该用〈保暖性〉。衣服暖和要说“保暖性”，“处理能力”指把事情弄好的本事，衣服没有这种本事。"}, {"text": "这张桌子的处理能力很高，放东西很稳。", "explanation": "这里应该用〈承重能力〉。桌子能承受多少重量要说“承重能力”，“处理能力”指把事情弄好的本事，桌子没有这种本事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很强的处理能力。", "corrected_sentence": "他有一种很强的处理能力。", "error_description": "量词错误：“只”用于动物等，能力类名词应当用“种”，正确说法是“一种很强的处理能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地处理能力很强，什么活儿都能干。", "corrected_sentence": "他的处理能力很强，什么活儿都能干。", "error_description": "结构助词错误：修饰名词“处理能力”应用“的”，不用“地”；“地”用于修饰动词，正确说法是“他的处理能力很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
