INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对事务、问题或数据进行处理的能力。", "primary_collocate": null, "pronunciation": "chǔ lǐ néng lì", "ipa": "tʂʰu˨˩ li˨˩ nɤŋ˧˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "这位经理的处理能力很强，问题很快就解决了。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要提高员工的处理能力。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电脑的处理能力比旧电脑强很多。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到突然的事，她的处理能力让大家放心。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做客服工作，需要很好的处理能力。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚工作，处理能力还不够，常常请老师帮忙。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的处理能力太低，打不开大文件。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，老板想看看你的处理能力。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故让大家看到了他的处理能力。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器的处理能力不够，网站一下子就卡住了。", "target_word": "处理能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "处理事务、问题或数据的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处理能力", "is_correct": true, "explanation": "正确：处理能力指处理事务、问题的能力，与“问题很快就解决了”相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很强”形容能力，不能形容体重。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很强”形容能力，不能形容身高。"}, {"text": "酒量", "is_correct": false, "explanation": "语义：酒量与“问题很快就解决了”无关，句子说的是处理事务的能力。"}], "explanations": {"处理能力": "正确：处理能力指处理事务、问题的能力，与“问题很快就解决了”相符。", "体重": "搭配：“很强”形容能力，不能形容体重。", "身高": "搭配：“很强”形容能力，不能形容身高。", "酒量": "语义：酒量与“问题很快就解决了”无关，句子说的是处理事务的能力。"}, "sentence_index": 0, "correct_answer": "处理能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学生的处理能力很强，一讲就懂。", "explanation": "这里应该用〈理解能力〉。听了讲解就懂，要用“理解能力”，“处理能力”指处理事务、问题的能力。"}, {"text": "她的处理能力很好，讲话很清楚，大家都爱听。", "explanation": "这里应该用〈表达能力〉。讲话清楚要用“表达能力”，“处理能力”不用于说话。"}, {"text": "这个孩子的处理能力很强，三年级就读完了很多书。", "explanation": "这里应该用〈阅读能力〉。读书要用“阅读能力”，“处理能力”不用于读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处理能力", "is_correct": true, "explanation": "正确：处理能力太低，机器就打不开大文件，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不说“低”，“太低”不能用来形容颜色。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与机器能否打开大文件无关，句子说的是机器的处理能力。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音太低与“打不开大文件”无关，句子说的是机器的能力。"}], "explanations": {"处理能力": "正确：处理能力太低，机器就打不开大文件，与句意相符。", "颜色": "搭配：颜色不说“低”，“太低”不能用来形容颜色。", "年龄": "语义：年龄与机器能否打开大文件无关，句子说的是机器的处理能力。", "声音": "语义：声音太低与“打不开大文件”无关，句子说的是机器的能力。"}, "sentence_index": 6, "correct_answer": "处理能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的处理能力很强，坐上去很舒服。", "explanation": "这里应该用〈承重能力〉。椅子能承受多少重量要说“承重能力”，“处理能力”指对事务、数据进行处理的能力，椅子没有这种能力。"}, {"text": "这首歌的处理能力很好，大家都爱听。", "explanation": "这里应该用〈感染力〉。歌曲打动人要说“感染力”，“处理能力”指对事务、数据进行处理的能力，不能用于歌。"}, {"text": "这片草地的处理能力很高，夏天很凉快。", "explanation": "这里应该用〈降温能力〉。草地让夏天凉快要说“降温能力”，“处理能力”指对事务、数据进行处理的能力，草地不具备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台服务器有一条很强的处理能力。", "corrected_sentence": "这台服务器有一种很强的处理能力。", "error_description": "量词错误：能力类名词应用“种”，不用“条”，正确说法是“一种很强的处理能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的处理能力提高地很快。", "corrected_sentence": "他的处理能力提高得很快。", "error_description": "补语错误：动词“提高”后的程度补语要用“得”连接，应说“提高得很快”，不能用“地”说“提高地很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
