INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们算了清桌子的数量。", "corrected_sentence": "我们算清了桌子的数量。", "error_description": "结果补语“清”位置错误：应说“算清”，“了”要放在“清”后，不说“算了清”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adb0bbfe-38d6-494b-aa72-a06b51652833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
