INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大只", "is_correct": true, "explanation": "大只（dà zhī，第四声＋第一声）是正确答案，方言中指人或动物身材高大壮实。"}, {"text": "大志", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是远大的志向。"}, {"text": "大指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大拇指。"}, {"text": "大致", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是大体、大概。"}], "explanations": {"大只": "大只（dà zhī，第四声＋第一声）是正确答案，方言中指人或动物身材高大壮实。", "大志": "zhì（第四声）与 zhī（第一声）声调不同，意思是远大的志向。", "大指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大拇指。", "大致": "zhì（第四声）与 zhī（第一声）声调不同，意思是大体、大概。"}, "sentence_index": null, "correct_answer": "大只"}, "level_3": {"options": [{"text": "大只", "is_correct": true, "explanation": "“大只”指人身材高大壮实，与“村里最……的人”的语境相符。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”多用于刀、剑，不能用来形容一个人。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指能透过光，不能用来形容一个人。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，不能用来形容一个人。"}], "explanations": {"大只": "“大只”指人身材高大壮实，与“村里最……的人”的语境相符。", "锋利": "搭配：“锋利”多用于刀、剑，不能用来形容一个人。", "透明": "语义：“透明”指能透过光，不能用来形容一个人。", "干燥": "语义：“干燥”指缺少水分，不能用来形容一个人。"}, "sentence_index": 0, "correct_answer": "大只"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很大只，能坐三个人。", "explanation": "这里应该用〈宽大〉。大只只说人或动物的身材，不用于形容家具。"}, {"text": "这座楼很大只，有十层。", "explanation": "这里应该用〈高大〉。大只不用于形容建筑。"}, {"text": "他胆子很大只，什么都敢做。", "explanation": "这里应该用〈大〉。大只说身材，不说胆量；胆子大要说“胆子很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87546, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大只", "is_correct": true, "explanation": "大只（dà zhī，第四声＋第一声）是正确答案，方言中指人或动物身材高大壮实。"}, {"text": "大旨", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是主要的意思。"}, {"text": "大字", "is_correct": false, "explanation": "zì（平舌音、第四声）与 zhī（翘舌音、第一声）读音不同，意思是写得很大的字。"}, {"text": "大纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大张的纸。"}], "explanations": {"大只": "大只（dà zhī，第四声＋第一声）是正确答案，方言中指人或动物身材高大壮实。", "大旨": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是主要的意思。", "大字": "zì（平舌音、第四声）与 zhī（翘舌音、第一声）读音不同，意思是写得很大的字。", "大纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大张的纸。"}, "sentence_index": null, "correct_answer": "大只"}, "level_3": {"options": [{"text": "大只", "is_correct": true, "explanation": "“大只”指孩子身材高大、壮实，与“真……，几岁了”的说法相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指含水分多，不能用来形容孩子。"}, {"text": "稀薄", "is_correct": false, "explanation": "搭配：“稀薄”多用于空气、液体，不能用来形容孩子。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”指质地硬，与孩子的形态不符。"}], "explanations": {"大只": "“大只”指孩子身材高大、壮实，与“真……，几岁了”的说法相符。", "潮湿": "语义：“潮湿”指含水分多，不能用来形容孩子。", "稀薄": "搭配：“稀薄”多用于空气、液体，不能用来形容孩子。", "坚硬": "语义：“坚硬”指质地硬，与孩子的形态不符。"}, "sentence_index": 6, "correct_answer": "大只"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河很大只，船都能开过去。", "explanation": "这里应该用〈宽阔〉。大只只用于人或动物的身材，不用来形容河流。"}, {"text": "这个问题很大只，大家都在讨论。", "explanation": "这里应该用〈严重〉。大只不说问题的程度。"}, {"text": "这部电影很大只，很多人都去看。", "explanation": "这里应该用〈精彩〉。大只不用于形容电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没大只，但很有力气。", "corrected_sentence": "他不大只，但很有力气。", "error_description": "否定副词错用：形容词前应用“不”，“没”用于动词或“没有”，应说“他不大只”，不能说“他没大只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长很大只，像个运动员。", "corrected_sentence": "他长得很大只，像个运动员。", "error_description": "补语错误：应改为“长得很大只”。动词“长”后接描述程度的补语要用“得”连接，不能说“长很大只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
