INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87547, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年代学是研究过去的事情发生在哪一年的学问。", "primary_collocate": null, "pronunciation": "nián dài xué", "ipa": "njɛn˧˥ taɪ˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "年代学能告诉我们事情发生在哪一年。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对年代学很感兴趣。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大学里教年代学。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年代学是研究年份的学问。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很懂年代学。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学年代学要记很多年份。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年代学研究古代事件的年份，你知道吗？", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年代学帮我们弄清历史故事发生的年份。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本关于年代学的书。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的历史课也会讲一点年代学。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年代学家", "label": "复合"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "年代学：研究过去的事发生在哪一年的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年代学", "is_correct": true, "explanation": "正确：年代学研究过去的事情发生在哪一年，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能告诉人们事情发生在哪一年。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房与历史事件的年份无关，不能说明事情发生的时间。"}, {"text": "闲话", "is_correct": false, "explanation": "语域：“闲话”是口语，指随便说的话，不能作为确定事件年份的依据。"}], "explanations": {"年代学": "正确：年代学研究过去的事情发生在哪一年，与句意相符。", "天气": "语义：天气不能告诉人们事情发生在哪一年。", "厨房": "语义：厨房与历史事件的年份无关，不能说明事情发生的时间。", "闲话": "语域：“闲话”是口语，指随便说的话，不能作为确定事件年份的依据。"}, "sentence_index": 0, "correct_answer": "年代学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年代学通过地层和器物研究古代人类的生活。", "explanation": "这里应该用〈考古学〉。年代学只确定事件发生的年份，不研究古代人类的生活。"}, {"text": "年代学研究资源的分配与市场的运行。", "explanation": "这里应该用〈经济学〉。年代学研究过去的事情发生在哪一年，不研究资源的分配与市场的运行。"}, {"text": "年代学研究人的情绪和思维过程。", "explanation": "这里应该用〈心理学〉。年代学研究过去的事情发生在哪一年，不研究人的情绪和思维。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年代学", "is_correct": true, "explanation": "正确：年代学研究的是事件发生的年份，与“研究古代事件的年份”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不研究古代事件的年份。"}, {"text": "北京", "is_correct": false, "explanation": "语义：北京是城市，不研究古代事件的年份。"}, {"text": "老妈", "is_correct": false, "explanation": "语域与语义：“老妈”是口语称呼，指母亲，不研究古代事件的年份。"}], "explanations": {"年代学": "正确：年代学研究的是事件发生的年份，与“研究古代事件的年份”相符。", "天气": "语义：天气不研究古代事件的年份。", "北京": "语义：北京是城市，不研究古代事件的年份。", "老妈": "语域与语义：“老妈”是口语称呼，指母亲，不研究古代事件的年份。"}, "sentence_index": 6, "correct_answer": "年代学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年代学研究物质的运动和相互作用。", "explanation": "这里应该用〈物理学〉。年代学研究过去的事情发生在哪一年，不研究物质的运动和相互作用。"}, {"text": "年代学研究世界的本质和人生的意义。", "explanation": "这里应该用〈哲学〉。年代学研究过去的事情发生在哪一年，不研究世界的本质和人生的意义。"}, {"text": "年代学研究疾病的预防和治疗。", "explanation": "这里应该用〈医学〉。年代学研究过去的事情发生在哪一年，不研究疾病的预防和治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师把年代学讲很清楚。", "corrected_sentence": "这位老师把年代学讲得很清楚。", "error_description": "错误形式：“讲很清楚”；正确形式：“讲得很清楚”。动词后表示程度的补语要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我过学年代学。", "corrected_sentence": "我学过年代学。", "error_description": "错误形式：“过学年代学”；正确形式：“学过年代学”。表示经历的“过”要紧跟在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
