INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究并确定历史事件发生的时间和先后次序的学科。", "primary_collocate": null, "pronunciation": "nián dài xué", "ipa": "njɛn˧˥ taɪ˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "年代学帮助历史学家确定事件的先后次序。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学里学的是年代学。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年代学研究事件发生的时间。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古队请年代学专家判断这座墓的年份。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说年代学是一门很重要的学科。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有年代学，历史就会乱成一团。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是古代年代学的方法。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年代学要先排出事件的前后顺序。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用年代学的方法研究这段历史。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年代学让我们知道哪件事发生得更早。", "target_word": "年代学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年代学家", "label": "复合"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "年代学：确定历史事件时间和先后次序的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年代学", "is_correct": true, "explanation": "正确：年代学研究历史事件的时间和先后次序，与“确定事件的先后次序”相符。"}, {"text": "地理学", "is_correct": false, "explanation": "语义：地理学研究地表与环境，不能帮助确定事件的先后次序。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法研究词句的组合规则，与历史事件的先后次序无关。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语中的闲话，不是确定历史事件次序的学问。"}], "explanations": {"年代学": "正确：年代学研究历史事件的时间和先后次序，与“确定事件的先后次序”相符。", "地理学": "语义：地理学研究地表与环境，不能帮助确定事件的先后次序。", "语法": "语义：语法研究词句的组合规则，与历史事件的先后次序无关。", "八卦": "语域：“八卦”是口语中的闲话，不是确定历史事件次序的学问。"}, "sentence_index": 0, "correct_answer": "年代学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年代学的任务是发掘和研究古代遗址。", "explanation": "这里应该用〈考古学〉。年代学研究事件发生的时间先后，发掘和研究遗址属于考古学。"}, {"text": "年代学研究山川与气候的分布。", "explanation": "这里应该用〈地理学〉。年代学研究历史事件的时间先后，不研究山川与气候的分布。"}, {"text": "年代学研究人类社会的发展过程。", "explanation": "这里应该用〈历史学〉。年代学只研究事件发生的时间先后，不研究社会发展的全过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年代学", "is_correct": true, "explanation": "正确：年代学是研究古代历史时间次序的学问，“古代年代学的方法”讲得通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：古代没有钢琴，“古代钢琴的方法”与时代矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：古代没有电脑，“古代电脑的方法”与时代矛盾。"}, {"text": "大哥大", "is_correct": false, "explanation": "语域：“大哥大”是口语俗称，指早期的移动电话，既不适合书面语境，也与“古代”相矛盾。"}], "explanations": {"年代学": "正确：年代学是研究古代历史时间次序的学问，“古代年代学的方法”讲得通。", "钢琴": "语义：古代没有钢琴，“古代钢琴的方法”与时代矛盾。", "电脑": "语义：古代没有电脑，“古代电脑的方法”与时代矛盾。", "大哥大": "语域：“大哥大”是口语俗称，指早期的移动电话，既不适合书面语境，也与“古代”相矛盾。"}, "sentence_index": 6, "correct_answer": "年代学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年代学研究星体的运行规律。", "explanation": "这里应该用〈天文学〉。年代学研究历史事件的时间先后，不研究星体的运行。"}, {"text": "年代学研究语言的结构和演变。", "explanation": "这里应该用〈语言学〉。年代学研究时间先后，不研究语言的结构和演变。"}, {"text": "年代学研究植物的光合作用。", "explanation": "这里应该用〈生物学〉。年代学研究历史事件的时间先后，不研究植物的光合作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学里选了一本年代学。", "corrected_sentence": "他大学里选了一门年代学。", "error_description": "错误形式：“一本年代学”；正确形式：“一门年代学”。年代学是学科，学科的量词用“门”，“本”只用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把年代学学很好。", "corrected_sentence": "他把年代学学得很好。", "error_description": "错误形式：“学很好”；正确形式：“学得很好”。动词后表示程度的补语要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
