INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87551, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "总理是一个国家里管很多事的大官。", "primary_collocate": null, "pronunciation": "zǒng lǐ", "ipa": "tsʊŋ˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "总理是这个国家最大的官。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大以后当总理。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理每天要管很多事。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在报纸上看到了总理的照片。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理坐车来到了我们学校。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的总理很忙。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都很喜欢这位总理。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理对大家说，欢迎你们来。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了那位总理的故事。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理明天要和农民见面。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "副总理", "label": "复合"}, {"form": "總理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个国家里管很多事的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老百姓", "is_correct": false, "explanation": "语义：“老百姓”不是官，与“最大的官”矛盾。"}, {"text": "总理", "is_correct": true, "explanation": "“总理”是国家里管很多事的大官，符合“这个国家最大的官”。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：“小学生”不是官，无法成为“最大的官”。"}, {"text": "市长", "is_correct": false, "explanation": "搭配：“这个国家”与“市长”不搭配，市长管理的是城市。"}], "explanations": {"老百姓": "语义：“老百姓”不是官，与“最大的官”矛盾。", "总理": "“总理”是国家里管很多事的大官，符合“这个国家最大的官”。", "小学生": "语义：“小学生”不是官，无法成为“最大的官”。", "市长": "搭配：“这个国家”与“市长”不搭配，市长管理的是城市。"}, "sentence_index": 0, "correct_answer": "总理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的总理很严格，大家都怕他。", "explanation": "这里应该用〈校长〉。总理指国家政府的首脑，学校的负责人要说“校长”。"}, {"text": "这个村子的总理很热情，常帮助大家。", "explanation": "这里应该用〈村长〉。总理是国家级的大官，村里的负责人要说“村长”。"}, {"text": "他是教育部的总理，负责管理学校的工作。", "explanation": "这里应该用〈部长〉。总理不是某个部门的负责人，教育部的负责人要说“部长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "搭配：“这位”只用于指人，不能指老虎。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物，不能像人那样被喜欢作为“这位”。"}, {"text": "总理", "is_correct": true, "explanation": "“总理”是人，可以用“这位”指称，符合句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不是人，句中的“这位”无法指它。"}], "explanations": {"老虎": "搭配：“这位”只用于指人，不能指老虎。", "窗户": "语义：“窗户”是物，不能像人那样被喜欢作为“这位”。", "总理": "“总理”是人，可以用“这位”指称，符合句意。", "电脑": "语义：“电脑”不是人，句中的“这位”无法指它。"}, "sentence_index": 6, "correct_answer": "总理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的总理是小明，他每天帮老师收作业。", "explanation": "这里应该用〈班长〉。总理是国家政府的首脑，班里的负责人要说“班长”。"}, {"text": "这家医院的总理是一位老医生。", "explanation": "这里应该用〈院长〉。总理是国家级的大官，医院的负责人要说“院长”。"}, {"text": "公司的总理每天开车上班。", "explanation": "这里应该用〈总经理〉。总理指国家政府的首脑，公司的负责人要说“总经理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视上，一只总理正在讲话。", "corrected_sentence": "电视上，一位总理正在讲话。", "error_description": "量词错误：“总理”指人，应用“位”，不能用“只”（“只”多用于动物）。正确是“一位总理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天在街上见到了一只总理。", "corrected_sentence": "我们昨天在街上见到了一位总理。", "error_description": "量词错误：“总理”指人，应用“位”，不能用“只”。正确是“一位总理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
