INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家政府的首脑；某些国家内阁的最高领导人。", "primary_collocate": null, "pronunciation": "zǒng lǐ", "ipa": "tsʊŋ˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "总理今天上午会见了外国客人。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的总理每天都要开会。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理在电视里说了很多话。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总理明天要去北京访问。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问总理一个关于经济的问题。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理和大家一起看了这场比赛。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位总理在任五年，做了不少好事。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理说，今年要多建学校。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理的办公室在市中心的大楼里。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他当国家的总理。", "target_word": "总理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "副总理", "label": "复合"}, {"form": "總理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家政府的首脑，内阁最高领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物体，不能会见外国客人。"}, {"text": "总理", "is_correct": true, "explanation": "“总理”是政府首脑，符合“会见外国客人”的身份。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“会见”多用于政府或外交人员之间，“厨师”不搭配这种会面。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不是人，无法会见客人。"}], "explanations": {"窗户": "语义：“窗户”是物体，不能会见外国客人。", "总理": "“总理”是政府首脑，符合“会见外国客人”的身份。", "厨师": "搭配：“会见”多用于政府或外交人员之间，“厨师”不搭配这种会面。", "书": "语义：“书”不是人，无法会见客人。"}, "sentence_index": 0, "correct_answer": "总理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是教育部的总理。", "explanation": "这里应该用〈部长〉。总理是国家政府的首脑，不负责某个部门；部门负责人要说“部长”。"}, {"text": "这个城市的总理很年轻，大家都很喜欢他。", "explanation": "这里应该用〈市长〉。总理指全国政府的首脑，城市的行政长官要说“市长”。"}, {"text": "这家工厂的总理每天都很忙。", "explanation": "这里应该用〈厂长〉。总理不是工厂的负责人，工厂的负责人要说“厂长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是物，不能在任，也不能做好事。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不能在任，也不能做好事。"}, {"text": "总理", "is_correct": true, "explanation": "“总理”是政府首脑，可以在任五年，符合句意。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“在任”用于官员职务，“司机”不搭配。"}], "explanations": {"椅子": "语义：“椅子”是物，不能在任，也不能做好事。", "电脑": "语义：“电脑”不能在任，也不能做好事。", "总理": "“总理”是政府首脑，可以在任五年，符合句意。", "司机": "搭配：“在任”用于官员职务，“司机”不搭配。"}, "sentence_index": 6, "correct_answer": "总理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的总理每天早上在门口欢迎学生。", "explanation": "这里应该用〈校长〉。总理是国家政府的首脑，学校的负责人要说“校长”。"}, {"text": "这家医院的总理是一位老医生。", "explanation": "这里应该用〈院长〉。总理不是医院的负责人，医院的负责人要说“院长”。"}, {"text": "我们村的总理带大家修了一条路。", "explanation": "这里应该用〈村长〉。总理是全国政府的首脑，村里的负责人要说“村长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天来了三只总理，他们一起讨论了经济问题。", "corrected_sentence": "昨天来了三位总理，他们一起讨论了经济问题。", "error_description": "量词错误：“总理”指人，应用“位”，不能用“只”（“只”多用于动物等）。正确是“三位总理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会上有一只总理先发了言。", "corrected_sentence": "会上有一位总理先发了言。", "error_description": "量词错误：“总理”指人，应用“位”，不能用“只”（“只”多用于动物）。正确是“一位总理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
