INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对号是写在纸上的一个小勾，表示答对了。", "primary_collocate": null, "pronunciation": "duì hào", "ipa": "tuei˥˩ xau˥˩", "syllable_count": 2, "sentences": [{"text": "老师在我的作业上画了一个对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题答对了，所以老师给我打了对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试卷上有很多对号，我很高兴。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "答对的题后面都有一个红色的对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在每个正确的答案旁边画对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见作业本上有一个对号，就笑了。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“做对了就画对号，做错了就画叉。”", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上的对号是用红笔画的。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明数了数，一共有八个对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业本上没有对号，我只好重做一遍。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "對號", "label": "繁体"}], "register": "通用", "sense_fingerprint": "对号|纸上的小勾|表示答对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对号", "is_correct": true, "explanation": "正确答案。对号 duì hào，指纸上表示答对的小勾。"}, {"text": "退号", "is_correct": false, "explanation": "tuì（第四声）与 duì 声母不同（t 与 d），意思是退掉挂号，与“对号”不同。"}, {"text": "对话", "is_correct": false, "explanation": "huà 与 hào 韵母不同（ua 与 ao），意思是两人之间的谈话，与“对号”不同。"}, {"text": "对好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是对得正确、搭配得当，不是指小勾。"}], "explanations": {"对号": "正确答案。对号 duì hào，指纸上表示答对的小勾。", "退号": "tuì（第四声）与 duì 声母不同（t 与 d），意思是退掉挂号，与“对号”不同。", "对话": "huà 与 hào 韵母不同（ua 与 ao），意思是两人之间的谈话，与“对号”不同。", "对好": "hǎo（第三声）与 hào（第四声）声调不同，意思是对得正确、搭配得当，不是指小勾。"}, "sentence_index": null, "correct_answer": "对号"}, "level_3": {"options": [{"text": "对号", "is_correct": true, "explanation": "正确：“对号”是老师画在作业上表示答对的小勾，符合句意。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“画”用于画图形或符号，答案要写，不能画。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“画”用于图形，名字要写，不能画在作业上当标记。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是要写的文章，不是可以画在作业上的标记，“画作文”不成立。"}], "explanations": {"对号": "正确：“对号”是老师画在作业上表示答对的小勾，符合句意。", "答案": "搭配：“画”用于画图形或符号，答案要写，不能画。", "名字": "搭配：“画”用于图形，名字要写，不能画在作业上当标记。", "作文": "语义：作文是要写的文章，不是可以画在作业上的标记，“画作文”不成立。"}, "sentence_index": 0, "correct_answer": "对号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "答对的题后面都有一只红色的对号。", "explanation": "这里应该用〈个〉。对号是纸上的符号，量词用“个”；“只”用于动物等，不能修饰对号。"}, {"text": "答错的题后面都有一个红色的对号。", "explanation": "这里应该用〈叉〉。对号表示答对，表示答错要用叉。"}, {"text": "老师在我做错的题上画了一个对号，说我这题错了。", "explanation": "这里应该用〈叉〉。对号表示答对，表示做错要画叉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对号", "is_correct": true, "explanation": "正确：“做对了就画对号”与后文“画叉”构成对照，只有“对号”符合。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“画”用于画符号，作业是要做的东西，不能画。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“画”不能用于问题；问题要回答或解决。"}, {"text": "结果", "is_correct": false, "explanation": "语义：结果是评定后的情况，不是可以画出来的标记，无法与“画叉”并列。"}], "explanations": {"对号": "正确：“做对了就画对号”与后文“画叉”构成对照，只有“对号”符合。", "作业": "搭配：“画”用于画符号，作业是要做的东西，不能画。", "问题": "搭配：“画”不能用于问题；问题要回答或解决。", "结果": "语义：结果是评定后的情况，不是可以画出来的标记，无法与“画叉”并列。"}, "sentence_index": 6, "correct_answer": "对号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一口气吃掉了三个对号，老师说我很棒。", "explanation": "这里应该用〈饼干〉。对号是纸上的符号，不能吃，应该吃饼干。"}, {"text": "我已经把这道题的对号判断好了。", "explanation": "这里应该用〈对错〉。对号是打在答案旁边的符号，指判断的结果；判断的对象是对错，不能说判断对号。"}, {"text": "请把车票和座位对号，别坐错了。", "explanation": "这里“对号”是动词，表示核对号码（如“对号入座”），与本词指小勾的名词义不同，应改用〈核对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
