INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "表示正确的符号\"√\"。", "primary_collocate": null, "pronunciation": "duì hào", "ipa": "tuei˥˩ xau˥˩", "syllable_count": 2, "sentences": [{"text": "请在你选的答案前面打对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同意的话，就在表格的方框里打对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个符号“√”就是对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上出现了一个绿色的对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选好以后，方框里会出现对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对号表示正确，叉表示错误。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在清单上的每一项后面都打了对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完的事情，我就在后面画一个对号。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这里的对号是什么意思？", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表上，没有对号的就是还没完成的。", "target_word": "对号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "對號", "label": "繁体"}], "register": "通用", "sense_fingerprint": "对号|符号√|表示正确或完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对号", "is_correct": true, "explanation": "正确答案。对号 duì hào，指表示正确的符号“√”。"}, {"text": "退号", "is_correct": false, "explanation": "tuì（第四声）与 duì 声母不同（t 与 d），意思是退掉挂号，与“对号”不同。"}, {"text": "对话", "is_correct": false, "explanation": "huà 与 hào 韵母不同（ua 与 ao），意思是两人之间的谈话，与“对号”不同。"}, {"text": "对好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是对得正确、搭配得当，不是指符号。"}], "explanations": {"对号": "正确答案。对号 duì hào，指表示正确的符号“√”。", "退号": "tuì（第四声）与 duì 声母不同（t 与 d），意思是退掉挂号，与“对号”不同。", "对话": "huà 与 hào 韵母不同（ua 与 ao），意思是两人之间的谈话，与“对号”不同。", "对好": "hǎo（第三声）与 hào（第四声）声调不同，意思是对得正确、搭配得当，不是指符号。"}, "sentence_index": null, "correct_answer": "对号"}, "level_3": {"options": [{"text": "对号", "is_correct": true, "explanation": "正确：“打对号”是在选中的答案前做正确标记，符合句意。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“打”用于标记符号，答案本身不能被“打”去标记。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“打”用于标记符号，名字不能用来标记答案前面。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是要写的文章，不是可以打在答案前面的标记，“打作文”不成立。"}], "explanations": {"对号": "正确：“打对号”是在选中的答案前做正确标记，符合句意。", "答案": "搭配：“打”用于标记符号，答案本身不能被“打”去标记。", "名字": "搭配：“打”用于标记符号，名字不能用来标记答案前面。", "作文": "语义：作文是要写的文章，不是可以打在答案前面的标记，“打作文”不成立。"}, "sentence_index": 0, "correct_answer": "对号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手机屏幕上出现了一只绿色的对号。", "explanation": "这里应该用〈个〉。“只”用于动物等，对号这类符号要用“个”。"}, {"text": "手机屏幕上出现了一把绿色的对号。", "explanation": "这里应该用〈个〉。“把”用于有柄或可握的东西，不能用于对号这种符号。"}, {"text": "手机屏幕上出现了一条绿色的对号。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，对号这种符号要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对号", "is_correct": true, "explanation": "正确：“打了对号”表示在每一项后面做了正确标记，符合句意。"}, {"text": "错误", "is_correct": false, "explanation": "搭配：“打”用于标记符号，错误是要改正的东西，不能被“打”。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“打”不能用于问题；问题要回答或解决。"}, {"text": "结果", "is_correct": false, "explanation": "语义：结果是评定后的情况，不是可以打出来的标记。"}], "explanations": {"对号": "正确：“打了对号”表示在每一项后面做了正确标记，符合句意。", "错误": "搭配：“打”用于标记符号，错误是要改正的东西，不能被“打”。", "问题": "搭配：“打”不能用于问题；问题要回答或解决。", "结果": "语义：结果是评定后的情况，不是可以打出来的标记。"}, "sentence_index": 6, "correct_answer": "对号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张表上，有对号的就是还没完成的。", "explanation": "这里应该用〈叉〉。对号表示已经完成，表示没完成要用叉。"}, {"text": "请在你选的答案前面吃对号。", "explanation": "这里应该用〈打〉。对号是名词，不能用“吃”，应说“打对号”。"}, {"text": "这张表上每个人都读了一个对号。", "explanation": "这里应该用〈名字〉。对号是符号，不能“读”，应读每个人的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
