INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "建制是一个团体里有多少人、怎样分工的规定。", "primary_collocate": null, "pronunciation": "jiàn zhì", "ipa": "tɕjɛn˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的建制很清楚，每个部门有几个人都写好了。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的建制规定了每个班有几位老师。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的建制不大，只有五个人。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要改变建制，先要决定每个人做什么。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照建制，我们部门需要两个会计。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的建制里没有这个工作，所以不能招人。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建制把一个大部门分成了三个小组。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十分熟悉公司的建制，清楚各部门的职责。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建制过于复杂，员工不清楚应当向谁请示。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团队的建制简单，一个人做好几件事。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "团体里人数与分工的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制（jiànzhì）指团体里人数与分工的规定，是本词。"}, {"text": "剪纸", "is_correct": false, "explanation": "剪纸（jiǎnzhǐ）与建制（jiànzhì）两个音节声调都不同，意思是剪纸艺术。"}, {"text": "监制", "is_correct": false, "explanation": "监（jiān，第一声）与建（jiàn，第四声）声调不同，意思是监督制作。"}, {"text": "现制", "is_correct": false, "explanation": "现（xiàn）与建（jiàn）声母不同，意思是现场制作。"}], "explanations": {"建制": "建制（jiànzhì）指团体里人数与分工的规定，是本词。", "剪纸": "剪纸（jiǎnzhǐ）与建制（jiànzhì）两个音节声调都不同，意思是剪纸艺术。", "监制": "监（jiān，第一声）与建（jiàn，第四声）声调不同，意思是监督制作。", "现制": "现（xiàn）与建（jiàn）声母不同，意思是现场制作。"}, "sentence_index": null, "correct_answer": "建制"}, "level_3": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制指团体里人数与分工的规定，与“每个部门有几个人都写好了”相符。"}, {"text": "业务", "is_correct": false, "explanation": "语义：业务指工作内容，不规定每个部门有几个人，与后半句矛盾。"}, {"text": "利润", "is_correct": false, "explanation": "语义：利润是财务数字，不规定部门人数，与后半句不合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“公司的天气”不成立，天气不属于公司的组织规定。"}], "explanations": {"建制": "建制指团体里人数与分工的规定，与“每个部门有几个人都写好了”相符。", "业务": "语义：业务指工作内容，不规定每个部门有几个人，与后半句矛盾。", "利润": "语义：利润是财务数字，不规定部门人数，与后半句不合。", "天气": "搭配：“公司的天气”不成立，天气不属于公司的组织规定。"}, "sentence_index": 0, "correct_answer": "建制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的建制是学生不能带手机。", "explanation": "这里应该用〈规定〉。建制指团体里人数与分工的规定，不指学生的行为规则。"}, {"text": "这次会议的建制很紧，只安排了两个小时。", "explanation": "这里应该用〈日程〉。建制指团体里人数与分工的规定，会议的时间安排要说日程。"}, {"text": "公司的考勤建制很严格。", "explanation": "这里应该用〈制度〉。建制指人数与分工的规定，考勤规则不属于建制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87555, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制（jiànzhì）指团体里人数与分工的规定，是本词。"}, {"text": "建址", "is_correct": false, "explanation": "址（zhǐ，第三声）与制（zhì，第四声）声调不同，意思是建筑物的地址。"}, {"text": "舰只", "is_correct": false, "explanation": "只（zhī，第一声）与制（zhì，第四声）声调不同，意思是舰船。"}, {"text": "间质", "is_correct": false, "explanation": "间（jiān，第一声）与建（jiàn，第四声）声调不同，意思是细胞之间的物质，属于较少用的术语。"}], "explanations": {"建制": "建制（jiànzhì）指团体里人数与分工的规定，是本词。", "建址": "址（zhǐ，第三声）与制（zhì，第四声）声调不同，意思是建筑物的地址。", "舰只": "只（zhī，第一声）与制（zhì，第四声）声调不同，意思是舰船。", "间质": "间（jiān，第一声）与建（jiàn，第四声）声调不同，意思是细胞之间的物质，属于较少用的术语。"}, "sentence_index": null, "correct_answer": "建制"}, "level_3": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制指团体里人数与分工的规定，“新建制把大部门分成小组”相符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能作分组的主语，与“把……分成三个小组”的动作搭配不成立。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不能被分成部门，与“分成三个小组”矛盾。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是组织，不能把大部门分成小组，与后半句矛盾。"}], "explanations": {"建制": "建制指团体里人数与分工的规定，“新建制把大部门分成小组”相符。", "工资": "搭配：“工资”不能作分组的主语，与“把……分成三个小组”的动作搭配不成立。", "水果": "语义：水果不能被分成部门，与“分成三个小组”矛盾。", "饮料": "语义：饮料不是组织，不能把大部门分成小组，与后半句矛盾。"}, "sentence_index": 6, "correct_answer": "建制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的建制很高，员工都很努力。", "explanation": "这里应该用〈效率〉。建制指团体里人数与分工的规定，不能用来形容工作的快慢或高低。"}, {"text": "这个项目的建制太高，需要再找几家公司投资。", "explanation": "这里应该用〈预算〉。建制指人数与分工的规定，不指经费数额，经费要说预算。"}, {"text": "这家医院的建制很周到，大家都很满意。", "explanation": "这里应该用〈服务〉。建制指人数与分工的规定，医院对病人的照顾要说服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version 