INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87557, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家为管理地方事务而划分的区域或设立的机构，如省、市、县。", "primary_collocate": null, "pronunciation": "xíng zhèng dān wèi", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tan˥ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "省、市、县都是我国的行政单位。", "target_word": "行政单位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县是比市小一级的行政单位。", "target_word": "行政单位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个行政单位负责管理本地的学校和医院。", "target_word": "行政单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京是一个直辖市，也是一级行政单位。", "target_word": "行政单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家乡是一个很小的行政单位。", "target_word": "行政单位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家把这个地区分成了三个行政单位。", "target_word": "行政单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡和镇是最基层的行政单位。", "target_word": "行政单位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的行政单位成立后，要选出负责人。", "target_word": "行政单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县是全省面积最大的行政单位。", "target_word": "行政单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上用不同的线表示不同级别的行政单位。", "target_word": "行政单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "基层行政单位", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家划分的区域或设立的机构，如省、市、县", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物", "is_correct": false, "explanation": "语义：省、市、县是行政区划，不是动物。"}, {"text": "行政单位", "is_correct": true, "explanation": "正确：「行政单位」指国家划分的区域或机构，与“省、市、县”的类别相符。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语色彩重，与书面的行政说明不协调。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是行政区划，与“省、市、县”的类别不符。"}], "explanations": {"动物": "语义：省、市、县是行政区划，不是动物。", "行政单位": "正确：「行政单位」指国家划分的区域或机构，与“省、市、县”的类别相符。", "玩意儿": "语域：“玩意儿”口语色彩重，与书面的行政说明不协调。", "颜色": "语义：颜色不是行政区划，与“省、市、县”的类别不符。"}, "sentence_index": 0, "correct_answer": "行政单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的叔叔是一名行政单位，在市政府工作。", "explanation": "这里应该用〈公务员〉。行政单位指机构或区域，不指人；说人要用“公务员”。"}, {"text": "这台行政单位很大。", "explanation": "这里应该用〈个〉。“台”多用于机器，行政单位要用通用量词“个”。"}, {"text": "一米是长度的行政单位。", "explanation": "这里应该用〈计量单位〉。这里的“单位”指长度的标准；行政单位指国家划分的管理区域或机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：乡和镇是行政区划，天气不是地方的行政类别。"}, {"text": "行政单位", "is_correct": true, "explanation": "正确：「行政单位」指最基层的行政区划或机构，与“乡和镇”相符。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，与书面的行政说明不协调。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是行政区划，与“乡和镇”的类别不符。"}], "explanations": {"天气": "语义：乡和镇是行政区划，天气不是地方的行政类别。", "行政单位": "正确：「行政单位」指最基层的行政区划或机构，与“乡和镇”相符。", "家伙": "语域：“家伙”是口语，与书面的行政说明不协调。", "水果": "语义：水果不是行政区划，与“乡和镇”的类别不符。"}, "sentence_index": 6, "correct_answer": "行政单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天煮一锅行政单位。", "explanation": "这里应该用〈饭〉。“煮”的对象是食物，行政单位不能煮。"}, {"text": "他喜欢吃行政单位。", "explanation": "这里应该用〈苹果〉。“吃”的对象是食物，行政单位不是可以吃的东西。"}, {"text": "我爸爸每天开行政单位去上班。", "explanation": "这里应该用〈车〉。“开”的对象是车辆，行政单位不能用来驾驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县是国家划分的一条行政单位。", "corrected_sentence": "这个县是国家划分的一个行政单位。", "error_description": "错误形式：“一条行政单位”；正确形式：“一个行政单位”。“条”用于细长的东西，行政单位要用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区有三行政单位。", "corrected_sentence": "这个地区有三个行政单位。", "error_description": "错误形式：“三行政单位”；正确形式：“三个行政单位”。数词后面的名词要加量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
