INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机关、军队等组织的编制和系统。", "primary_collocate": null, "pronunciation": "jiàn zhì", "ipa": "tɕjɛn˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这支部队的建制很完整，有步兵也有炮兵。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争以后，政府取消了这个师的建制。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的建制分成师、团、营和连。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机关的建制有三级，一级管一级。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的部队保持着原来的建制。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打了败仗以后，这个连的建制乱了。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府的建制里有十几个局。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家改革了机关的建制，减少了很多部门。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照建制，这个营应该有五百人，现在只有两百人。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队建制要先分清上下级。", "target_word": "建制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "机关军队的编制与系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87558, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制（jiànzhì）指机关、军队等组织的编制和系统，是本词。"}, {"text": "剪纸", "is_correct": false, "explanation": "剪纸（jiǎnzhǐ）与建制（jiànzhì）两个音节声调都不同，意思是剪纸艺术。"}, {"text": "监制", "is_correct": false, "explanation": "监（jiān，第一声）与建（jiàn，第四声）声调不同，意思是监督制作。"}, {"text": "现制", "is_correct": false, "explanation": "现（xiàn）与建（jiàn）声母不同，意思是现场制作。"}], "explanations": {"建制": "建制（jiànzhì）指机关、军队等组织的编制和系统，是本词。", "剪纸": "剪纸（jiǎnzhǐ）与建制（jiànzhì）两个音节声调都不同，意思是剪纸艺术。", "监制": "监（jiān，第一声）与建（jiàn，第四声）声调不同，意思是监督制作。", "现制": "现（xiàn）与建（jiàn）声母不同，意思是现场制作。"}, "sentence_index": null, "correct_answer": "建制"}, "level_3": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制指军队等组织的编制和系统，与“有步兵也有炮兵”相符。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是饭馆的列表，与“有步兵也有炮兵”的部队不相关。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的方法，不能用来形容部队。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“部队的天气”不成立，天气不属于部队的编制。"}], "explanations": {"建制": "建制指军队等组织的编制和系统，与“有步兵也有炮兵”相符。", "菜单": "语义：菜单是饭馆的列表，与“有步兵也有炮兵”的部队不相关。", "食谱": "语义：食谱是做菜的方法，不能用来形容部队。", "天气": "搭配：“部队的天气”不成立，天气不属于部队的编制。"}, "sentence_index": 0, "correct_answer": "建制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支部队的建制是六一一。", "explanation": "这里应该用〈番号〉。建制指编制和系统，部队的编号要说番号。"}, {"text": "部队每天五点起床，建制很严。", "explanation": "这里应该用〈作息〉。建制指编制和系统，不指一天的起居安排。"}, {"text": "这支部队每天早上进行建制。", "explanation": "这里应该用〈训练〉。建制是名词，指编制和系统，不能表示“进行”的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87558, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制（jiànzhì）指机关、军队等组织的编制和系统，是本词。"}, {"text": "建址", "is_correct": false, "explanation": "址（zhǐ，第三声）与制（zhì，第四声）声调不同，意思是建筑物的地址。"}, {"text": "舰只", "is_correct": false, "explanation": "只（zhī，第一声）与制（zhì，第四声）声调不同，意思是舰船。"}, {"text": "间质", "is_correct": false, "explanation": "间（jiān，第一声）与建（jiàn，第四声）声调不同，意思是细胞之间的物质，属于较少用的术语。"}], "explanations": {"建制": "建制（jiànzhì）指机关、军队等组织的编制和系统，是本词。", "建址": "址（zhǐ，第三声）与制（zhì，第四声）声调不同，意思是建筑物的地址。", "舰只": "只（zhī，第一声）与制（zhì，第四声）声调不同，意思是舰船。", "间质": "间（jiān，第一声）与建（jiàn，第四声）声调不同，意思是细胞之间的物质，属于较少用的术语。"}, "sentence_index": null, "correct_answer": "建制"}, "level_3": {"options": [{"text": "建制", "is_correct": true, "explanation": "建制指机关的编制和系统，与“市政府的建制里有十几个局”相符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱里列的是菜，不会列出十几个局。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历记录病人的情况，与“十几个局”的机关无关。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“市政府的歌词”不成立，歌词不属于机关。"}], "explanations": {"建制": "建制指机关的编制和系统，与“市政府的建制里有十几个局”相符。", "菜谱": "语义：菜谱里列的是菜，不会列出十几个局。", "病历": "语义：病历记录病人的情况，与“十几个局”的机关无关。", "歌词": "搭配：“市政府的歌词”不成立，歌词不属于机关。"}, "sentence_index": 6, "correct_answer": "建制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的建制非常结实，坐上去很舒服。", "explanation": "这里应该用〈做工〉。建制指组织的编制和系统，不指家具的构造；说椅子结实应说做工。"}, {"text": "这座大楼的建制很漂亮，外墙是白色的。", "explanation": "这里应该用〈建筑〉。建制指编制和系统，不指房屋的外形，大楼的外观要说建筑。"}, {"text": "这台机器的建制很先进，效率很高。", "explanation": "这里应该用〈结构〉。建制指机关、军队等组织的编制和系统，不指机器的构造；机器的构造要说结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军队重新编了一张建制，分成三个营。", "corrected_sentence": "军队重新编了一套建制，分成三个营。", "error_description": "“建制”应该用量词“套”（一套建制），不能用“张”，“张”用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个营重新调整了一颗建制。", "corrected_sentence": "这个营重新调整了建制。", "error_description": "“建制”不能用量词“颗”，“颗”用于小粒、圆形的东西；说调整组织的编制，直接说“调整了建制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
