INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87559, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "新建（办事处、分支机构、门诊等场所），并让它开始工作。", "primary_collocate": null, "pronunciation": "shè lì", "ipa": "ʂɤ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "公司在上海设立了一个办事处。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府在这里设立了一个服务中心。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校决定设立一个图书室。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行在小区门口设立了新的分行。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院设立了儿童门诊。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司准备在北京设立分公司。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府设立了一个电话中心，帮助市民。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学在山里设立了一个研究站。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在国外设立了办公室。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里设立了几个咨询点。", "target_word": "设立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设立了", "label": "体标"}, {"form": "设立过", "label": "体标"}, {"form": "設立", "label": "繁体"}], "register": "书面", "sense_fingerprint": "新建办事处、门诊等场所并让它开始工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87559, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立指新建机构或场所，读 shè lì。"}, {"text": "树立", "is_correct": false, "explanation": "shù（第四声）与 shè 韵母不同（u 与 e），意思是树立，如“树立榜样”。"}, {"text": "竖立", "is_correct": false, "explanation": "shù 与 shè 韵母不同（u 与 e），意思是竖起来、直立。"}, {"text": "设计", "is_correct": false, "explanation": "jì 与 lì 声母不同（j 与 l），意思是设计、规划。"}], "explanations": {"设立": "正确。设立指新建机构或场所，读 shè lì。", "树立": "shù（第四声）与 shè 韵母不同（u 与 e），意思是树立，如“树立榜样”。", "竖立": "shù 与 shè 韵母不同（u 与 e），意思是竖起来、直立。", "设计": "jì 与 lì 声母不同（j 与 l），意思是设计、规划。"}, "sentence_index": null, "correct_answer": "设立"}, "level_3": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立表示新建办事处这类场所，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：办事处不能被“吃”，句子表示新建机构，与吃的意思无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲等，不能搭配“办事处”。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指掘开土地，不能表示新建一个办事处。"}], "explanations": {"设立": "正确。设立表示新建办事处这类场所，与句意相符。", "吃": "语义：办事处不能被“吃”，句子表示新建机构，与吃的意思无关。", "唱": "搭配：“唱”的宾语应是歌曲等，不能搭配“办事处”。", "挖": "语义：“挖”指掘开土地，不能表示新建一个办事处。"}, "sentence_index": 0, "correct_answer": "设立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国设立了良好的关系。", "explanation": "这里应该用〈建立〉。设立多用于机构、场所，关系、联系要用〈建立〉。"}, {"text": "老师设立学生的兴趣。", "explanation": "这里应该用〈培养〉。设立指新建机构、场所，兴趣这类个人品质要用〈培养〉。"}, {"text": "他努力设立良好的形象。", "explanation": "这里应该用〈树立〉。设立用于机构、场所，形象、榜样要用〈树立〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立表示新建一个为市民服务的电话中心，与“帮助市民”相符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除，与“帮助市民”的意思相反，句子不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能作用于“电话中心”，二者搭配不当。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”表示咽下，不能用于新建机构。"}], "explanations": {"设立": "正确。设立表示新建一个为市民服务的电话中心，与“帮助市民”相符。", "拆": "语义：“拆”指拆除，与“帮助市民”的意思相反，句子不通。", "喝": "搭配：“喝”不能作用于“电话中心”，二者搭配不当。", "吞": "语义：“吞”表示咽下，不能用于新建机构。"}, "sentence_index": 6, "correct_answer": "设立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在墙上设立了一个灯。", "explanation": "这里应该用〈安装〉。设立指新建机构、场所，灯具这类装置要用〈安装〉。"}, {"text": "我在手机上设立了闹钟。", "explanation": "这里应该用〈设置〉。设立指建立机构或场所，闹钟这类功能要用〈设置〉。"}, {"text": "学校设立了一场比赛。", "explanation": "这里应该用〈举办〉。设立指新建机构、制度，比赛、活动要用〈举办〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家银行在深圳设立了一本分行。", "corrected_sentence": "这家银行在深圳设立了一家分行。", "error_description": "错误在“一本”。“本”用于书本等，机构、分行要用量词“家”，应说“设立了一家分行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
