INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立指新建奖学金、制度等，读 shè lì。"}, {"text": "树立", "is_correct": false, "explanation": "shù（第四声）与 shè 韵母不同（u 与 e），意思是树立，如“树立榜样”。"}, {"text": "竖立", "is_correct": false, "explanation": "shù 与 shè 韵母不同（u 与 e），意思是竖起来、直立。"}, {"text": "设计", "is_correct": false, "explanation": "jì 与 lì 声母不同（j 与 l），意思是设计、规划。"}], "explanations": {"设立": "正确。设立指新建奖学金、制度等，读 shè lì。", "树立": "shù（第四声）与 shè 韵母不同（u 与 e），意思是树立，如“树立榜样”。", "竖立": "shù 与 shè 韵母不同（u 与 e），意思是竖起来、直立。", "设计": "jì 与 lì 声母不同（j 与 l），意思是设计、规划。"}, "sentence_index": null, "correct_answer": "设立"}, "level_3": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立指新建奖学金，与句意相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与句中新设奖学金的意思相反。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，不能用来指设置奖学金。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语应是衣物等，不能搭配“奖学金”。"}], "explanations": {"设立": "正确。设立指新建奖学金，与句意相符。", "扔": "语义：“扔”指丢弃，与句中新设奖学金的意思相反。", "咬": "语义：“咬”指用牙齿咬，不能用来指设置奖学金。", "洗": "搭配：“洗”的宾语应是衣物等，不能搭配“奖学金”。"}, "sentence_index": 0, "correct_answer": "设立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议设立了改革的方向。", "explanation": "这里应该用〈确立〉。设立指新建机构、奖项、制度，方向、目标要用〈确立〉。"}, {"text": "两国设立了友好的关系。", "explanation": "这里应该用〈建立〉。设立指新建机构、制度、奖项，关系要用〈建立〉。"}, {"text": "他设立了早起的习惯。", "explanation": "这里应该用〈养成〉。设立指新建机构、制度、奖项，习惯要用〈养成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED