INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立表示新建奖项，与“科学奖”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，不能用于新建奖项。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，不能用于设立奖项。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，与“科学奖”搭配不当。"}], "explanations": {"设立": "正确。设立表示新建奖项，与“科学奖”相符。", "煮": "语义：“煮”指加热食物，不能用于新建奖项。", "踢": "语义：“踢”指用脚击打，不能用于设立奖项。", "穿": "搭配：“穿”的宾语应是衣物，与“科学奖”搭配不当。"}, "sentence_index": 6, "correct_answer": "设立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校设立了开学典礼。", "explanation": "这里应该用〈举行〉。设立指新建机构、奖项、制度，典礼、会议要用〈举行〉。"}, {"text": "他设立了一篇文章。", "explanation": "这里应该用〈发表〉。设立指新建机构或制度，文章这类作品要用〈发表〉。"}, {"text": "政府设立了新的法律。", "explanation": "这里应该用〈制定〉。设立指新建机构、制度、奖项，法律要用〈制定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校去年设立着一个助学基金。", "corrected_sentence": "学校去年设立了一个助学基金。", "error_description": "体标错误：“去年”表示动作已经完成，“设立”是一次完成的动作，不能用表示持续的“着”，应改为“设立了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学正在设立了一个奖励基金。", "corrected_sentence": "这所大学设立了一个奖励基金。", "error_description": "错误在“正在”。“正在”表示动作进行中，与表示完成的“了”冲突；“设立”是一次完成的动作，应去掉“正在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
