INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87561, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年底是一年里最后的那几天。", "primary_collocate": null, "pronunciation": "nián dǐ", "ipa": "njɛn˧˥ ti˨˩", "syllable_count": 2, "sentences": [{"text": "年底大家都很忙。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年底要回老家过年。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了年底，公司会发奖金。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底的时候，商店里人很多。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打算年底搬到新家。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底前我要把工作做完。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底天气很冷，下了大雪。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说年底要大扫除。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年年底我去了北京。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底快到了，火车票很难买。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年中最后的那几天，临近过年的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87561, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年底", "is_correct": true, "explanation": "正确。“年底”指一年最后的几天，作时间主语，句意通顺。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机不表示时间，不能作“大家都很忙”的时间背景。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不表示时间段，放在句首说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”多与“发”“涨”搭配，不与“忙”搭配。"}], "explanations": {"年底": "正确。“年底”指一年最后的几天，作时间主语，句意通顺。", "洗衣机": "语义：洗衣机不表示时间，不能作“大家都很忙”的时间背景。", "手机": "语义：手机是通讯工具，不表示时间段，放在句首说不通。", "工资": "搭配：“工资”多与“发”“涨”搭配，不与“忙”搭配。"}, "sentence_index": 0, "correct_answer": "年底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年底的时候，我们去海边避暑。", "explanation": "这里应该用〈夏天〉。“避暑”是夏天的活动，而“年底”指一年的末尾，二者时间矛盾。"}, {"text": "三月的年底，商店里人很多。", "explanation": "这里应该用〈月底〉。“年底”指一年最后的几天，不能指某个月的末尾；指三月末应说“三月底”或“月底”。"}, {"text": "每天年底都要去上班。", "explanation": "这里应该用〈每年〉。“年底”一年只出现一次，表示每年都有要说“每年年底”，不能与“每天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年底", "is_correct": true, "explanation": "正确。“年底”指一年的末尾，与“天气很冷，下了大雪”的冬季情境相符。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天不会下大雪，与句中“下了大雪”矛盾。"}, {"text": "雨季", "is_correct": false, "explanation": "搭配：“雨季”多与下雨、潮湿搭配，不与“下大雪”搭配。"}, {"text": "端午", "is_correct": false, "explanation": "语义：端午节在夏季，与“下了大雪”矛盾。"}], "explanations": {"年底": "正确。“年底”指一年的末尾，与“天气很冷，下了大雪”的冬季情境相符。", "夏天": "语义：夏天不会下大雪，与句中“下了大雪”矛盾。", "雨季": "搭配：“雨季”多与下雨、潮湿搭配，不与“下大雪”搭配。", "端午": "语义：端午节在夏季，与“下了大雪”矛盾。"}, "sentence_index": 6, "correct_answer": "年底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我祝大家年底快乐。", "explanation": "这里应该用〈新年〉。固定祝福语是“新年快乐”，“年底”不用于向人祝福新一年。"}, {"text": "年底早上七点，我们去火车站。", "explanation": "这里应该用〈那天〉。“年底”指一段较长的时间，不能直接与具体钟点“早上七点”组合；指某一天应说“那天早上”。"}, {"text": "这个月年底要还贷款。", "explanation": "这里应该用〈月底〉。“年底”指一年的末尾，不能指这个月的末尾，应说“这个月底”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年底的前我们要把房子卖掉。", "corrected_sentence": "年底前我们要把房子卖掉。", "error_description": "“年底”与“前”之间不用“的”，应说“年底前”；“年底的前”不成话，错误在于多出结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年底地时候，我想去看望爷爷。", "corrected_sentence": "年底的时候，我想去看望爷爷。", "error_description": "结构助词误用：修饰名词「时候」应用「的」，不能用「地」，应说「年底的时候」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
