INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年的最后一段时间。", "primary_collocate": null, "pronunciation": "nián dǐ", "ipa": "njɛn˧˥ ti˨˩", "syllable_count": 2, "sentences": [{"text": "年底银行里的人特别多。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年底有一个大会。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司年底要算账。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说年底要考试。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底我想去海边玩。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从十月到年底，他一直在国外。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底的时候，学校放寒假。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年底就要结婚了。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年年底，我们会搬家。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底了，大家开始准备新年礼物。", "target_word": "年底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年的最后一段时间，常指最后一两个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年底", "is_correct": true, "explanation": "正确。“年底”指最后一两个月，作时间主语，句意通顺。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是日用品，不表示时间，放在句首说不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是饮食，不表示时间段，放在句首说不通。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“存款”多与“存”“取”搭配，不与“人特别多”搭配。"}], "explanations": {"年底": "正确。“年底”指最后一两个月，作时间主语，句意通顺。", "牙刷": "语义：牙刷是日用品，不表示时间，放在句首说不通。", "午饭": "语义：午饭是饮食，不表示时间段，放在句首说不通。", "存款": "搭配：“存款”多与“存”“取”搭配，不与“人特别多”搭配。"}, "sentence_index": 0, "correct_answer": "年底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年底我们举办了一次夏令营开幕式。", "explanation": "这里应该用〈夏天〉。夏令营多在夏天举办，“年底”指一年的末尾，二者时间矛盾。"}, {"text": "老师说年底九点要考试。", "explanation": "这里应该用〈那天〉。“年底”指一段较长的时间，不能直接与具体钟点“九点”组合；指某一天应说“那天”。"}, {"text": "老师说昨天的年底要考试。", "explanation": "这里应该用〈那天〉。“年底”指一段较长的时间，不能当作“昨天”这样的具体某一天来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年底", "is_correct": true, "explanation": "正确。“年底”指学期末、寒假前的时段，与“放寒假”相符。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：寒假通常在冬季，夏天不放寒假。"}, {"text": "暑假", "is_correct": false, "explanation": "语义：暑假与寒假是不同的假期，句中“放寒假”与暑假矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不表示时间，「桌子的时候」说不通。"}], "explanations": {"年底": "正确。“年底”指学期末、寒假前的时段，与“放寒假”相符。", "夏天": "语义：寒假通常在冬季，夏天不放寒假。", "暑假": "语义：暑假与寒假是不同的假期，句中“放寒假”与暑假矛盾。", "桌子": "语义：桌子不表示时间，「桌子的时候」说不通。"}, "sentence_index": 6, "correct_answer": "年底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祝大家年底快乐。", "explanation": "这里应该用〈元旦〉。固定祝福语是“元旦快乐”，“年底”不用于问候。"}, {"text": "比赛的年底已经结束了。", "explanation": "这里应该用〈末尾〉。“年底”只指一年的末尾，不能指比赛的末尾，应说“比赛的末尾”。"}, {"text": "她每天年底都去跑步。", "explanation": "这里应该用〈每年〉。“年底”一年只出现一次，表示每年都有要说“每年年底”，不能与“每天”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年底地时候，公司会组织一次体检。", "corrected_sentence": "年底的时候，公司会组织一次体检。", "error_description": "结构助词误用：修饰名词「时候」应用「的」，不能用「地」，应说「年底的时候」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年底的前我们要交完作业。", "corrected_sentence": "年底前我们要交完作业。", "error_description": "“年底”与“前”之间不用“的”，应说“年底前”；“年底的前”不成话，错误在于多出结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
