INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卫视是用卫星把节目传到很远地方的电视台。", "primary_collocate": null, "pronunciation": "wèi shì", "ipa": "uei˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "卫视用卫星传节目，全国都能看到。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在山里的人也能看卫视。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天晚上都看卫视的新闻。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家卫视的电影频道很有意思。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢看那个卫视的唱歌比赛。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫视的节目很多，我常常看到半夜。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喜欢看卫视里的老电视剧。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外也能看到中国的卫视。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看卫视的新闻学汉语。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个卫视新开了一个旅游节目。", "target_word": "卫视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "卫视台", "label": "复合"}], "register": "中性", "sense_fingerprint": "用卫星把节目传到远方的电视台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87563, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卫视", "is_correct": true, "explanation": "卫视（wèi shì）是“卫星电视”的简称，指用卫星传送节目的电视台，是正确答案。"}, {"text": "委实", "is_correct": false, "explanation": "委实（wěi shí）与卫视（wèi shì）两个音节的声调都不同：wěi 为第三声，wèi 为第四声；shí 为第二声，shì 为第四声。意思是确实、实在。"}, {"text": "威势", "is_correct": false, "explanation": "威势（wēi shì）第一个音节是第一声，与卫视的第四声（wèi）不同；意思是威力、权势。"}, {"text": "为时", "is_correct": false, "explanation": "为时（wèi shí）第二个音节是第二声（shí），与卫视的第四声（shì）不同；意思是处于某个时期，多用于“为时已晚”。"}, {"text": "位数", "is_correct": false, "explanation": "位数（wèi shù）第二个音节的韵母是 u（shù），与卫视的 i（shì）不同；意思是数字的位数。"}], "explanations": {"卫视": "卫视（wèi shì）是“卫星电视”的简称，指用卫星传送节目的电视台，是正确答案。", "委实": "委实（wěi shí）与卫视（wèi shì）两个音节的声调都不同：wěi 为第三声，wèi 为第四声；shí 为第二声，shì 为第四声。意思是确实、实在。", "威势": "威势（wēi shì）第一个音节是第一声，与卫视的第四声（wèi）不同；意思是威力、权势。", "为时": "为时（wèi shí）第二个音节是第二声（shí），与卫视的第四声（shì）不同；意思是处于某个时期，多用于“为时已晚”。", "位数": "位数（wèi shù）第二个音节的韵母是 u（shù），与卫视的 i（shì）不同；意思是数字的位数。"}, "sentence_index": null, "correct_answer": "卫视"}, "level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是播出节目的机构，不能用卫星传节目。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“传节目”要说广播电视机构，报纸不播节目，不能说“报纸用卫星传节目”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能用卫星传节目，与“全国都能看到”的语境不合。"}, {"text": "卫视", "is_correct": true, "explanation": "正确：卫视是用卫星传送节目的电视台，与句中“用卫星传节目，全国都能看到”相符。"}], "explanations": {"厨房": "语义：厨房不是播出节目的机构，不能用卫星传节目。", "报纸": "搭配：“传节目”要说广播电视机构，报纸不播节目，不能说“报纸用卫星传节目”。", "冰箱": "语义：冰箱是家用电器，不能用卫星传节目，与“全国都能看到”的语境不合。", "卫视": "正确：卫视是用卫星传送节目的电视台，与句中“用卫星传节目，全国都能看到”相符。"}, "sentence_index": 0, "correct_answer": "卫视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家卫视只在本市能看到。", "explanation": "这里应该用〈地方台〉。卫视用卫星把节目传到远方，覆盖范围广，不能说只在本市能看到；只在本地播出要用地方台。"}, {"text": "他常去外地采访，是个卫视。", "explanation": "这里应该用〈记者〉。卫视是电视台，不指人；“是个……”后要接表示人的词，应说“是个记者”。"}, {"text": "我把卫视放在客厅里了。", "explanation": "这里应该用〈电视机〉。卫视是电视台，不是能放在客厅里的机器；放在家里的是电视机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场不播放电视剧，“奶奶喜欢看菜市场里的老电视剧”说不通。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不播放电视剧，“看银行里的老电视剧”不合常理，与句意不合。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：电视剧要在能播放节目的地方看，花园里不放电视剧，“看花园里的老电视剧”搭配不当。"}, {"text": "卫视", "is_correct": true, "explanation": "正确：卫视是播放电视剧的电视台，“看卫视里的老电视剧”合理，符合句意。"}], "explanations": {"菜市场": "语义：菜市场不播放电视剧，“奶奶喜欢看菜市场里的老电视剧”说不通。", "银行": "语义：银行不播放电视剧，“看银行里的老电视剧”不合常理，与句意不合。", "花园": "搭配：电视剧要在能播放节目的地方看，花园里不放电视剧，“看花园里的老电视剧”搭配不当。", "卫视": "正确：卫视是播放电视剧的电视台，“看卫视里的老电视剧”合理，符合句意。"}, "sentence_index": 6, "correct_answer": "卫视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卫视上列着下周的电影。", "explanation": "这里应该用〈节目表〉。卫视是电视台，不是能列出电影的表格；“……上列着……”要用节目表。"}, {"text": "全国有三本卫视。", "explanation": "这里应该用〈家〉。卫视的量词是“家”；“本”用于书刊等，不用于卫视。"}, {"text": "他是很受欢迎的卫视。", "explanation": "这里应该用〈主持人〉。卫视指电视台，不指人；“他是……”要用表示人的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只卫视的新闻节目每天都会播出。", "corrected_sentence": "这家卫视的新闻节目每天都会播出。", "error_description": "量词错误：卫视是电视台，应该用量词“家”，不能用“只”。正确说法是“这家卫视”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们城市有一只卫视在播旅游节目。", "corrected_sentence": "我们城市有一家卫视在播旅游节目。", "error_description": "量词错误：卫视是电视台，量词应用“家”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
