INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强使是用力量让别人一定要这样做，不管他愿不愿意。", "primary_collocate": null, "pronunciation": "qiǎng shǐ", "ipa": "tɕʰjaŋ˨˩˦ ʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他强使孩子每天练琴三个小时。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能强使别人做不愿意的事。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板强使工人在周末加班。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用权力强使大家同意这个办法。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大人不应该强使孩子学自己不喜欢的东西。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人强使他交出了所有的钱。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能强使客人喝酒。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家强使农民离开了自己的土地。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从来没有强使过学生背书。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强使弟弟每天早起，弟弟很累。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强使了", "label": "完成体"}, {"form": "强使过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "用力量逼别人照做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强使", "is_correct": true, "explanation": "强使：用力量让孩子每天练琴，与句中“每天练琴三个小时”的意思相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是把东西抛掉，不能用来对孩子施加要求，与练琴也无关，句子读不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于人时只指清洁身体，不能接“练琴三个小时”这类活动。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是把食物放进嘴里，不能用来对孩子提出练琴的要求，句子读不通。"}], "explanations": {"强使": "强使：用力量让孩子每天练琴，与句中“每天练琴三个小时”的意思相符。", "扔": "语义：“扔”是把东西抛掉，不能用来对孩子施加要求，与练琴也无关，句子读不通。", "洗": "搭配：“洗”用于人时只指清洁身体，不能接“练琴三个小时”这类活动。", "吃": "语义：“吃”是把食物放进嘴里，不能用来对孩子提出练琴的要求，句子读不通。"}, "sentence_index": 0, "correct_answer": "强使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用道理强使大家同意这个办法。", "explanation": "这里应该用〈说服〉。强使是用力量逼人照做，靠道理让人同意应说说服，“用道理”与“强使”相矛盾。"}, {"text": "我强使他喜欢上了画画。", "explanation": "这里应该用〈引导〉。强使是用力量逼人照做，喜欢不能靠强迫产生，应说引导或培养。"}, {"text": "他强使我佩服他的成绩。", "explanation": "这里应该用〈赢得〉。强使是用力量逼人照做，佩服是心悦诚服的态度，不能靠强迫产生，应说赢得某人的佩服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强使", "is_correct": true, "explanation": "强使：用力量让客人去做某事，与句中“不能……客人喝酒”的语境相符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是用力撞击，不能用来让客人去做喝酒这件事，句子读不通。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理物品，不能用于人，与“客人喝酒”搭配不上。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是商品，不能说买人，与“客人喝酒”的说法不搭。"}], "explanations": {"强使": "强使：用力量让客人去做某事，与句中“不能……客人喝酒”的语境相符。", "砸": "语义：“砸”是用力撞击，不能用来让客人去做喝酒这件事，句子读不通。", "修": "语义：“修”是修理物品，不能用于人，与“客人喝酒”搭配不上。", "买": "搭配：“买”的宾语是商品，不能说买人，与“客人喝酒”的说法不搭。"}, "sentence_index": 6, "correct_answer": "强使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息强使我们高兴起来。", "explanation": "这里应该用〈让〉。强使是用力量逼人照做，消息不能用力量逼人，应说让人高兴。"}, {"text": "他强使神灵保佑家人。", "explanation": "这里应该用〈祈求〉。神灵无法被强迫，向神灵表达恳求应说祈求，不能用强使。"}, {"text": "我强使你早日康复。", "explanation": "这里应该用〈盼望〉。康复不能靠强迫，表示美好的祝愿应说盼望，强使与语境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲强使让儿子去参加比赛。", "corrected_sentence": "父亲强使儿子去参加比赛。", "error_description": "“强使”本身已含有“使”的意思，后面不能再加“让”。应为“父亲强使儿子去参加比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班主任不强使了学生参加比赛。", "corrected_sentence": "班主任不强使学生参加比赛。", "error_description": "“了”不能放在否定的“不强使”和宾语“学生”之间。否定句里“了”应放在句末，表示不再这样做：应为“班主任不强使学生参加比赛了”，或直接删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
