INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强迫使（某人做某事）。", "primary_collocate": null, "pronunciation": "qiǎng shǐ", "ipa": "tɕʰjaŋ˨˩˦ ʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "医生不能强使病人接受这种治疗。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方强使我们签了那份合同。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大国强使小国改变了自己的政策。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从不强使我做不喜欢的工作。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强使弟弟把玩具交给了自己。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司强使员工在年底前搬到新城市。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用武力强使村民离开了家。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不能强使人相信某种说法。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强使自己笑，其实心里很难过。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，没有人强使过他做决定。", "target_word": "强使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强使了", "label": "完成体"}, {"form": "强使过", "label": "经历体"}, {"form": "强使着", "label": "持续体"}], "register": "书面", "sense_fingerprint": "强迫某人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强使", "is_correct": true, "explanation": "强使：用力量迫使病人接受治疗，与句中的语境相符。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”是用手臂环住，不能表示让病人接受治疗，句子读不通。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”是关闭或拘禁，与“接受这种治疗”无关，句子读不通。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的宾语是商品，不能说购买病人，与“接受这种治疗”的说法不搭。"}], "explanations": {"强使": "强使：用力量迫使病人接受治疗，与句中的语境相符。", "抱": "语义：“抱”是用手臂环住，不能表示让病人接受治疗，句子读不通。", "关": "语义：“关”是关闭或拘禁，与“接受这种治疗”无关，句子读不通。", "购买": "搭配：“购买”的宾语是商品，不能说购买病人，与“接受这种治疗”的说法不搭。"}, "sentence_index": 0, "correct_answer": "强使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我强使老板感激我。", "explanation": "这里应该用〈打动〉。强使是用力量逼人照做，感激是内心的情感，不能靠强迫产生，应说打动某人。"}, {"text": "老师强使学生对科学充满好奇。", "explanation": "这里应该用〈激发〉。强使是用力量迫使人做某事，好奇心不能靠强迫产生，应说激发。"}, {"text": "我强使你开心起来。", "explanation": "这里应该用〈逗〉。强使是用力量逼人照做，情绪不能被强迫，应说逗人开心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强使", "is_correct": true, "explanation": "强使：用武力迫使村民离开，与句中“用武力”的手段相符。"}, {"text": "劝", "is_correct": false, "explanation": "搭配：劝说靠道理，与“用武力”相抵，不能说用武力来劝。"}, {"text": "请", "is_correct": false, "explanation": "语义：“请”是礼貌地邀请，与“用武力”的强制手段矛盾，句子读不通。"}, {"text": "感动", "is_correct": false, "explanation": "语义：“感动”是使人动情，与“用武力”搭配不上，句子读不通。"}], "explanations": {"强使": "强使：用武力迫使村民离开，与句中“用武力”的手段相符。", "劝": "搭配：劝说靠道理，与“用武力”相抵，不能说用武力来劝。", "请": "语义：“请”是礼貌地邀请，与“用武力”的强制手段矛盾，句子读不通。", "感动": "语义：“感动”是使人动情，与“用武力”搭配不上，句子读不通。"}, "sentence_index": 6, "correct_answer": "强使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信强使我们来做客。", "explanation": "这里应该用〈邀请〉。强使是用力量逼人照做，信件不能用力量逼人，应说邀请我们来做客。"}, {"text": "他强使神灵保佑家人。", "explanation": "这里应该用〈祈求〉。神灵无法被强迫，向神灵表达恳求应说祈求，不能用强使。"}, {"text": "我强使你早日康复。", "explanation": "这里应该用〈盼望〉。康复不能靠强迫，表示美好的祝愿应说盼望，强使与语境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈强使去洗碗。", "corrected_sentence": "妈妈强使弟弟去洗碗。", "error_description": "“强使”后面必须带出被强迫的人，此处漏掉了“弟弟”。应为“妈妈强使弟弟去洗碗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师强使学生了背课文。", "corrected_sentence": "老师强使学生背了课文。", "error_description": "“了”应放在动作“背”的后面，表示动作完成。应为“老师强使学生背了课文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
