INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "资金是用来做一件事的钱。", "primary_collocate": null, "pronunciation": "zī jīn", "ipa": "tsɹ̩⁵⁵ tɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们需要一笔资金来办这个活动。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用这笔资金买了新书。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路的资金已经准备好了。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们缺少资金，所以不能开店。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想开一家小店，可是资金不够。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们为这次旅行筹集了一些资金。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔资金只能用来修桥，不能做别的事。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开公司前，你要先准备好资金。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把资金都用在了孩子的学习上。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这台机器的资金还差一万元。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；为做某件事准备的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ececac-152b-4004-ac0a-24281145fd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87567, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资金", "is_correct": true, "explanation": "正确答案：资金（zī jīn），指为做某件事准备的钱。"}, {"text": "丝巾", "is_correct": false, "explanation": "sī 与 zī 声母不同（s 与 z），意思是丝织的围巾。"}, {"text": "紫金", "is_correct": false, "explanation": "zǐ（第三声）与 zī（第一声）声调不同，意思是紫色的金子。"}, {"text": "子金", "is_correct": false, "explanation": "zǐ（第三声）与 zī（第一声）声调不同，意思是利息。"}], "explanations": {"资金": "正确答案：资金（zī jīn），指为做某件事准备的钱。", "丝巾": "sī 与 zī 声母不同（s 与 z），意思是丝织的围巾。", "紫金": "zǐ（第三声）与 zī（第一声）声调不同，意思是紫色的金子。", "子金": "zǐ（第三声）与 zī（第一声）声调不同，意思是利息。"}, "sentence_index": null, "correct_answer": "资金"}, "level_3": {"options": [{"text": "资金", "is_correct": true, "explanation": "资金指用来做事的钱，与“一笔”搭配，符合“办这个活动”的需要。"}, {"text": "人员", "is_correct": false, "explanation": "搭配：量词“笔”用于钱款，不能用来计量“人员”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是可以用来办活动的钱款，与“一笔”也不搭配。"}, {"text": "场地", "is_correct": false, "explanation": "搭配：“场地”用“块”或“片”计量，不能与量词“笔”搭配。"}], "explanations": {"资金": "资金指用来做事的钱，与“一笔”搭配，符合“办这个活动”的需要。", "人员": "搭配：量词“笔”用于钱款，不能用来计量“人员”。", "时间": "语义：“时间”不是可以用来办活动的钱款，与“一笔”也不搭配。", "场地": "搭配：“场地”用“块”或“片”计量，不能与量词“笔”搭配。"}, "sentence_index": 0, "correct_answer": "资金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林是重要的自然资金。", "explanation": "这里应该用〈资源〉。资源指自然界中可以利用的东西，资金只指钱款，不能用来修饰森林等自然物。"}, {"text": "这份资金一共有二十页，请大家仔细读。", "explanation": "这里应该用〈资料〉。资料是可以阅读的文字材料，资金指钱款，不能按页阅读。"}, {"text": "我们每天都要看最新的资金。", "explanation": "这里应该用〈资讯〉。资讯指新闻和信息，资金只指钱款，不能用来指需要阅读的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资金", "is_correct": true, "explanation": "资金指钱款，与“这笔”搭配，只能用于修桥，符合句意。"}, {"text": "工人", "is_correct": false, "explanation": "语义：“工人”是人，不能“用来修桥”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，不能用来修桥。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：量词“笔”不能用来计量“黑板”，“黑板”应用“块”计量。"}], "explanations": {"资金": "资金指钱款，与“这笔”搭配，只能用于修桥，符合句意。", "工人": "语义：“工人”是人，不能“用来修桥”。", "面包": "语义：“面包”是食物，不能用来修桥。", "黑板": "搭配：量词“笔”不能用来计量“黑板”，“黑板”应用“块”计量。"}, "sentence_index": 6, "correct_answer": "资金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的资金包括几座厂房和大量设备。", "explanation": "这里应该用〈资产〉。资产指公司拥有的厂房、设备等财产；资金只指用来做事的钱款，不能用来指实物。"}, {"text": "药店里有很多资金，都是进口的。", "explanation": "这里应该用〈药品〉。药品指可以买卖的药物；资金只指用来做事的钱款，不能用来指商品。"}, {"text": "仓库里的资金都是饮料。", "explanation": "这里应该用〈库存〉。库存指仓库中存放的货物；资金指钱款，不能用来指饮料等货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校为新的实验室准备了一本资金。", "corrected_sentence": "这所学校为新的实验室准备了一笔资金。", "error_description": "量词错误：“资金”应用量词“笔”计量，不能用“本”。“本”用于书籍、本子等，“笔”用于钱款和资金。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这三笔资金们都已经到账了。", "corrected_sentence": "这三笔资金都已经到账了。", "error_description": "词缀错误：“们”只用于指人的名词，资金不是人，不能加“们”表示复数，应直接说“这三笔资金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
