INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古代帝王用来纪年的名号，如\"贞观\"\"康熙\"。", "primary_collocate": null, "pronunciation": "nián hào", "ipa": "njɛn˧˥ xaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "康熙是清朝一位皇帝的年号。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贞观是唐太宗用过的年号。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新皇帝一上台，就改了年号。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代皇帝登基后，会定一个新年号。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝的万历年号用了四十八年。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里常用年号纪年。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乾隆这个年号一共用了六十年。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，清朝最后一个年号是宣统。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位皇帝一生换过好几个年号。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古装剧里常听到“永乐”这样的年号。", "target_word": "年号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "年號", "label": "繁体"}], "register": "书面", "sense_fingerprint": "古代帝王纪年所用的名号，如贞观、康熙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年号", "is_correct": true, "explanation": "正确：年号，古代帝王用来纪年的名号。"}, {"text": "连号", "is_correct": false, "explanation": "lián 与 nián 声调相同，但声母 l 与 n 不同，意思是连续的编号。"}, {"text": "年货", "is_correct": false, "explanation": "年货（nián huò）与年号（nián hào）只差韵母（uo 与 ao），意思是过年时买的东西。"}, {"text": "年报", "is_correct": false, "explanation": "bào 与 hào 声母不同，意思是一年一度的报告。"}], "explanations": {"年号": "正确：年号，古代帝王用来纪年的名号。", "连号": "lián 与 nián 声调相同，但声母 l 与 n 不同，意思是连续的编号。", "年货": "年货（nián huò）与年号（nián hào）只差韵母（uo 与 ao），意思是过年时买的东西。", "年报": "bào 与 hào 声母不同，意思是一年一度的报告。"}, "sentence_index": null, "correct_answer": "年号"}, "level_3": {"options": [{"text": "年号", "is_correct": true, "explanation": "正确：“年号”指皇帝的纪年名号，与“康熙是清朝一位皇帝的”相符。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”常与“多大”“几岁”搭配，不能用作皇帝的称号。"}, {"text": "首都", "is_correct": false, "explanation": "语义：“首都”指城市，不是皇帝的名号。"}, {"text": "寿辰", "is_correct": false, "explanation": "语义：“寿辰”指生日，与“康熙”这一名号不符。"}], "explanations": {"年号": "正确：“年号”指皇帝的纪年名号，与“康熙是清朝一位皇帝的”相符。", "年纪": "搭配：“年纪”常与“多大”“几岁”搭配，不能用作皇帝的称号。", "首都": "语义：“首都”指城市，不是皇帝的名号。", "寿辰": "语义：“寿辰”指生日，与“康熙”这一名号不符。"}, "sentence_index": 0, "correct_answer": "年号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位运动员得到了一个新的年号。", "explanation": "这里应该用〈称号〉。年号只用于古代帝王纪年，运动员的荣誉名称要用“称号”。"}, {"text": "这座古塔的年号很久远了。", "explanation": "这里应该用〈年代〉。年号是帝王的纪年名号，不能用来说明文物的时间久远。"}, {"text": "这套邮票的年号是1998年。", "explanation": "这里应该用〈年份〉。年号是帝王的纪年名号，如“贞观”，而公历的年数要说“年份”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年号", "is_correct": true, "explanation": "正确：“年号”是皇帝的纪年名号，与“乾隆这个……”相符，且可以“用了六十年”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“用了……年”要求被用的对象是可以被使用的东西，“年龄”不能这样搭配。"}, {"text": "生平", "is_correct": false, "explanation": "语义：“生平”指一个人一生的经历，不是可以“用”的名号。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与“乾隆”和“用了六十年”都不搭。"}], "explanations": {"年号": "正确：“年号”是皇帝的纪年名号，与“乾隆这个……”相符，且可以“用了六十年”。", "年龄": "搭配：“用了……年”要求被用的对象是可以被使用的东西，“年龄”不能这样搭配。", "生平": "语义：“生平”指一个人一生的经历，不是可以“用”的名号。", "体重": "语义：“体重”指身体的重量，与“乾隆”和“用了六十年”都不搭。"}, "sentence_index": 6, "correct_answer": "年号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们国家的年号是中华人民共和国。", "explanation": "这里应该用〈国号〉。年号是帝王纪年的名号，国家的名称要用“国号”。"}, {"text": "同学们都给他取了一个年号。", "explanation": "这里应该用〈绰号〉。绰号是别人给人取的外号，年号只指帝王的纪年名号，不能用来称呼同学。"}, {"text": "这家公司的年号很响亮。", "explanation": "这里应该用〈名称〉。年号只指帝王的纪年名号，公司的名称不能叫年号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位皇帝一共用过三只年号。", "corrected_sentence": "这位皇帝一共用过三个年号。", "error_description": "量词错误：“年号”应用量词“个”，不能用“只”（“只”多用于动物或成对的东西）。应说“三个年号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位皇帝刚定了一个新年号们。", "corrected_sentence": "这位皇帝刚定了一个新年号。", "error_description": "词缀错误：“年号”是无生名词，不能加复数后缀“们”。已用“一个”表示数量，应说“一个新年号”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
