INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "亲属是和你有血缘或结婚关系的家里人。", "primary_collocate": null, "pronunciation": "qīn shǔ", "ipa": "tɕʰin˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "亲属就是家里的亲人。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加婚礼的亲属很多。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的亲属都很关心他。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在北京有一位亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后，对方的家人也成了你的亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我的亲属，不是普通朋友。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我去看了亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲属们坐在一起聊天。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把好消息告诉了亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们是亲属吗？我们是表兄弟。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "近亲属", "label": "复合"}, {"form": "直系亲属", "label": "复合"}], "register": "中性", "sense_fingerprint": "和自己有血缘或结婚关系的家里人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲属", "is_correct": true, "explanation": "正确：亲属指有血缘或婚姻关系的家里人，与“家里的亲人”同指，句意成立。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：陌生人与家里的亲人相反，不能作“亲人”的定义。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“是……亲人”要求人作主语，家具不能是亲人。"}, {"text": "客人", "is_correct": false, "explanation": "语义：客人是来访的人，不属于家里的亲人。"}], "explanations": {"亲属": "正确：亲属指有血缘或婚姻关系的家里人，与“家里的亲人”同指，句意成立。", "陌生人": "语义：陌生人与家里的亲人相反，不能作“亲人”的定义。", "家具": "搭配：“是……亲人”要求人作主语，家具不能是亲人。", "客人": "语义：客人是来访的人，不属于家里的亲人。"}, "sentence_index": 0, "correct_answer": "亲属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的亲属很多，都是同一品牌。", "explanation": "这里应该用〈同类〉。亲属指有血缘或婚姻关系的人，不能用来指电脑，电脑的同类才应这样说。"}, {"text": "这张桌子是我的老亲属，很结实。", "explanation": "这里应该用〈家具〉。亲属指人，不能用来指桌子，桌子应说“家具”。"}, {"text": "我在路边看到一件亲属。", "explanation": "这里〈亲属〉指人，不能用物品的计量词计数，应说“一位亲属”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲属", "is_correct": true, "explanation": "正确：过年去看望亲属，“看了”指探望，符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“看了”作探望讲时，对象必须是人，空气不能被探望。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“去看了钥匙”不成立，找东西才说“找钥匙”。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是建筑物，不能被探望。"}], "explanations": {"亲属": "正确：过年去看望亲属，“看了”指探望，符合语境。", "空气": "语义：“看了”作探望讲时，对象必须是人，空气不能被探望。", "钥匙": "搭配：“去看了钥匙”不成立，找东西才说“找钥匙”。", "墙": "语义：墙是建筑物，不能被探望。"}, "sentence_index": 6, "correct_answer": "亲属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩一直在培养亲属。", "explanation": "这里应该用〈人才〉。亲属是血缘或婚姻关系形成的人，不能像人才那样培养。"}, {"text": "院子里跑来一只亲属。", "explanation": "这里〈亲属〉指人，不能用动物的计量词计数，应说“一位亲属”。"}, {"text": "我在学校交了很多亲属。", "explanation": "这里应该用〈朋友〉。交到的是朋友，亲属是血缘或婚姻关系形成的，不能这样交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有几件亲属在国外。", "corrected_sentence": "我有几位亲属在国外。", "error_description": "“几件亲属”应为“几位亲属”：〈件〉用于物品，指人要用〈位〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节我见到了好几头亲属。", "corrected_sentence": "春节我见到了好几位亲属。", "error_description": "量词错误：“好几头亲属”应为“好几位亲属”。〈头〉用于牲畜，亲属是人，要用〈位〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
