INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有血缘或婚姻关系的人。", "primary_collocate": null, "pronunciation": "qīn shǔ", "ipa": "tɕʰin˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在这个城市没有亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院通知了病人的亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，亲属们都来我家吃饭。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司不让亲属一起工作。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的亲属都住在南方。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些是我母亲那边的亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的亲属的名字写在这里。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律上，夫妻和子女都是亲属。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲属之间应该互相帮助。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少和远方的亲属联系。", "target_word": "亲属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "近亲属", "label": "复合"}, {"form": "直系亲属", "label": "复合"}], "register": "中性", "sense_fingerprint": "有血缘或婚姻关系的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲属", "is_correct": true, "explanation": "正确：亲属指有血缘或婚姻关系的人，“他在这个城市没有亲属”符合语境。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天是时段，不是可以“没有”的人，句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不能作“没有”的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“没有年龄”不是常用说法，也与“在这个城市”的语境不合。"}], "explanations": {"亲属": "正确：亲属指有血缘或婚姻关系的人，“他在这个城市没有亲属”符合语境。", "白天": "语义：白天是时段，不是可以“没有”的人，句意不通。", "星期": "语义：星期是时间单位，不能作“没有”的对象。", "年龄": "搭配：“没有年龄”不是常用说法，也与“在这个城市”的语境不合。"}, "sentence_index": 0, "correct_answer": "亲属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们办公室的亲属大多是陌生人。", "explanation": "这里应该用〈同事〉。亲属必须有血缘或婚姻关系，不能用来指互不相识的办公室成员，这类人应称为同事。"}, {"text": "我们班的亲属都坐在前排听课。", "explanation": "这里应该用〈同学〉。同学指同班或同校的人，在班里听课的人不属于亲属，应说同学。"}, {"text": "我今天在路上遇见了一件亲属。", "explanation": "这里〈亲属〉指人，不能用物品的计量词计数，应说“一位亲属”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲属", "is_correct": true, "explanation": "正确：亲属是人，“你的亲属的名字”指亲属的姓名，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有名字可以写，“你的天气的名字”说不通。"}, {"text": "风", "is_correct": false, "explanation": "语义：风不是需要登记姓名的对象，“你的风的名字”不成立。"}, {"text": "身材", "is_correct": false, "explanation": "语义：身材指体形，“你的身材的名字”说不通。"}], "explanations": {"亲属": "正确：亲属是人，“你的亲属的名字”指亲属的姓名，符合语境。", "天气": "语义：天气没有名字可以写，“你的天气的名字”说不通。", "风": "语义：风不是需要登记姓名的对象，“你的风的名字”不成立。", "身材": "语义：身材指体形，“你的身材的名字”说不通。"}, "sentence_index": 6, "correct_answer": "亲属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都在培养亲属。", "explanation": "这里应该用〈人才〉。亲属是血缘或婚姻关系形成的人，不能像人才那样培养。"}, {"text": "他家里养了一只亲属。", "explanation": "这里〈亲属〉指人，不能用动物的计量词计数，应说“一位亲属”。"}, {"text": "他在饭店订了很多亲属。", "explanation": "这里应该用〈座位〉。亲属是人，不能被“订”，订的是座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有两只亲属在国外。", "corrected_sentence": "他有两位亲属在国外。", "error_description": "“两只亲属”应为“两位亲属”：〈只〉用于动物，指人要用〈位〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他和亲属的之间经常见面。", "corrected_sentence": "他和亲属之间经常见面。", "error_description": "“亲属的之间”应为“亲属之间”：“之间”前面不能加助词“的”，应直接说“亲属之间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
