INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "复苏是睡着了或没有力气的东西又活过来。", "primary_collocate": null, "pronunciation": "fù sū", "ipa": "fu˥˩ su˥", "syllable_count": 2, "sentences": [{"text": "春天一到，小虫子都复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来后，花草慢慢复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬眠的青蛙春天会复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，干枯的草复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树喝了水，很快就复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天暖了，沉睡的蜜蜂开始复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水一浇，快死的花又复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬眠的熊一到春天就复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的动物在春天复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冻僵的蝴蝶在阳光下慢慢复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复苏了", "label": "体标"}, {"form": "复苏过", "label": "体标"}], "register": "中性", "sense_fingerprint": "复苏：沉睡或没有生气的生物重新活过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复苏", "is_correct": true, "explanation": "正确：“复苏”表示生物重新活过来，与“春天一到，小虫子都”相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：小虫子不会考试，句中说的是春天里的变化。"}, {"text": "发工资", "is_correct": false, "explanation": "搭配：“发工资”需要雇主作主语，小虫子不能发工资。"}, {"text": "下班", "is_correct": false, "explanation": "语义：小虫子没有上班和下班，“下班”与句意不符。"}], "explanations": {"复苏": "正确：“复苏”表示生物重新活过来，与“春天一到，小虫子都”相符。", "考试": "语义：小虫子不会考试，句中说的是春天里的变化。", "发工资": "搭配：“发工资”需要雇主作主语，小虫子不能发工资。", "下班": "语义：小虫子没有上班和下班，“下班”与句意不符。"}, "sentence_index": 0, "correct_answer": "复苏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的感冒终于复苏了。", "explanation": "这里应该用〈痊愈〉。复苏指沉睡或失去生气的生物重新活过来，感冒好了要说痊愈。"}, {"text": "这一批旧书在夏天大量复苏。", "explanation": "这里应该用〈修复〉。复苏指沉睡或失去生气的生物重新活过来，书籍翻新要说修复。"}, {"text": "麦子在七月复苏。", "explanation": "这里应该用〈成熟〉。复苏指重新活过来，庄稼长到可以收获时要说成熟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复苏", "is_correct": true, "explanation": "正确：“复苏”表示快死的花重新活过来，与“热水一浇”相符。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语必须是人，花不能结婚。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”需要人作主语，花不能出差。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能用来描述快死的花的状态变化。"}], "explanations": {"复苏": "正确：“复苏”表示快死的花重新活过来，与“热水一浇”相符。", "结婚": "搭配：“结婚”的主语必须是人，花不能结婚。", "出差": "搭配：“出差”需要人作主语，花不能出差。", "下雨": "语义：“下雨”是天气现象，不能用来描述快死的花的状态变化。"}, "sentence_index": 6, "correct_answer": "复苏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱终于复苏了。", "explanation": "这里应该用〈修好〉。复苏指沉睡或失去生气的生物重新活过来，坏了的冰箱要说修好。"}, {"text": "这座旧桥终于复苏了。", "explanation": "这里应该用〈修缮〉。复苏指沉睡或失去生气的生物重新活过来，桥梁坏了要说修缮。"}, {"text": "这家初创公司迅速复苏。", "explanation": "这里应该用〈崛起〉。复苏要求事物原本已存在而变弱，刚兴起的公司不说复苏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天一到，冬眠的蛇都复苏下来了。", "corrected_sentence": "春天一到，冬眠的蛇都复苏了。", "error_description": "错误形式：“复苏下来了”；正确形式：“复苏了”。“复苏”表示生物重新活过来，后面不接“下来”这类趋向补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冻僵的蝴蝶在阳光下复苏很快。", "corrected_sentence": "冻僵的蝴蝶在阳光下复苏得很快。", "error_description": "错误形式：“复苏很快”；正确形式：“复苏得很快”。表示程度的补语前要用“得”连接动词和补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
