INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "复苏是经济、市场等重新好转。", "primary_collocate": null, "pronunciation": "fù sū", "ipa": "fu˥˩ su˥", "syllable_count": 2, "sentences": [{"text": "今年经济开始复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节过后，餐饮业慢慢复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游业正在复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济复苏需要很长时间。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的市场渐渐复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情过后，房地产市场开始复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说明年消费会复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "降息以后，股市慢慢复苏了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策出台后，外贸订单开始复苏。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场复苏以后，商店的生意变好了。", "target_word": "复苏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复苏了", "label": "体标"}, {"form": "复苏过", "label": "体标"}], "register": "中性", "sense_fingerprint": "复苏：经济、市场等重新好转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复苏", "is_correct": true, "explanation": "正确：“复苏”表示经济重新好转，与“今年经济开始”相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：经济不会融化，“融化”不能用来描述经济好转。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：经济不会唱歌，“唱歌”与经济的变化毫无关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”需要有生命的主语，经济不能吃饭。"}], "explanations": {"复苏": "正确：“复苏”表示经济重新好转，与“今年经济开始”相符。", "融化": "语义：经济不会融化，“融化”不能用来描述经济好转。", "唱歌": "语义：经济不会唱歌，“唱歌”与经济的变化毫无关系。", "吃饭": "搭配：“吃饭”需要有生命的主语，经济不能吃饭。"}, "sentence_index": 0, "correct_answer": "复苏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位病人的病情复苏了。", "explanation": "这里应该用〈好转〉。复苏多指经济重新好转或生物重新活过来，描述病情变化要用好转。"}, {"text": "这个班级的成绩复苏了不少。", "explanation": "这里应该用〈提高〉。复苏指经济重新好转或生物重新活过来，成绩变好要说提高。"}, {"text": "这把椅子的腿终于复苏了。", "explanation": "这里应该用〈修好〉。复苏指经济重新好转或生物重新活过来，坏了的椅子要说修好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复苏", "is_correct": true, "explanation": "正确：“复苏”表示消费重新好转，与“明年消费会”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：消费不会散步，“散步”与消费的变化毫无关系。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”的主语应该是人，消费不能迟到。"}, {"text": "打哈欠", "is_correct": false, "explanation": "搭配：“打哈欠”需要生物作主语，消费不会打哈欠。"}], "explanations": {"复苏": "正确：“复苏”表示消费重新好转，与“明年消费会”相符。", "散步": "语义：消费不会散步，“散步”与消费的变化毫无关系。", "迟到": "搭配：“迟到”的主语应该是人，消费不能迟到。", "打哈欠": "搭配：“打哈欠”需要生物作主语，消费不会打哈欠。"}, "sentence_index": 6, "correct_answer": "复苏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座新兴城市迅速复苏。", "explanation": "这里应该用〈崛起〉。复苏指重新好转或重新活过来，新兴城市是兴起，不说复苏。"}, {"text": "这把旧吉他终于复苏了。", "explanation": "这里应该用〈修好〉。复苏指经济重新好转或生物重新活过来，坏了的乐器要说修好。"}, {"text": "这家新品牌刚刚复苏。", "explanation": "这里应该用〈诞生〉。复苏要求事物原本已经存在而变弱，刚出现的新品牌不说复苏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "就业市场最近开始复苏下来了。", "corrected_sentence": "就业市场最近开始复苏了。", "error_description": "错误形式：“复苏下来了”；正确形式：“复苏了”。“复苏”表示重新好转，后面不接“下来”这类趋向补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个市场复苏的很快。", "corrected_sentence": "这个市场复苏得很快。", "error_description": "错误形式：“复苏的很快”；正确形式：“复苏得很快”。表示程度的补语前要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
