INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87575, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关是把开着的东西合上。", "primary_collocate": null, "pronunciation": "guān", "ipa": "kwan˥", "syllable_count": 1, "sentences": [{"text": "请把窗户关上，外面太吵了。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，我先关灯。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，他关了窗户。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出门时忘了关电视。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水开了，快去关火。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸关着门在房间里看书。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经把电脑关了。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打完电话，她就关了手机。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱门没关好，里面的东西坏了。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请关一下空调，我有点冷。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关了", "label": "体标（完成）"}, {"form": "关着", "label": "体标（持续）"}, {"form": "关掉", "label": "复合词"}, {"form": "關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关灯、关窗：把开着的东西合上或停止运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87575, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：关（guān）指把开着的东西合上或停止运转，与句意相符。"}, {"text": "管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是管子或管理。"}, {"text": "惯", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。"}, {"text": "光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（ang/an），意思是光线。"}, {"text": "宽", "is_correct": false, "explanation": "kuān 与 guān 声母不同（k/g），意思是宽阔。"}], "explanations": {"关": "正确：关（guān）指把开着的东西合上或停止运转，与句意相符。", "管": "guǎn（第三声）与 guān（第一声）声调不同，意思是管子或管理。", "惯": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。", "光": "guāng 与 guān 韵母不同（ang/an），意思是光线。", "宽": "kuān 与 guān 声母不同（k/g），意思是宽阔。"}, "sentence_index": null, "correct_answer": "关"}, "level_3": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：关上窗户以隔绝噪音，符合「外面太吵了」的语境。"}, {"text": "开", "is_correct": false, "explanation": "语义：开窗会让噪音进来，与「外面太吵」的原因相反。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦窗户是清洁动作，与「外面太吵」的理由无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」不能带「上」表示合拢，「把窗户洗上」不成立。"}], "explanations": {"关": "正确：关上窗户以隔绝噪音，符合「外面太吵了」的语境。", "开": "语义：开窗会让噪音进来，与「外面太吵」的原因相反。", "擦": "语义：擦窗户是清洁动作，与「外面太吵」的理由无关。", "洗": "搭配：「洗」不能带「上」表示合拢，「把窗户洗上」不成立。"}, "sentence_index": 0, "correct_answer": "关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈出门时忘了过一道关。", "explanation": "这里的「关」是「关卡」的意思，与「停止运转」无关，不能用于关电视的语境。"}, {"text": "妈妈出门时忘了关一本书。", "explanation": "这里应该用〈合上〉。关多用于开着的设备或门窗，书应说「合上」。"}, {"text": "妈妈累了，关上眼镜睡了一会儿。", "explanation": "这里应该用〈摘下〉。眼镜应说「摘下」，「关上」不能用于眼镜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87575, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：关（guān）指把开着的东西合上或停止运转，与句意相符。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 guān 韵母不同（an/uan），意思是干燥。"}, {"text": "罐", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是罐子。"}, {"text": "管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是管子或管理。"}], "explanations": {"关": "正确：关（guān）指把开着的东西合上或停止运转，与句意相符。", "干": "gān 与 guān 韵母不同（an/uan），意思是干燥。", "罐": "guàn（第四声）与 guān（第一声）声调不同，意思是罐子。", "管": "guǎn（第三声）与 guān（第一声）声调不同，意思是管子或管理。"}, "sentence_index": null, "correct_answer": "关"}, "level_3": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：电脑用完后关机，符合「已经」的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象通常是食物，电脑不能被吃。"}, {"text": "喂", "is_correct": false, "explanation": "配价：喂的对象须是有生命的东西，不能带「电脑」作宾语。"}, {"text": "哄", "is_correct": false, "explanation": "搭配：哄多用于人或小孩，「哄电脑」不是常见搭配。"}], "explanations": {"关": "正确：电脑用完后关机，符合「已经」的语境。", "吃": "语义：吃的对象通常是食物，电脑不能被吃。", "喂": "配价：喂的对象须是有生命的东西，不能带「电脑」作宾语。", "哄": "搭配：哄多用于人或小孩，「哄电脑」不是常见搭配。"}, "sentence_index": 6, "correct_answer": "关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盒牛奶很会关灯。", "explanation": "这里的「关灯」须由人或能操作开关的设备执行，「牛奶」不能作施事。"}, {"text": "请关一下这本小说，我有点冷。", "explanation": "这里应该用〈合上〉。关多用于开着的设备，小说应说「合上」。"}, {"text": "请把我关起来，我有点冷。", "explanation": "这里的「关」是「关押」的意思，与「停止运转」无关，不能用于空调的语境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
