INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87576, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使开着的东西合上；使不开放。", "primary_collocate": null, "pronunciation": "guān", "ipa": "kwan˥", "syllable_count": 1, "sentences": [{"text": "这家店晚上十点关门。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太冷了，请把门关上。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店因为装修关了一个月。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进屋后，轻轻关上门。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆几点关门？", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前一定要关好煤气。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，我去把窗户关了。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园晚上不关门，大家随时可以去。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店关着门，里面没有人。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，商店都关了门。", "target_word": "关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关了", "label": "体标（完成）"}, {"form": "关着", "label": "体标（持续）"}, {"form": "关上", "label": "复合词"}, {"form": "關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关门：把门窗合上，或商店、场所停止开放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：关（guān）指把开着的东西合上，与句意相符。"}, {"text": "管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是管子或管理。"}, {"text": "惯", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。"}, {"text": "光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（ang/an），意思是光线。"}, {"text": "宽", "is_correct": false, "explanation": "kuān 与 guān 声母不同（k/g），意思是宽阔。"}, {"text": "捐", "is_correct": false, "explanation": "juān 与 guān 声母不同（j/g），意思是捐赠。"}], "explanations": {"关": "正确：关（guān）指把开着的东西合上，与句意相符。", "管": "guǎn（第三声）与 guān（第一声）声调不同，意思是管子或管理。", "惯": "guàn（第四声）与 guān（第一声）声调不同，意思是习惯。", "光": "guāng 与 guān 韵母不同（ang/an），意思是光线。", "宽": "kuān 与 guān 声母不同（k/g），意思是宽阔。", "捐": "juān 与 guān 声母不同（j/g），意思是捐赠。"}, "sentence_index": null, "correct_answer": "关"}, "level_3": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：关门指停止营业或把门关上，符合晚上十点的语境。"}, {"text": "砸", "is_correct": false, "explanation": "语义：砸门指猛力敲打，店铺不会在晚上十点这样做。"}, {"text": "撞", "is_correct": false, "explanation": "语义：撞门指冲撞门扉，与店铺正常打烊的情境不符。"}, {"text": "踹", "is_correct": false, "explanation": "语义：踹门是用脚猛踢，与店铺正常打烊不符。"}], "explanations": {"关": "正确：关门指停止营业或把门关上，符合晚上十点的语境。", "砸": "语义：砸门指猛力敲打，店铺不会在晚上十点这样做。", "撞": "语义：撞门指冲撞门扉，与店铺正常打烊的情境不符。", "踹": "语义：踹门是用脚猛踢，与店铺正常打烊不符。"}, "sentence_index": 0, "correct_answer": "关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他进屋后，轻轻关上了灯光。", "explanation": "这里应该用〈关上了灯〉。关的对象是灯、门等，不能说「关上灯光」。"}, {"text": "他听完后不再说话，关上了嘴。", "explanation": "这里应该用〈闭〉。关多用于门窗、开关等，嘴应说「闭上」。"}, {"text": "他拿出包里的东西，关上了拉链。", "explanation": "这里应该用〈拉〉。拉链要说「拉上」，「关」多用于门窗、开关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87576, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：关（guān）指把开着的东西合上，与句意相符。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 guān 韵母不同（an/uan），意思是干燥。"}, {"text": "罐", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是罐子。"}, {"text": "灌", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，意思是灌注。"}], "explanations": {"关": "正确：关（guān）指把开着的东西合上，与句意相符。", "干": "gān 与 guān 韵母不同（an/uan），意思是干燥。", "罐": "guàn（第四声）与 guān（第一声）声调不同，意思是罐子。", "灌": "guàn（第四声）与 guān（第一声）声调不同，意思是灌注。"}, "sentence_index": null, "correct_answer": "关"}, "level_3": {"options": [{"text": "关", "is_correct": true, "explanation": "正确：风大时关窗户是常见的做法，符合语境。"}, {"text": "吹", "is_correct": false, "explanation": "配价：吹的施事应是风，「我」不能吹窗户。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是使物体落地，与「风太大」而去关窗的理由不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱不能带窗户作宾语，「唱窗户」不成立。"}], "explanations": {"关": "正确：风大时关窗户是常见的做法，符合语境。", "吹": "配价：吹的施事应是风，「我」不能吹窗户。", "摔": "语义：摔是使物体落地，与「风太大」而去关窗的理由不符。", "唱": "搭配：唱不能带窗户作宾语，「唱窗户」不成立。"}, "sentence_index": 6, "correct_answer": "关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下班后，商店都关了天。", "explanation": "这里应该用〈门〉。「关」的对象是门窗或场所，「天」不能被关。"}, {"text": "他把钥匙关进了抽屉。", "explanation": "这里应该用〈放〉。关多用于门窗、开关等可以合上的东西，把钥匙放进抽屉要说「放」。"}, {"text": "他关了那本厚厚的小说。", "explanation": "这里应该用〈合上〉。关多用于门窗等开合之物，书应说「合上」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里她把关门了。", "corrected_sentence": "夜里她把门关了。", "error_description": "错误：「把」字句中，宾语「门」应位于动词「关」之前，写成「把关门了」是错误的。正确形式：「把门关了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把门关。", "corrected_sentence": "他把门关上。", "error_description": "错误：「把」字句中，动词「关」后须有补语或「了」「着」等成分，「把门关」语义不完整。正确形式：「把门关上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
