INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心中是人的心里面，是想事情、有感觉的地方。", "primary_collocate": null, "pronunciation": "xīn zhōng", "ipa": "ɕin˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "她心中有很多话，不知道怎么说。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心中一直想着家人。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话一直留在我心中。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心中很清楚，这件事不容易。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，他心中很高兴。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的帮助，我会永远记在心中。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心中有一个小小的梦想。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心中很不安，一晚上没睡好。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的一件事，我至今仍记在心中。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子心中有话，就应该对妈妈说。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "心中：人想事情、有感觉的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心中", "is_correct": true, "explanation": "心中指人的内心，能“有很多话”，与“不知道怎么说”相合。"}, {"text": "门外", "is_correct": false, "explanation": "语义：“门外”是位置，不是人能装话的地方，“她门外有很多话”说不通。"}, {"text": "车里", "is_correct": false, "explanation": "语义：“车里”指车厢内部，“她车里有很多话”说不通。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：“桌上”常与具体东西搭配，不说桌面上有人的话。"}], "explanations": {"心中": "心中指人的内心，能“有很多话”，与“不知道怎么说”相合。", "门外": "语义：“门外”是位置，不是人能装话的地方，“她门外有很多话”说不通。", "车里": "语义：“车里”指车厢内部，“她车里有很多话”说不通。", "桌上": "搭配：“桌上”常与具体东西搭配，不说桌面上有人的话。"}, "sentence_index": 0, "correct_answer": "心中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公园是城市的心中。", "explanation": "这里应该用〈中心〉。心中指人的内心，不指地理位置的中心。"}, {"text": "她的心中很长，该剪一剪了。", "explanation": "这里应该用〈头发〉。心中指内心，不是身体部位，不能说长短。"}, {"text": "我把书包放在心中。", "explanation": "心中指人的内心，不是实际的地点，不能用来放东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心中", "is_correct": true, "explanation": "心中指人的内心，能“有一个小小的梦想”，与句子相合。"}, {"text": "天上", "is_correct": false, "explanation": "语义：“天上”指天空，梦想不在天空里，“他天上有梦想”说不通。"}, {"text": "脚下", "is_correct": false, "explanation": "搭配：“脚下”指脚底的位置，不与“梦想”搭配。"}, {"text": "碗里", "is_correct": false, "explanation": "语义：“碗里”指容器内部，梦想不能装在碗里。"}], "explanations": {"心中": "心中指人的内心，能“有一个小小的梦想”，与句子相合。", "天上": "语义：“天上”指天空，梦想不在天空里，“他天上有梦想”说不通。", "脚下": "搭配：“脚下”指脚底的位置，不与“梦想”搭配。", "碗里": "语义：“碗里”指容器内部，梦想不能装在碗里。"}, "sentence_index": 6, "correct_answer": "心中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为这个项目花了很多心中。", "explanation": "这里应该用〈心血〉。心中指内心，不指付出的精力，不能作“花”的宾语。"}, {"text": "他每天早上在心中刷牙。", "explanation": "心中指内心，刷牙是身体动作，不能在心中进行。"}, {"text": "护士检查了病人的心中。", "explanation": "这里应该用〈内脏〉。心中指内心，不指身体器官，不能用来检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一直把这句话记在心中里。", "corrected_sentence": "我一直把这句话记在心中。", "error_description": "错误：「心中」本身已表示位置（「中」即里面），后面不应再加「里」，「心中里」重复。正确形式：「记在心中」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份恩情我一直记在心中里。", "corrected_sentence": "这份恩情我一直记在心中。", "error_description": "错误：「心中」本身已表示位置（「中」即里面），后面不应再加「里」，「心中里」重复。正确形式：「记在心中」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
