INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内心；心里。", "primary_collocate": null, "pronunciation": "xīn zhōng", "ipa": "ɕin˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "考试以前，我心中有点儿紧张。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人在我心中很重要。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不说话，心中却很难过。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子们笑，我心中很温暖。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把爱藏在心中，从来不说。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心中有点怕，但脸上笑着。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人心中一直想念着远方的儿子。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你，我心中十分感动。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让她心中很不舒服。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心中明白，妈妈是为他好。", "target_word": "心中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "心中：内心，心里的感情和想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心中", "is_correct": true, "explanation": "心中指内心，心里的紧张是内心的感受，与句子相合。"}, {"text": "树下", "is_correct": false, "explanation": "语义：“树下”是地点，紧张是心里的感受，不能处在树下。"}, {"text": "水杯里", "is_correct": false, "explanation": "语义：“水杯里”指容器内部，不能用来指人的心情。"}, {"text": "电视上", "is_correct": false, "explanation": "搭配：“电视上”不能作“紧张”这种心情的处所。"}], "explanations": {"心中": "心中指内心，心里的紧张是内心的感受，与句子相合。", "树下": "语义：“树下”是地点，紧张是心里的感受，不能处在树下。", "水杯里": "语义：“水杯里”指容器内部，不能用来指人的心情。", "电视上": "搭配：“电视上”不能作“紧张”这种心情的处所。"}, "sentence_index": 0, "correct_answer": "心中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把车钥匙放在心中。", "explanation": "心中指人的内心，不是实际的地点，不能用来放东西。"}, {"text": "夏天她的心中容易干。", "explanation": "这里应该用〈皮肤〉。心中指内心，不指身体表面，不能说干燥。"}, {"text": "这块蛋糕的心中是巧克力。", "explanation": "心中指人的内心，不指食物内部，不能用来描述蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心中", "is_correct": true, "explanation": "心中指人的内心，“想念远方的儿子”是内心的感情，与句子相合。"}, {"text": "柜子里", "is_correct": false, "explanation": "语义：“柜子里”指柜子内部，想念不能存放在柜子里。"}, {"text": "窗台上", "is_correct": false, "explanation": "配价：“想念”的主语要是人，“窗台上”不能作主语。"}, {"text": "墙角", "is_correct": false, "explanation": "语义：“墙角”是位置，不能有想念的感情。"}], "explanations": {"心中": "心中指人的内心，“想念远方的儿子”是内心的感情，与句子相合。", "柜子里": "语义：“柜子里”指柜子内部，想念不能存放在柜子里。", "窗台上": "配价：“想念”的主语要是人，“窗台上”不能作主语。", "墙角": "语义：“墙角”是位置，不能有想念的感情。"}, "sentence_index": 6, "correct_answer": "心中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月我的心中增加了三公斤。", "explanation": "这里应该用〈体重〉。心中指内心，不指身体的重量，不能说增加了几公斤。"}, {"text": "他在心中跑了五公里。", "explanation": "心中指内心，跑步是身体运动，不能在心中进行。"}, {"text": "市场的心中很热闹。", "explanation": "这里应该用〈中心〉。心中指内心，不指地点的中心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份友情我会刻在心中里。", "corrected_sentence": "这份友情我会刻在心中。", "error_description": "错误：「心中」本身已表示位置（「中」即里面），后面不应再加「里」，「心中里」重复。正确形式：「刻在心中」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的好意我一直记在心中里。", "corrected_sentence": "他的好意我一直记在心中。", "error_description": "错误：「心中」本身已表示位置（「中」即里面），后面不应再加「里」，「心中里」重复。正确形式：「记在心中」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
