INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87579, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解析是把难懂的东西一点一点讲清楚。", "primary_collocate": null, "pronunciation": "jiě xī", "ipa": "tɕjɛ˨˩˦ ɕi˥", "syllable_count": 2, "sentences": [{"text": "老师把这道难题一点一点解析给我们听。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你给我解析一下这句古文的意思。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话太难了，谁能帮我解析一下？", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上解析了这个句子。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师耐心地解析每一个语法点。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂，你再解析一遍好吗？", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章很难，需要老师来解析。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把游戏规则一条一条解析给弟弟听。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用图片一步一步解析了这种手术的过程。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在给同学解析这道数学题。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解析了", "label": "完成体"}, {"form": "解析过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把难懂的内容逐步讲解清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解析", "is_correct": true, "explanation": "正确：“解析”指把难懂的东西一点一点讲清楚，与“讲给我们听”相符。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”是用假话骗人，与把难题讲清楚的意思相反。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”是藏起来，不能用来讲给别人听。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或错误，不能说“把难题批评给我们听”。"}], "explanations": {"解析": "正确：“解析”指把难懂的东西一点一点讲清楚，与“讲给我们听”相符。", "欺骗": "语义：“欺骗”是用假话骗人，与把难题讲清楚的意思相反。", "隐藏": "语义：“隐藏”是藏起来，不能用来讲给别人听。", "批评": "搭配：“批评”的对象是人或错误，不能说“把难题批评给我们听”。"}, "sentence_index": 0, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把这台旧机器解析开，零件扔了一地。", "explanation": "这里应该用〈拆解〉。解析是把难懂的东西讲清楚，拆开机器要用“拆解”。"}, {"text": "警察解析了被困的人。", "explanation": "这里应该用〈解救〉。解析是讲清道理，把被困的人救出来要用“解救”。"}, {"text": "他把这段话解析成了英文。", "explanation": "这里应该用〈翻译〉。解析是讲清楚意思，不表示把一种语言转换成另一种语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解析", "is_correct": true, "explanation": "正确：“解析”指把难懂的东西讲清楚，与“需要老师来……”相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再坚持，不能表示老师帮忙讲清楚文章。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是美化外观，与讲清楚文章的意思无关。"}, {"text": "眺望", "is_correct": false, "explanation": "配价：“眺望”需要处所宾语（如眺望远方），不能直接以“文章”为对象。"}], "explanations": {"解析": "正确：“解析”指把难懂的东西讲清楚，与“需要老师来……”相符。", "放弃": "语义：“放弃”是不再坚持，不能表示老师帮忙讲清楚文章。", "装饰": "语义：“装饰”是美化外观，与讲清楚文章的意思无关。", "眺望": "配价：“眺望”需要处所宾语（如眺望远方），不能直接以“文章”为对象。"}, "sentence_index": 6, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在课堂上解析了这个学生的书包。", "explanation": "这里应该用〈检查〉。解析是讲清道理，不能用来指检查物品。"}, {"text": "她把耳环解析下来，放进了首饰盒。", "explanation": "这里应该用〈摘下〉。解析是把难懂的东西讲清楚，把耳环摘下来要用“摘下”。"}, {"text": "他解析了鞋带，准备去跑步。", "explanation": "这里应该用〈解开〉。解析是把难懂的东西讲清楚，解开鞋带要用“解开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷把这段古文一句一句解析孙子听。", "corrected_sentence": "爷爷把这段古文一句一句解析给孙子听。", "error_description": "介词漏用：“解析”后引出听的对象“孙子”时要用介词“给”，应说“解析给孙子听”，不能省掉“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这段话解析很清楚。", "corrected_sentence": "他把这段话解析得很清楚。", "error_description": "补语错误：状态补语前要用“得”，应说“解析得很清楚”，不能省掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
