INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "剖析并解释，使之清楚明白。", "primary_collocate": null, "pronunciation": "jiě xī", "ipa": "tɕjɛ˨˩˦ ɕi˥", "syllable_count": 2, "sentences": [{"text": "这位专家解析了经济下降的原因。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一篇文章解析这次比赛。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者详细解析了新政策的内容。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书专门解析中国古代的诗。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师解析了这首诗的写法和意思。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写文章解析这个社会问题。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视节目请专家解析今年的经济形势。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先解析问题，再想办法。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇报告解析了公司失败的原因。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教授从历史背景入手，解析了这个理论的来源。", "target_word": "解析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解析了", "label": "完成体"}, {"form": "解析过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "剖析问题并加以解释，使人明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解析", "is_correct": true, "explanation": "正确：“解析”指剖析并解释，与“这位专家……经济下降的原因”相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”是把东西咽下去，原因不能被吃掉。"}, {"text": "擦掉", "is_correct": false, "explanation": "语义：“擦掉”是抹去痕迹，不能用来指分析原因。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”搭配节目、录音等，不能搭配“原因”。"}], "explanations": {"解析": "正确：“解析”指剖析并解释，与“这位专家……经济下降的原因”相符。", "吃掉": "语义：“吃掉”是把东西咽下去，原因不能被吃掉。", "擦掉": "语义：“擦掉”是抹去痕迹，不能用来指分析原因。", "播放": "搭配：“播放”搭配节目、录音等，不能搭配“原因”。"}, "sentence_index": 0, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生解析了这只青蛙。", "explanation": "这里应该用〈解剖〉。解析用于分析道理或问题，不能指切开动物的身体。"}, {"text": "消防员解析了被困的人。", "explanation": "这里应该用〈解救〉。解析是剖析或讲清道理，把被困的人救出来要用“解救”。"}, {"text": "他解析了被子，准备拿出去晒一晒。", "explanation": "这里应该用〈晾晒〉。解析指剖析或讲清道理，不能用来指晾晒被子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解析", "is_correct": true, "explanation": "正确：“解析”指剖析并解释，与“请专家……今年的经济形势”相符。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”是在材料上刻画，不能用于分析形势。"}, {"text": "聘请", "is_correct": false, "explanation": "配价：“聘请”的宾语应是人，不能直接以“经济形势”为宾语。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”是用乐器表演，与分析经济形势无关。"}], "explanations": {"解析": "正确：“解析”指剖析并解释，与“请专家……今年的经济形势”相符。", "雕刻": "语义：“雕刻”是在材料上刻画，不能用于分析形势。", "聘请": "配价：“聘请”的宾语应是人，不能直接以“经济形势”为宾语。", "演奏": "语义：“演奏”是用乐器表演，与分析经济形势无关。"}, "sentence_index": 6, "correct_answer": "解析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她解析了房间。", "explanation": "这里应该用〈打扫〉。解析的对象是问题、道理或内容，不能指房间。"}, {"text": "工人解析了这些箱子。", "explanation": "这里应该用〈搬运〉。解析用于分析道理，不能指搬动物品。"}, {"text": "他一口气把饭解析完了。", "explanation": "这里应该用〈吃〉。解析是剖析或讲清道理，把饭吃完要用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家正在解析了这次事故的原因。", "corrected_sentence": "专家正在解析这次事故的原因。", "error_description": "时态错误：“正在”表示动作进行中，不能与“了”同用，应说“正在解析”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他解析很清楚。", "corrected_sentence": "他解析得很清楚。", "error_description": "补语错误：状态补语前需要“得”，应说“解析得很清楚”，不能说“解析很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
