INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中国宋明时期的哲学学派，主张心是万物之本，强调“心即理”，代表人物有陆九渊、王阳明。", "primary_collocate": null, "pronunciation": "xīn xué", "ipa": "ɕin˥ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "心学是宋明时期的一个哲学学派。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心学认为心是万物的根本。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陆九渊是心学的重要人物。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王阳明让心学在明代有了很大的影响。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“心即理”是心学最有名的一句话。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和理学不同，心学更重视人的内心。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学的哲学课上，老师讲了宋明的心学。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心学对后来的中国思想影响很深。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文写的是心学和理学的关系。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读宋明历史，你一定会接触到心学。", "target_word": "心学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阳明心学", "label": "复合"}], "register": "书面", "sense_fingerprint": "宋明哲学学派，主张心即理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87582, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心学", "is_correct": true, "explanation": "心学：本词，指宋明时期主张“心即理”的哲学学派。"}, {"text": "心血", "is_correct": false, "explanation": "xuè（第四声）与 xué（第二声）声调不同，心血意思是血液，也比喻费尽的心力。"}, {"text": "新雪", "is_correct": false, "explanation": "xuě（第三声）与 xué（第二声）声调不同，新雪意思是新下的雪。"}, {"text": "兴学", "is_correct": false, "explanation": "xīng 与 xīn 的韵尾不同（ng 与 n），兴学意思是兴办学校。"}, {"text": "新血", "is_correct": false, "explanation": "xuè（第四声）与 xué（第二声）声调不同，新血意思是新鲜的血液，也比喻新生力量。"}], "explanations": {"心学": "心学：本词，指宋明时期主张“心即理”的哲学学派。", "心血": "xuè（第四声）与 xué（第二声）声调不同，心血意思是血液，也比喻费尽的心力。", "新雪": "xuě（第三声）与 xué（第二声）声调不同，新雪意思是新下的雪。", "兴学": "xīng 与 xīn 的韵尾不同（ng 与 n），兴学意思是兴办学校。", "新血": "xuè（第四声）与 xué（第二声）声调不同，新血意思是新鲜的血液，也比喻新生力量。"}, "sentence_index": null, "correct_answer": "心学"}, "level_3": {"options": [{"text": "心学", "is_correct": true, "explanation": "正确：“心学”是宋明时期的哲学学派，与句意相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是哲学学派，句意不通。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是思想流派，“……是宋明时期的一个哲学学派”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“学派”只能指思想流派，不能说“天气是……学派”。"}], "explanations": {"心学": "正确：“心学”是宋明时期的哲学学派，与句意相符。", "数学": "语义：数学是学科，不是哲学学派，句意不通。", "地图": "语义：地图不是思想流派，“……是宋明时期的一个哲学学派”说不通。", "天气": "搭配：“学派”只能指思想流派，不能说“天气是……学派”。"}, "sentence_index": 0, "correct_answer": "心学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的心学，专门研究宋明历史。", "explanation": "这里应该用〈学者〉。心学是学派名称，不能指人，指人要用“学者”。"}, {"text": "他心学很好，每次考试都考第一。", "explanation": "这里应该用〈学习〉。心学是哲学学派名称，不能表示读书的成绩。"}, {"text": "医生说他的心学很健康。", "explanation": "这里应该用〈心脏〉。心学是学问名称，不能用来说人的身体状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心学", "is_correct": true, "explanation": "正确：“宋明的心学”是老师讲授的内容，与哲学课的语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：宋明时代没有冰箱，“讲了宋明的冰箱”与史实矛盾。"}, {"text": "电视", "is_correct": false, "explanation": "语义：宋明时代没有电视，“讲了宋明的电视”不合常理。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“讲了……的”后接的是学问、思想等内容，“手机”不能作讲授的对象。"}], "explanations": {"心学": "正确：“宋明的心学”是老师讲授的内容，与哲学课的语境相符。", "冰箱": "语义：宋明时代没有冰箱，“讲了宋明的冰箱”与史实矛盾。", "电视": "语义：宋明时代没有电视，“讲了宋明的电视”不合常理。", "手机": "搭配：“讲了……的”后接的是学问、思想等内容，“手机”不能作讲授的对象。"}, "sentence_index": 6, "correct_answer": "心学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心学是当一名医生。", "explanation": "这里应该用〈理想〉。心学是学派名称，不能用来指人的志向。"}, {"text": "心学研究人体的疾病和治疗方法。", "explanation": "这里应该用〈医学〉。心学研究的是人如何明辨对错，不研究人体疾病。"}, {"text": "心学讲究笔墨的功夫。", "explanation": "这里应该用〈书法〉。心学是学问，不涉及笔墨技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "陆九渊开创了一条心学，影响很大。", "corrected_sentence": "陆九渊开创了心学，影响很大。", "error_description": "量词错误：“心学”是学派名称，前面不用量词，“一条心学”不对，应直接说“开创了心学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "心学们认为人应该相信自己的良心，这一点很重要。", "corrected_sentence": "心学认为人应该相信自己的良心，这一点很重要。", "error_description": "复数错误：“心学”是学派名称，不能加“们”表示复数。应去掉“们”，说“心学认为……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
