INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "令是让别人有某种感觉或做某件事。", "primary_collocate": null, "pronunciation": "lìng", "ipa": "liŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他的歌声令人感到很温暖。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题令我很难回答。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的决定令员工很不安。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败令他明白了很多道理。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的笑脸令妈妈忘记了累。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息令全家人都很担心。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话令我想起了小时候。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那部电影令观众流下了眼泪。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表现令老师很满意。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好天气令我们决定去爬山。", "target_word": "令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "令人", "label": "复合"}], "register": "书面语", "sense_fingerprint": "让别人产生感觉或去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87583, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "令", "is_correct": true, "explanation": "令（lìng）是动词，意思是让别人有某种感觉或做某事，书面语，本句指“令人感到温暖”。"}, {"text": "岭", "is_correct": false, "explanation": "lǐng（第三声）与 lìng（第四声）声调不同，意思是“山岭”。"}, {"text": "铃", "is_correct": false, "explanation": "líng（第二声）与 lìng 声调不同，意思是“铃铛”。"}, {"text": "宁", "is_correct": false, "explanation": "nìng 与 lìng 声母不同（n 与 l），意思是“宁可”。"}, {"text": "利", "is_correct": false, "explanation": "lì 比 lìng 少了韵尾 -ng，意思是“利益、锋利”。"}, {"text": "历", "is_correct": false, "explanation": "lì 比 lìng 少了韵尾 -ng，意思是“历史、经历”。"}], "explanations": {"令": "令（lìng）是动词，意思是让别人有某种感觉或做某事，书面语，本句指“令人感到温暖”。", "岭": "lǐng（第三声）与 lìng（第四声）声调不同，意思是“山岭”。", "铃": "líng（第二声）与 lìng 声调不同，意思是“铃铛”。", "宁": "nìng 与 lìng 声母不同（n 与 l），意思是“宁可”。", "利": "lì 比 lìng 少了韵尾 -ng，意思是“利益、锋利”。", "历": "lì 比 lìng 少了韵尾 -ng，意思是“历史、经历”。"}, "sentence_index": null, "correct_answer": "令"}, "level_3": {"options": [{"text": "令", "is_correct": true, "explanation": "“令”表示使人产生某种感觉，“令人感到很温暖”符合本句。"}, {"text": "伤", "is_correct": false, "explanation": "语义：“伤”表示伤害，不能使人感到温暖。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”不能带“人”作宾语，“感到人感到很温暖”不成立。"}, {"text": "听", "is_correct": false, "explanation": "语义：“听”的主语应是人，“歌声听人”不成立。"}], "explanations": {"令": "“令”表示使人产生某种感觉，“令人感到很温暖”符合本句。", "伤": "语义：“伤”表示伤害，不能使人感到温暖。", "感到": "配价：“感到”不能带“人”作宾语，“感到人感到很温暖”不成立。", "听": "语义：“听”的主语应是人，“歌声听人”不成立。"}, "sentence_index": 0, "correct_answer": "令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上级下了一道令，要大家马上撤离。", "explanation": "“令”在这里是名词，指上级发布的命令，与本词作动词“让别人有某种感觉或做某件事”不同。"}, {"text": "他曾做过一个县的县令。", "explanation": "“县令”中的“令”指古代县的长官，是名词，与本词的动词义不同。"}, {"text": "书店里有一令白纸。", "explanation": "“令”在这里是量词，指五百张纸，与本词的动词义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87583, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "令", "is_correct": true, "explanation": "令（lìng）是动词，意思是让别人有某种感觉或做某事，书面语，本句指“令我想起了小时候”。"}, {"text": "领", "is_correct": false, "explanation": "lǐng（第三声）与 lìng（第四声）声调不同，意思是“领导、带领”。"}, {"text": "灵", "is_correct": false, "explanation": "líng（第二声）与 lìng 声调不同，意思是“灵活、灵验”。"}, {"text": "浪", "is_correct": false, "explanation": "làng 与 lìng 韵母不同（ang 与 ing），意思是“波浪”。"}, {"text": "立", "is_correct": false, "explanation": "lì 比 lìng 少了韵尾 -ng，意思是“站立”。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 lìng 声调不同，意思是“零”。"}], "explanations": {"令": "令（lìng）是动词，意思是让别人有某种感觉或做某事，书面语，本句指“令我想起了小时候”。", "领": "lǐng（第三声）与 lìng（第四声）声调不同，意思是“领导、带领”。", "灵": "líng（第二声）与 lìng 声调不同，意思是“灵活、灵验”。", "浪": "làng 与 lìng 韵母不同（ang 与 ing），意思是“波浪”。", "立": "lì 比 lìng 少了韵尾 -ng，意思是“站立”。", "零": "líng（第二声）与 lìng 声调不同，意思是“零”。"}, "sentence_index": null, "correct_answer": "令"}, "level_3": {"options": [{"text": "令", "is_correct": true, "explanation": "“令”表示使人产生某种感受或想法，“令我想起了小时候”符合本句。"}, {"text": "使用", "is_correct": false, "explanation": "语义：“使用”指用某种物品，不能表示让人想起往事。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”后面接名词宾语，不能接“我想起了小时候”这样的小句。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”指用手臂环住，与“想起”不相容。"}], "explanations": {"令": "“令”表示使人产生某种感受或想法，“令我想起了小时候”符合本句。", "使用": "语义：“使用”指用某种物品，不能表示让人想起往事。", "拥有": "配价：“拥有”后面接名词宾语，不能接“我想起了小时候”这样的小句。", "抱": "语义：“抱”指用手臂环住，与“想起”不相容。"}, "sentence_index": 6, "correct_answer": "令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "令尊身体还好吗？", "explanation": "这里“令”是敬称，用于称呼对方的父亲（令尊），与本词作动词“让别人有某种感觉或做某件事”的意思不同。"}, {"text": "我见过他的令堂。", "explanation": "这里“令”是敬称，用于称呼别人的母亲（令堂），与本词作动词的意思不同。"}, {"text": "听说令爱今年考上了大学。", "explanation": "这里“令”是敬称，用于称呼对方的女儿（令爱），与本词作动词的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场音乐会令很激动。", "corrected_sentence": "这场音乐会令观众很激动。", "error_description": "漏掉兼语：“令”是使令动词，后面须带出被使令的人，“令很激动”缺少对象，应补上“观众”，正确说法是“令观众很激动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张照片令着他想起了童年。", "corrected_sentence": "那张照片令他想起了童年。", "error_description": "错误在“令”后面加了“着”。“着”表示持续的状态，与“令”的使令用法不符，正确说法是“令他想起了童年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "正确。“忘记”与“想起”（忽然记起）意义相反。"}, {"text": "打开", "is_correct": false, "explanation": "“打开”是动词，但与记忆无关，也不与“想起”构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是动词，指走走，与“想起”的记忆义无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”是动词，指清洗身体，与“想起”没有反义关系。"}], "correct_answer": "忘记", "explanations": {"忘记": "正确。“忘记”与“想起”（忽然记起）意义相反。", "打开": "“打开”是动词，但与记忆无关，也不与“想起”构成反义。", "散步": "“散步”是动词，指走走，与“想起”的记忆义无关。", "洗澡": "“洗澡”是动词，指清洗身体，与“想起”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "正确。“忘记”与“想起”（忽然记起）意义相反。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是动词，指快速移动，与“想起”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”是动词，指进食，与记忆无关，也不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是动词，指发声唱曲，与“想起”没有反义关系。"}], "correct_answer": "忘记", "explanations": {"忘记": "正确。“忘记”与“想起”（忽然记起）意义相反。", "跑步": "“跑步”是动词，指快速移动，与“想起”没有反义关系。", "吃饭": "“吃饭”是动词，指进食，与记忆无关，也不构成反义。", "唱歌": "“唱歌”是动词，指发声唱曲，与“想起”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想起是以前的事忽然出现在脑子里。", "primary_collocate": null, "pronunciation": "xiǎng qǐ", "ipa": "ɕjɑŋ˨˩ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "走到门口，我忽然想起忘带钱包了。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他突然想起今天是妈妈的生日。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚想起明天还要考试。", "target_word": "想起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡觉前，她忽然想起没关灯。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到雪，我想起了老家的冬天。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时他想起一件重要的事。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忽然想起，昨天答应了朋友。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了商店，妈妈才想起没带手机。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她突然想起了那个夏天。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上我想起忘了锁门。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "想起了", "label": "体标"}, {"form": "想起过", "label": "体标"}, {"form": "想不起", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "以前的事忽然浮现在脑海里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想起", "is_correct": true, "explanation": "正确答案。“想起”（xiǎng qǐ）指以前的事忽然浮现在脑海里。"}, {"text": "香气", "is_correct": false, "explanation": "xiāng qì 与 xiǎng qǐ 声母韵母相同，声调不同，意思是好闻的气味。"}, {"text": "想骑", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是想骑某物。"}, {"text": "讲起", "is_correct": false, "explanation": "jiǎng 与 xiǎng 声母不同（j 与 x），讲起意思是说起、谈起。"}], "explanations": {"想起": "正确答案。“想起”（xiǎng qǐ）指以前的事忽然浮现在脑海里。", "香气": "xiāng qì 与 xiǎng qǐ 声母韵母相同，声调不同，意思是好闻的气味。", "想骑": "qí（第二声）与 qǐ（第三声）声调不同，意思是想骑某物。", "讲起": "jiǎng 与 xiǎng 声母不同（j 与 x），讲起意思是说起、谈起。"}, "sentence_index": null, "correct_answer": "想起"}, "level_3": {"options": [{"text": "想起", "is_correct": true, "explanation": "正确。“想起”表示忽然想到“忘带钱包了”这件事，与句意相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能接“忘带钱包了”这样的小句。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能表示察觉或浮现，不接这类小句。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”表示烹饪，与“忘带钱包”的察觉无关。"}], "explanations": {"想起": "正确。“想起”表示忽然想到“忘带钱包了”这件事，与句意相符。", "洗": "搭配：“洗”不能接“忘带钱包了”这样的小句。", "吃": "语义：“吃”不能表示察觉或浮现，不接这类小句。", "煮": "语义：“煮”表示烹饪，与“忘带钱包”的察觉无关。"}, "sentence_index": 0, "correct_answer": "想起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她突然想起了一个从没见过的人。", "explanation": "这里应该用〈想象〉。“想起”指以前见过或经历过的事忽然浮现，从没见过的人不能被想起，应说“想象”。"}, {"text": "那张桌子突然想起了他的童年。", "explanation": "这里应该用〈使…想起〉。“想起”的主语必须是能回忆往事的人，桌子不能回忆；应说“那张桌子使他想起了童年”。"}, {"text": "她很想起远方的父母。", "explanation": "这里应该用〈想念〉。“想起”指以前的事忽然浮现在脑海里，思念远方的亲人要用“想念”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想起", "is_correct": true, "explanation": "正确。“想起”表示忽然记起“昨天答应了朋友”，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能表示忽然察觉或记起以前的事。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”与“答应了朋友”的记起无关，不能表示想到。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”不能接“答应了朋友”这样的小句。"}], "explanations": {"想起": "正确。“想起”表示忽然记起“昨天答应了朋友”，与句意相符。", "唱": "语义：“唱”不能表示忽然察觉或记起以前的事。", "跑": "语义：“跑”与“答应了朋友”的记起无关，不能表示想到。", "切": "搭配：“切”不能接“答应了朋友”这样的小句。"}, "sentence_index": 6, "correct_answer": "想起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很想起妈妈，每天都打电话。", "explanation": "这里应该用〈想念〉。“想起”指记起，表示思念亲人要用“想念”。"}, {"text": "我很想起远方的朋友，经常写信。", "explanation": "这里应该用〈惦记〉。“想起”指记起，不指惦记远方的人。"}, {"text": "我突然想起了一个从没去过的地方。", "explanation": "这里应该用〈想象〉。“想起”指以前经历过的事忽然浮现，从没去过的地方不能被想起，应说“想象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一看到照片，就想起着童年。", "corrected_sentence": "我一看到照片，就想起了童年。", "error_description": "体标错误：“想起”后表示完成的体标应为“了”，正确为“想起了童年”；“着”表示持续，不能用在“想起”之后，“想起着童年”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我怎么也想起不他的电话号码了。", "corrected_sentence": "我怎么也想不起他的电话号码了。", "error_description": "可能补语的正确语序是“想不起”，否定词“不”放在“想”和“起”之间；“想起不”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
