INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "记起；回忆起。", "primary_collocate": null, "pronunciation": "xiǎng qǐ", "ipa": "ɕjɑŋ˨˩ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "我想起了他的名字。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这张照片，我想起了小时候。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想起那个人是谁了吗？", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想起了老师说过的话。", "target_word": "想起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我终于想起了钥匙放在哪儿。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这首歌，他想起了大学生活。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想起昨天会议的内容了吗？", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想起了那家饭馆的名字。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一时想起了很多事。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等我想起他当时说了什么，就告诉你。", "target_word": "想起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "想起了", "label": "体标"}, {"form": "想起过", "label": "体标"}, {"form": "想不起", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "回忆起某人、某事或某个名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想起", "is_correct": true, "explanation": "正确答案。“想起”（xiǎng qǐ）指记起、回忆起。"}, {"text": "香气", "is_correct": false, "explanation": "xiāng qì 与 xiǎng qǐ 声母韵母相同，声调不同，意思是好闻的气味。"}, {"text": "想骑", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是想骑某物。"}, {"text": "讲起", "is_correct": false, "explanation": "jiǎng 与 xiǎng 声母不同（j 与 x），讲起意思是说起、谈起。"}], "explanations": {"想起": "正确答案。“想起”（xiǎng qǐ）指记起、回忆起。", "香气": "xiāng qì 与 xiǎng qǐ 声母韵母相同，声调不同，意思是好闻的气味。", "想骑": "qí（第二声）与 qǐ（第三声）声调不同，意思是想骑某物。", "讲起": "jiǎng 与 xiǎng 声母不同（j 与 x），讲起意思是说起、谈起。"}, "sentence_index": null, "correct_answer": "想起"}, "level_3": {"options": [{"text": "想起", "is_correct": true, "explanation": "正确。“想起”表示回忆起“他的名字”，与句意相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”多接衣物、身体，不与“名字”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能煮名字。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”多接食物、物体，不与“名字”搭配。"}], "explanations": {"想起": "正确。“想起”表示回忆起“他的名字”，与句意相符。", "洗": "搭配：“洗”多接衣物、身体，不与“名字”搭配。", "煮": "语义：“煮”的对象是食物，不能煮名字。", "切": "搭配：“切”多接食物、物体，不与“名字”搭配。"}, "sentence_index": 0, "correct_answer": "想起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想起了从没见过的大海的颜色。", "explanation": "这里应该用〈想象〉。“想起”指回忆曾经见过或经历过的事，从没见过的大海颜色不能被想起，应说“想象”。"}, {"text": "我很想起妈妈。", "explanation": "这里应该用〈想念〉。“想起”指记起，表示思念亲人要用“想念”。"}, {"text": "我想起了一个从没听过的声音。", "explanation": "这里应该用〈想象〉。“想起”指回忆曾经听过或经历过的事，没听过的声音不能被想起，应说“想象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想起", "is_correct": true, "explanation": "正确。“想起”表示回忆起“昨天会议的内容”，与句意相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”多接具体物体，“会议内容”不能搬。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是具体的东西，不能咬“内容”。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”多接衣物，不能穿“内容”。"}], "explanations": {"想起": "正确。“想起”表示回忆起“昨天会议的内容”，与句意相符。", "搬": "搭配：“搬”多接具体物体，“会议内容”不能搬。", "咬": "语义：“咬”的对象是具体的东西，不能咬“内容”。", "穿": "语义：“穿”多接衣物，不能穿“内容”。"}, "sentence_index": 6, "correct_answer": "想起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请想起这个电话号码，别忘了。", "explanation": "这里应该用〈记住〉。“想起”指回忆已经知道的事，要求对方记下新信息应说“记住”。"}, {"text": "我很想起远方的朋友。", "explanation": "这里应该用〈惦记〉。“想起”指记起，不指惦记远方的人。"}, {"text": "这本书想起了他的童年。", "explanation": "这里应该用〈使…想起〉。“想起”的主语必须是能回忆往事的人，书不能回忆；应说“这本书使他想起了童年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我怎么也想起不那个人的名字了。", "corrected_sentence": "我怎么也想不起那个人的名字了。", "error_description": "可能补语的正确语序是“想不起”，否定词“不”放在“想”和“起”之间；“想起不”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一下子想起着那个电话号码。", "corrected_sentence": "我一下子想起了那个电话号码。", "error_description": "体标错误：“想起”后表示完成的体标应为“了”，正确为“想起了”；“着”表示持续，不能用在“想起”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
