INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87587, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87587, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解体是一个整体散开，变成一块一块的。", "primary_collocate": null, "pronunciation": "jiě tǐ", "ipa": "tɕjɛ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "老船在大海里解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在空中解体，碎片掉了一地。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座旧桥被大水冲得解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那艘纸船在水里很快就解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆旧车开了二十年，快要解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭进入大气层后解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木桌太旧了，一搬就解体。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子堆成的城堡被海浪打得解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧房子在地震中完全解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条船撞上石头后，很快就解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解体了", "label": "体标"}, {"form": "解体过", "label": "体标"}], "register": "中性", "sense_fingerprint": "整体散开，碎成一块一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：船不会唱歌，“老船在大海里唱歌了”与句意不合。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：船不会发芽，“发芽”只用于植物，与句子的主语不合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”需要有生命的主语，老船不能吃，不符合句中的搭配。"}, {"text": "解体", "is_correct": true, "explanation": "正确：解体表示整体散开、碎成一块一块，老船在大海里散成碎块，符合句意。"}], "explanations": {"唱歌": "语义：船不会唱歌，“老船在大海里唱歌了”与句意不合。", "发芽": "语义：船不会发芽，“发芽”只用于植物，与句子的主语不合。", "吃": "搭配：“吃”需要有生命的主语，老船不能吃，不符合句中的搭配。", "解体": "正确：解体表示整体散开、碎成一块一块，老船在大海里散成碎块，符合句意。"}, "sentence_index": 0, "correct_answer": "解体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病情终于解体了。", "explanation": "这里应该用〈好转〉。病情转好要用好转；解体指整体散成碎块，不用于病情。"}, {"text": "他们决定解体这份合同。", "explanation": "这里应该用〈解除〉。合同、协议终止要用解除；解体指整体散成碎块，不能用于合同。"}, {"text": "他的伤口慢慢解体了。", "explanation": "这里应该用〈愈合〉。伤口慢慢长好要用愈合；解体指整体散成碎块，伤口不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：木桌不会出生，“木桌太旧了，一搬就出生”与句意不合。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”的主语应是人或动物，木桌不能生病。"}, {"text": "开花", "is_correct": false, "explanation": "语义：木桌不会开花，“开花”只用于植物，与句子的主语不合。"}, {"text": "解体", "is_correct": true, "explanation": "正确：解体表示木桌一搬就散成碎块，符合“木桌太旧了，一搬就……”的语境。"}], "explanations": {"出生": "语义：木桌不会出生，“木桌太旧了，一搬就出生”与句意不合。", "生病": "搭配：“生病”的主语应是人或动物，木桌不能生病。", "开花": "语义：木桌不会开花，“开花”只用于植物，与句子的主语不合。", "解体": "正确：解体表示木桌一搬就散成碎块，符合“木桌太旧了，一搬就……”的语境。"}, "sentence_index": 6, "correct_answer": "解体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水在通电后解体成了氢和氧。", "explanation": "这里应该用〈分解〉。化学物质分成几种成分要用分解；解体指整体散成碎块，不用于化学分解。"}, {"text": "他终于解体了这个难题。", "explanation": "这里应该用〈解决〉。难题的解答要用解决；解体指整体散成碎块，不用于难题。"}, {"text": "她听到噩耗后解体了。", "explanation": "这里应该用〈崩溃〉。人的情绪或精神垮掉要用崩溃；解体指物体或组织整体散成碎块，不用于人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那艘旧船昨天在海上正在解体了。", "corrected_sentence": "那艘旧船昨天在海上解体了。", "error_description": "体标错误：“正在”表示动作进行中，“了”表示已经完成，两者不能同时用在“解体”上；说过去已完成的事应删去“正在”，说“解体了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座旧桥在洪水中解体了它。", "corrected_sentence": "那座旧桥在洪水中解体了。", "error_description": "宾语错误：“那座旧桥”既是主语，又被“它”重复指代作宾语；“解体”在此指桥自行散开，主语已是解体的对象，再加宾语多余且不通。正确说法是“那座旧桥在洪水中解体了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
