INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "整体分裂、瓦解；也指把机器拆开。", "primary_collocate": null, "pronunciation": "jiě tǐ", "ipa": "tɕjɛ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "那个大公司因为欠钱太多解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家在三十年前解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内部不团结，球队很快就解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修理工把旧机器解体，检查里面的零件。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的乐队解体后，各自去了别的城市。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把旧飞机解体，再把零件卖掉。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家庭因为吵架差点解体。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在解体那台坏掉的发动机。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个王朝因为内乱解体了。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年前，这个组织已经解体过一次。", "target_word": "解体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解体了", "label": "体标"}, {"form": "解体过", "label": "体标"}], "register": "中性", "sense_fingerprint": "组织或整体分裂瓦解，也指拆开机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开业", "is_correct": false, "explanation": "语义：欠钱太多的公司不会开业，“因为欠钱太多开业了”说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：公司不能结婚，与句子的主语不合。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”的主语应是人，公司不能出差，“那个大公司出差了”搭配不当。"}, {"text": "解体", "is_correct": true, "explanation": "正确：解体表示组织或整体分裂瓦解，符合“因为欠钱太多……了”的句意。"}], "explanations": {"开业": "语义：欠钱太多的公司不会开业，“因为欠钱太多开业了”说不通。", "结婚": "语义：公司不能结婚，与句子的主语不合。", "出差": "搭配：“出差”的主语应是人，公司不能出差，“那个大公司出差了”搭配不当。", "解体": "正确：解体表示组织或整体分裂瓦解，符合“因为欠钱太多……了”的句意。"}, "sentence_index": 0, "correct_answer": "解体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的情绪慢慢解体了。", "explanation": "这里应该用〈崩溃〉。情绪垮掉要用崩溃；解体指组织瓦解或机器拆开，不用于人的情绪。"}, {"text": "他的伤口慢慢解体了。", "explanation": "这里应该用〈愈合〉。伤口长好要用愈合；解体指组织或机器分裂，不能用于伤口。"}, {"text": "糖放进水里后解体了。", "explanation": "这里应该用〈溶解〉。固体溶进液体要用溶解；解体指组织分裂或机器拆开，不用于溶化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业", "is_correct": false, "explanation": "语义：家庭不能毕业，“这个家庭因为吵架差点毕业”与句意不合。"}, {"text": "入学", "is_correct": false, "explanation": "语义：家庭不能入学，与“因为吵架”的语境不合。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：退休的主语是人，“家庭退休”搭配不当。"}, {"text": "解体", "is_correct": true, "explanation": "正确：解体表示家庭因吵架而分裂，符合句意。"}], "explanations": {"毕业": "语义：家庭不能毕业，“这个家庭因为吵架差点毕业”与句意不合。", "入学": "语义：家庭不能入学，与“因为吵架”的语境不合。", "退休": "搭配：退休的主语是人，“家庭退休”搭配不当。", "解体": "正确：解体表示家庭因吵架而分裂，符合句意。"}, "sentence_index": 6, "correct_answer": "解体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演出结束后，大家解体了。", "explanation": "这里应该用〈解散〉。人群或演出后的人员散开要用解散；解体指组织瓦解或机器拆开，不用于人群散开。"}, {"text": "她听到消息后解体了。", "explanation": "这里应该用〈崩溃〉。人的情绪垮掉要用崩溃；解体不用于人的情绪。"}, {"text": "雾在太阳出来后很快解体了。", "explanation": "这里应该用〈消散〉。雾、烟等散去要用消散；解体指组织瓦解或机器拆开，不用于雾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把这台旧机器了解体，检查零件。", "corrected_sentence": "工人把这台旧机器解体，检查零件。", "error_description": "了的位置错误：“了”不能放在“把”字句中动词“解体”之前，这里不需要“了”，应删去，正确形式是“把这台旧机器解体，检查零件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把那台发动机解体很彻底。", "corrected_sentence": "工人把那台发动机解体得很彻底。", "error_description": "补语错误：“解体”后要用“得”引出补语“很彻底”，应说“解体得很彻底”，漏掉“得”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
