INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87589, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心意是你对别人的好心和喜欢。", "primary_collocate": null, "pronunciation": "xīn yì", "ipa": "ɕin˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这是我的一点心意，请你收下。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你的心意，但这份礼物我不能收。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友生病了，我买了水果表示心意。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "礼物不贵，重要的是一份心意。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈很感动，因为这是孩子的一片心意。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然只是一张小卡片，却让我感到朋友的心意。", "target_word": "心意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师收下了学生们的心意。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年回家，他给父母带了礼物，也表达了心意。", "target_word": "心意", "complexity_tier": "T3", "furigana": "guò nián huí jiā, tā gěi fù mǔ dài le lǐ wù, yě biǎo dá le xīn yì.", "sentence_source": "generated"}, {"text": "他每年都寄一点钱，表达对老人的心意。", "target_word": "心意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这束花代表着全班同学的心意。", "target_word": "心意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份心意", "label": "量词"}, {"form": "一片心意", "label": "量词"}], "register": "中性", "sense_fingerprint": "送礼或帮助时表达的好心与情意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心意", "is_correct": true, "explanation": "正确。“心意”指对别人的好心和情意，送礼时可以说“一点心意”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不是东西，不能送给别人，也不能收下。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不能被收下，也不能当作礼物。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“收下”后面要接可以送的东西，不能接“影子”。"}], "explanations": {"心意": "正确。“心意”指对别人的好心和情意，送礼时可以说“一点心意”。", "脾气": "语义：脾气不是东西，不能送给别人，也不能收下。", "体温": "语义：体温不能被收下，也不能当作礼物。", "影子": "搭配：“收下”后面要接可以送的东西，不能接“影子”。"}, "sentence_index": 0, "correct_answer": "心意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有心意承受能力，什么事都不怕。", "explanation": "这里应该用〈心理〉。“心意”指对人的好心和情意，不指心理状态，“心理承受能力”才是正确说法。"}, {"text": "她的心意很细，什么事都想得很周到。", "explanation": "这里应该用〈心思〉。“心意”指对人的好心和情意，不指考虑事情是否细致。"}, {"text": "他的心意很宽，从不计较小事。", "explanation": "这里应该用〈心胸〉。“心意”指对人的好心和情意，不指胸怀、气量，说胸怀宽广要用〈心胸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心意", "is_correct": true, "explanation": "正确。“心意”指学生对老师的好心和情意，“收下”的是老师接受的情意。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：灰尘不是情意，不能被收下。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是声音，不能被收下。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“收下”可以接礼物或情意，不能接“气味”。"}], "explanations": {"心意": "正确。“心意”指学生对老师的好心和情意，“收下”的是老师接受的情意。", "灰尘": "语义：灰尘不是情意，不能被收下。", "嗓音": "语义：嗓音是声音，不能被收下。", "气味": "搭配：“收下”可以接礼物或情意，不能接“气味”。"}, "sentence_index": 6, "correct_answer": "心意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心意跳得很快，医生让他休息。", "explanation": "这里应该用〈心脏〉。“心意”指好心和情意，不指身体器官，也不能“跳”。"}, {"text": "他的心意很积极，遇到困难也不放弃。", "explanation": "这里应该用〈心态〉。“心意”指好心或情意，不指对待事情的态度。"}, {"text": "这个人心意很坏，常常骗别人。", "explanation": "这里应该用〈心肠〉。“心意”指送礼或帮助时的好心和情意，不指一个人的品性好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本小小的心意，请您收下。", "corrected_sentence": "这是一份小小的心意，请您收下。", "error_description": "错误：“一本小小的心意”；正确：“一份小小的心意”。“本”用于书籍，心意应用“份”（或“片”）计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一座心意送给了老师。", "corrected_sentence": "他把一片心意送给了老师。", "error_description": "错误：“一座心意”；正确：“一片心意”。“座”用于山、房屋等大件，心意应用“份”（或“片”）计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对别人的情意、心思或想法。", "primary_collocate": null, "pronunciation": "xīn yì", "ipa": "ɕin˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我明白你的心意，可是我还没准备好。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直不知道他的心意。", "target_word": "心意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把自己的心意写在了信里。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你到底是什么心意，请直接告诉我。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着她，想说出自己的心意。", "target_word": "心意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐很了解妈妈的心意。", "target_word": "心意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不想辜负她的心意。", "target_word": "心意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的心意很清楚，他想和你做朋友。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我猜不透她的心意。", "target_word": "心意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这首歌唱出了他对家人的心意。", "target_word": "心意", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份心意", "label": "量词"}, {"form": "一片心意", "label": "量词"}], "register": "中性", "sense_fingerprint": "对某人心里的情意、想法或打算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心意", "is_correct": true, "explanation": "正确。“心意”指对某人心里的情意或想法，“明白”的是对方的想法和感情。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是想法，也不是感情，不能被明白。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“明白”的对象多为想法或感情，不搭配“颜色”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不属于内心，不能被明白。"}], "explanations": {"心意": "正确。“心意”指对某人心里的情意或想法，“明白”的是对方的想法和感情。", "影子": "语义：影子不是想法，也不是感情，不能被明白。", "颜色": "搭配：“明白”的对象多为想法或感情，不搭配“颜色”。", "体重": "语义：体重是身体的数值，不属于内心，不能被明白。"}, "sentence_index": 0, "correct_answer": "心意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心意跳得很快，有点紧张。", "explanation": "这里应该用〈心脏〉。“心意”指情意或想法，不指身体器官，也不能用来形容跳动。"}, {"text": "这篇文章的心意很难懂。", "explanation": "这里应该用〈意思〉。“心意”指对人的情意或想法，不指文章、话语表达的内容。"}, {"text": "他做这份工作的心意是多赚钱。", "explanation": "这里应该用〈目的〉。“心意”指对人的情意或想法，不指做事要达到的目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心意", "is_correct": true, "explanation": "正确。“心意”指对某人心里的情意，“辜负”的是别人的情意。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位不是情意，不能被辜负。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是资料，不能被辜负。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“辜负”要接情意或期望，不搭配“闹钟”。"}], "explanations": {"心意": "正确。“心意”指对某人心里的情意，“辜负”的是别人的情意。", "座位": "语义：座位不是情意，不能被辜负。", "地图": "语义：地图是资料，不能被辜负。", "闹钟": "搭配：“辜负”要接情意或期望，不搭配“闹钟”。"}, "sentence_index": 6, "correct_answer": "心意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这就是他迟到的心意。", "explanation": "这里应该用〈理由〉。“心意”指对人的情意或打算，不指解释原因的理由。"}, {"text": "这件事的心意很重大。", "explanation": "这里应该用〈意义〉。“心意”指情意或打算，不指事情的价值或重要性。"}, {"text": "他的心意很健康，从不轻易焦虑。", "explanation": "这里应该用〈心理〉。“心意”指对人的情意或想法，不指心理状态，说心理健康要用〈心理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对我有一条心意，我却一直没察觉。", "corrected_sentence": "她对我有一份心意，我却一直没察觉。", "error_description": "错误：“一条心意”；正确：“一份心意”。“条”用于细长的东西，心意应用“份”（或“片”）计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一条心意写进了信里。", "corrected_sentence": "她把一份心意写进了信里。", "error_description": "错误：“一条心意”；正确：“一份心意”。“条”用于细长的东西，心意应用“份”（或“片”）计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
