INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87591, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利益是对一个人有好处的东西。", "primary_collocate": null, "pronunciation": "lì yì", "ipa": "li˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他只关心自己的利益。", "target_word": "利益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了自己的利益，他说了谎。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事对你的利益没有影响。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不会为了利益出卖朋友。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不愿意为了别人放弃自己的利益。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事总是先想自己的利益。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱关系到我的利益，我要问清楚。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间不要只看利益。", "target_word": "利益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了孩子的利益，妈妈换了工作。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了眼前的利益放弃了长远的计划。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个人利益", "label": "复合"}, {"form": "眼前利益", "label": "复合"}, {"form": "长远利益", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人得到的好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87591, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：利益（lì yì），指个人得到的好处。"}, {"text": "技艺", "is_correct": false, "explanation": "j 与 l 声母不同，意思是技术和本领。"}, {"text": "礼仪", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）、yí（第二声）与 yì（第四声）声调不同，意思是礼节和仪式。"}, {"text": "异议", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母 y 与 l），意思是不同的意见。"}], "explanations": {"利益": "正确答案：利益（lì yì），指个人得到的好处。", "技艺": "j 与 l 声母不同，意思是技术和本领。", "礼仪": "lǐ（第三声）与 lì（第四声）、yí（第二声）与 yì（第四声）声调不同，意思是礼节和仪式。", "异议": "yì 与 lì 声母不同（零声母 y 与 l），意思是不同的意见。"}, "sentence_index": null, "correct_answer": "利益"}, "level_3": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：「只关心自己的利益」指只关心自己的好处。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以被关心的好处，「关心自己的天气」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不指好处，与「只关心自己的」之后的搭配不合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「关心」一般不与「脾气」搭配，「关心自己的脾气」不自然。"}], "explanations": {"利益": "正确答案：「只关心自己的利益」指只关心自己的好处。", "天气": "语义：「天气」不是可以被关心的好处，「关心自己的天气」说不通。", "颜色": "语义：「颜色」不指好处，与「只关心自己的」之后的搭配不合。", "脾气": "搭配：「关心」一般不与「脾气」搭配，「关心自己的脾气」不自然。"}, "sentence_index": 0, "correct_answer": "利益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的利益很开朗。", "explanation": "这里应该用〈性格〉。形容人的性格要用「性格」，「利益」指好处，不能用来形容性格。"}, {"text": "今天的利益很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。「利益」指好处，不能用来说晴天雨天。"}, {"text": "他的利益长到一米八了。", "explanation": "这里应该用〈身高〉。「利益」是抽象的好处，不能用来说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87591, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：利益（lì yì），指个人得到的好处。"}, {"text": "离异", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是夫妻离婚。"}, {"text": "日益", "is_correct": false, "explanation": "rì 与 lì 声母不同（r 与 l），意思是一天比一天。"}, {"text": "意义", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母 y 与 l），意思是价值或含义。"}], "explanations": {"利益": "正确答案：利益（lì yì），指个人得到的好处。", "离异": "lí（第二声）与 lì（第四声）声调不同，意思是夫妻离婚。", "日益": "rì 与 lì 声母不同（r 与 l），意思是一天比一天。", "意义": "yì 与 lì 声母不同（零声母 y 与 l），意思是价值或含义。"}, "sentence_index": null, "correct_answer": "利益"}, "level_3": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：「关系到我的利益」指这笔钱对我有得失。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」与钱的得失无关，「关系到我的脚步」说不通。"}, {"text": "手指", "is_correct": false, "explanation": "语义：「手指」不是钱能关系到的对象，句子讲的是得失。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：「关系到」一般接得失、安危等，「方向」不能这样搭配。"}], "explanations": {"利益": "正确答案：「关系到我的利益」指这笔钱对我有得失。", "脚步": "语义：「脚步」与钱的得失无关，「关系到我的脚步」说不通。", "手指": "语义：「手指」不是钱能关系到的对象，句子讲的是得失。", "方向": "搭配：「关系到」一般接得失、安危等，「方向」不能这样搭配。"}, "sentence_index": 6, "correct_answer": "利益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个月的利益吃了两碗饭。", "explanation": "这里应该用〈饭量〉。「利益」是抽象的好处，不能用来说吃饭的份量。"}, {"text": "这道菜的利益又酸又甜。", "explanation": "这里应该用〈味道〉。「利益」指好处，不能用来说食物的味道。"}, {"text": "他每天的利益是一百元。", "explanation": "这里应该用〈工资〉。每天的劳动报酬称为工资，「利益」指好处，不指报酬数额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同只考虑了他自己的一只利益。", "corrected_sentence": "这份合同只考虑了他自己的利益。", "error_description": "量词错误：正确应为「只考虑了他自己的利益」，不加量词。「一只」多用于动物或成对的器物，「利益」不能用「只」计量，「自己的一只利益」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了个人利益们，放弃了大家的机会。", "corrected_sentence": "他为了个人利益，放弃了大家的机会。", "error_description": "词缀错误：“们”只能加在指人的名词或代词后，抽象名词“利益”不能加“们”；正确为“为了个人利益”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
