INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好处；对某人或某个群体有益的事物。", "primary_collocate": null, "pronunciation": "lì yì", "ipa": "li˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "公司要保护员工的利益。", "target_word": "利益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样做会损害大家的利益。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家的利益应该放在第一位。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们有共同的利益，所以合作得很好。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律保护消费者的利益。", "target_word": "利益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做决定时，要先想想大家的利益。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了小组的利益，他放弃了机会。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司的利益发生了冲突。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师应该维护学生的利益。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的合同要照顾双方的利益。", "target_word": "利益", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个人利益", "label": "复合"}, {"form": "国家利益", "label": "复合"}, {"form": "共同利益", "label": "复合"}], "register": "中性", "sense_fingerprint": "群体、公司、国家等的共同好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：利益（lì yì），指群体共同的好处。"}, {"text": "记忆", "is_correct": false, "explanation": "jì 与 lì 声母不同（j 与 l），意思是记住的内容。"}, {"text": "异议", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母 y 与 l），意思是不同的意见。"}, {"text": "礼仪", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）、yí（第二声）与 yì（第四声）声调不同，意思是礼节和仪式。"}], "explanations": {"利益": "正确答案：利益（lì yì），指群体共同的好处。", "记忆": "jì 与 lì 声母不同（j 与 l），意思是记住的内容。", "异议": "yì 与 lì 声母不同（零声母 y 与 l），意思是不同的意见。", "礼仪": "lǐ（第三声）与 lì（第四声）、yí（第二声）与 yì（第四声）声调不同，意思是礼节和仪式。"}, "sentence_index": null, "correct_answer": "利益"}, "level_3": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：「保护员工的利益」指保护员工应得的好处。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：员工的颜色不是可以被保护的好处，句子说不通。"}, {"text": "方向", "is_correct": false, "explanation": "语义：「方向」不指好处，「保护员工的方向」与句意不合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「保护」一般不与「脾气」搭配，说不通。"}], "explanations": {"利益": "正确答案：「保护员工的利益」指保护员工应得的好处。", "颜色": "语义：员工的颜色不是可以被保护的好处，句子说不通。", "方向": "语义：「方向」不指好处，「保护员工的方向」与句意不合。", "脾气": "搭配：「保护」一般不与「脾气」搭配，说不通。"}, "sentence_index": 0, "correct_answer": "利益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的利益是画画。", "explanation": "这里应该用〈兴趣〉。「兴趣」指对事物的爱好，「利益」指好处，不能用来说个人的爱好。"}, {"text": "他的利益很好，大家都喜欢他。", "explanation": "这里应该用〈脾气〉。说人的性情好要用「脾气」，「利益」指好处。"}, {"text": "银行每年付给这笔存款的利益是三百元。", "explanation": "这里应该用〈利息〉。存款产生的钱称为利息，「利益」泛指好处，不指利息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87592, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：利益（lì yì），指群体共同的好处。"}, {"text": "离异", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是夫妻离婚。"}, {"text": "日益", "is_correct": false, "explanation": "rì 与 lì 声母不同（r 与 l），意思是一天比一天。"}, {"text": "意义", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母 y 与 l），意思是价值或含义。"}], "explanations": {"利益": "正确答案：利益（lì yì），指群体共同的好处。", "离异": "lí（第二声）与 lì（第四声）声调不同，意思是夫妻离婚。", "日益": "rì 与 lì 声母不同（r 与 l），意思是一天比一天。", "意义": "yì 与 lì 声母不同（零声母 y 与 l），意思是价值或含义。"}, "sentence_index": null, "correct_answer": "利益"}, "level_3": {"options": [{"text": "利益", "is_correct": true, "explanation": "正确答案：「为了小组的利益」指小组共同的好处。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不能作为「为了」的目的，句子说的是小组的好处。"}, {"text": "气味", "is_correct": false, "explanation": "语义：“气味”与放弃机会的理由无关，句子说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「为了……的脚步」不能作为放弃机会的理由，与「为了」的搭配不合。"}], "explanations": {"利益": "正确答案：「为了小组的利益」指小组共同的好处。", "天气": "语义：「天气」不能作为「为了」的目的，句子说的是小组的好处。", "气味": "语义：“气味”与放弃机会的理由无关，句子说不通。", "脚步": "搭配：「为了……的脚步」不能作为放弃机会的理由，与「为了」的搭配不合。"}, "sentence_index": 6, "correct_answer": "利益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的利益长到一米六了。", "explanation": "这里应该用〈身高〉。「利益」是抽象的好处，不能用来说身高。"}, {"text": "这个房间的利益太小了。", "explanation": "这里应该用〈面积〉。「利益」指好处，不能用来说房间大小。"}, {"text": "这份工作每月的利益是一万元。", "explanation": "这里应该用〈薪水〉。每月的劳动报酬称为薪水，「利益」指好处，不指工资数额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
