INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了班级的利益们，大家都很努力。", "corrected_sentence": "为了班级的利益，大家都很努力。", "error_description": "词缀错误：「们」只能加在指人的名词或代词后，抽象名词「利益」不能加「们」，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
