INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87593, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房是人住的屋子。", "primary_collocate": null, "pronunciation": "fáng", "ipa": "faŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我打算明年在这个城市买房。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刚结婚，没有钱买房，只好租房。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们要去看房，看看那套房大不大。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房有三个卧室，很适合一家人住。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老家的房卖了，搬到了城里。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我租的那套房离公司很近，走路十分钟。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷住的那套房已经很老了。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租一套有阳台的房。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作了十年，终于买下了自己的房。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房朝南，冬天很暖和。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "房子", "label": "复合"}], "register": "通用", "sense_fingerprint": "房|人住的屋子|买房租房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "房", "is_correct": true, "explanation": "正确答案。房 fáng，指人住的屋子。"}, {"text": "方", "is_correct": false, "explanation": "fāng（第一声）与 fáng 声调不同，意思是方向或方形，与“房”不同。"}, {"text": "放", "is_correct": false, "explanation": "fàng（第四声）与 fáng 声调不同，意思是放置，与“房”不同。"}, {"text": "访", "is_correct": false, "explanation": "fǎng（第三声）与 fáng 声调不同，意思是拜访，与“房”不同。"}], "explanations": {"房": "正确答案。房 fáng，指人住的屋子。", "方": "fāng（第一声）与 fáng 声调不同，意思是方向或方形，与“房”不同。", "放": "fàng（第四声）与 fáng 声调不同，意思是放置，与“房”不同。", "访": "fǎng（第三声）与 fáng 声调不同，意思是拜访，与“房”不同。"}, "sentence_index": null, "correct_answer": "房"}, "level_3": {"options": [{"text": "房", "is_correct": true, "explanation": "正确：“买房”指买下住所，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”用于可以买卖的东西，空气不能被买。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想不是可以买卖的东西，“买梦想”不成立。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“买”的对象是商品，名字不能买。"}], "explanations": {"房": "正确：“买房”指买下住所，符合句意。", "空气": "搭配：“买”用于可以买卖的东西，空气不能被买。", "梦想": "语义：梦想不是可以买卖的东西，“买梦想”不成立。", "名字": "搭配：“买”的对象是商品，名字不能买。"}, "sentence_index": 0, "correct_answer": "房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只房有三个卧室，很适合一家人住。", "explanation": "这里应该用〈套〉。房按套计算；“只”用于动物等，不能修饰房。"}, {"text": "这间房有三个卧室，很适合一家人住。", "explanation": "这里应该用〈套〉。“间”指房间，不指整套住宅。"}, {"text": "这辆房在城郊，楼下有一个大花园。", "explanation": "这里应该用〈套〉。“辆”用于车，房不能用“辆”计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87593, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "房", "is_correct": true, "explanation": "正确答案。房 fáng，指人住的屋子。"}, {"text": "纺", "is_correct": false, "explanation": "fǎng（第三声）与 fáng 声调不同，意思是纺织，与“房”不同。"}, {"text": "芳", "is_correct": false, "explanation": "fāng（第一声）与 fáng 声调不同，意思是香气，与“房”不同。"}, {"text": "仿", "is_correct": false, "explanation": "fǎng（第三声）与 fáng 声调不同，意思是模仿，与“房”不同。"}], "explanations": {"房": "正确答案。房 fáng，指人住的屋子。", "纺": "fǎng（第三声）与 fáng 声调不同，意思是纺织，与“房”不同。", "芳": "fāng（第一声）与 fáng 声调不同，意思是香气，与“房”不同。", "仿": "fǎng（第三声）与 fáng 声调不同，意思是模仿，与“房”不同。"}, "sentence_index": null, "correct_answer": "房"}, "level_3": {"options": [{"text": "房", "is_correct": true, "explanation": "正确：“那套房”指一处住所，“住的”修饰房，符合句意。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“住的”只修饰住处，不能修饰衣服。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以住的地方，“住的那套饭”不成立。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“住”不能与病搭配，病不能被住。"}], "explanations": {"房": "正确：“那套房”指一处住所，“住的”修饰房，符合句意。", "衣服": "搭配：“住的”只修饰住处，不能修饰衣服。", "饭": "语义：饭不是可以住的地方，“住的那套饭”不成立。", "病": "搭配：“住”不能与病搭配，病不能被住。"}, "sentence_index": 6, "correct_answer": "房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这房很厚，夏天不热，冬天也不冷。", "explanation": "这里应该用〈墙〉。“厚”形容墙，房是整个屋子，不能直接说房很厚。"}, {"text": "请把房关上，外面很冷。", "explanation": "这里应该用〈门〉。要关的是门，房是屋子，不能直接说关房。"}, {"text": "这个房是用来存钱的，我每个月都去存。", "explanation": "这里应该用〈银行〉。“房”指屋子，不能用来存钱；存钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
