INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房间；房屋内用墙隔开的一个空间，也指旅馆里供住宿的房间。", "primary_collocate": null, "pronunciation": "fáng", "ipa": "faŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我在网上订了一间房。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，今晚还有房吗？", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的房都订满了，我们只好换一家。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们订了两间房，一间大的，一间小的。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次出差，公司给他订了一间房。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房很安静，窗外就是花园。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把行李放在我的房里。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的房在三楼，电梯在左边。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的房里有一张小床和一张书桌。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在旅馆住的房不大，但是很干净。", "target_word": "房", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "房间", "label": "复合"}], "register": "通用", "sense_fingerprint": "房|房间|订房退房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "房", "is_correct": true, "explanation": "正确答案。房 fáng，指房间。"}, {"text": "方", "is_correct": false, "explanation": "fāng（第一声）与 fáng 声调不同，意思是方向或方形，与“房”不同。"}, {"text": "放", "is_correct": false, "explanation": "fàng（第四声）与 fáng 声调不同，意思是放置，与“房”不同。"}, {"text": "访", "is_correct": false, "explanation": "fǎng（第三声）与 fáng 声调不同，意思是拜访，与“房”不同。"}], "explanations": {"房": "正确答案。房 fáng，指房间。", "方": "fāng（第一声）与 fáng 声调不同，意思是方向或方形，与“房”不同。", "放": "fàng（第四声）与 fáng 声调不同，意思是放置，与“房”不同。", "访": "fǎng（第三声）与 fáng 声调不同，意思是拜访，与“房”不同。"}, "sentence_index": null, "correct_answer": "房"}, "level_3": {"options": [{"text": "房", "is_correct": true, "explanation": "正确：“订了一间房”指订下一个住宿的房间，符合句意。"}, {"text": "票", "is_correct": false, "explanation": "搭配：量词“间”只用于房间，票应用“张”。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：量词“间”用于房间，座位应用“个”或“排”。"}, {"text": "车", "is_correct": false, "explanation": "量词：“间”不能用于车，车应用“辆”。"}], "explanations": {"房": "正确：“订了一间房”指订下一个住宿的房间，符合句意。", "票": "搭配：量词“间”只用于房间，票应用“张”。", "座位": "搭配：量词“间”用于房间，座位应用“个”或“排”。", "车": "量词：“间”不能用于车，车应用“辆”。"}, "sentence_index": 0, "correct_answer": "房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们订了两只房，一只大的，一只小的。", "explanation": "这里应该用〈间〉。“只”用于动物等，房间要用“间”。"}, {"text": "我们订了两把房，一把大的，一把小的。", "explanation": "这里应该用〈间〉。“把”用于有柄或可握的东西，房间要用“间”。"}, {"text": "我们订了两张房，一张大的，一张小的。", "explanation": "这里应该用〈间〉。“张”用于平面的东西，房间要用“间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "房", "is_correct": true, "explanation": "正确答案。房 fáng，指房间。"}, {"text": "纺", "is_correct": false, "explanation": "fǎng（第三声）与 fáng 声调不同，意思是纺织，与“房”不同。"}, {"text": "芳", "is_correct": false, "explanation": "fāng（第一声）与 fáng 声调不同，意思是香气，与“房”不同。"}, {"text": "仿", "is_correct": false, "explanation": "fǎng（第三声）与 fáng 声调不同，意思是模仿，与“房”不同。"}], "explanations": {"房": "正确答案。房 fáng，指房间。", "纺": "fǎng（第三声）与 fáng 声调不同，意思是纺织，与“房”不同。", "芳": "fāng（第一声）与 fáng 声调不同，意思是香气，与“房”不同。", "仿": "fǎng（第三声）与 fáng 声调不同，意思是模仿，与“房”不同。"}, "sentence_index": null, "correct_answer": "房"}, "level_3": {"options": [{"text": "房", "is_correct": true, "explanation": "正确：“放在我的房里”指放进个人的房间，符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以装行李的空间，“放在我的饭里”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是抽象的状态，不能作为装东西的地方。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“放在……里”需要有容器，问题不能作为放置行李的地方。"}], "explanations": {"房": "正确：“放在我的房里”指放进个人的房间，符合句意。", "饭": "语义：饭不是可以装行李的空间，“放在我的饭里”不成立。", "天气": "语义：天气是抽象的状态，不能作为装东西的地方。", "问题": "搭配：“放在……里”需要有容器，问题不能作为放置行李的地方。"}, "sentence_index": 6, "correct_answer": "房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我拉开房的抽屉，拿出一双袜子。", "explanation": "这里应该用〈柜子〉。抽屉是柜子的部件，“房”不能拉开抽屉。"}, {"text": "我每天早上用房喝牛奶，喝完再去上班。", "explanation": "这里应该用〈杯子〉。“房”是屋子，不能用来盛牛奶；喝牛奶要用杯子。"}, {"text": "病人一口吞下了那个房，然后马上就好了。", "explanation": "这里应该用〈药片〉。“房”是屋子，不能吞下；要吞服的是药片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想再订一只房，和朋友一起住。", "corrected_sentence": "我想再订一间房，和朋友一起住。", "error_description": "量词错误：“房间”应用量词“间”，“只”多用于动物，不能修饰房间。正确形式为“一间房”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友帮我订了两间的房。", "corrected_sentence": "朋友帮我订了两间房。", "error_description": "助词错误：数量词“两间”与名词“房”之间不能加“的”，正确形式为“两间房”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
