INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87595, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "护理是照看生病的人，帮他快点好起来。", "primary_collocate": null, "pronunciation": "hù lǐ", "ipa": "xu˥˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "妈妈发烧了，我在床边护理了她一晚上。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷住院时，叔叔每天去医院护理他。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学怎么护理发烧的孩子。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士耐心地护理着每一位病人。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病那几天，同屋的朋友一直护理我。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请了三天假，专门护理生病的丈夫。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来护理奶奶？大家商量了很久。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生教我们怎样护理刚出院的病人。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他护理过生病的邻居，很有办法。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆病了，妈妈回老家去护理她。", "target_word": "护理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "护理了", "label": "体标"}, {"form": "护理着", "label": "体标"}, {"form": "护理过", "label": "体标"}], "register": "中性", "sense_fingerprint": "照看生病的人帮他好起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87595, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "护理", "is_correct": true, "explanation": "正确。护理：照看生病的人，帮他快点好起来。"}, {"text": "助理", "is_correct": false, "explanation": "zhù lǐ 与 hù lǐ 声母不同（zh 与 h），意思是助理，不是照看病人。"}, {"text": "物理", "is_correct": false, "explanation": "wù lǐ 与 hù lǐ 声母不同（w 与 h），意思是物理，不是护理。"}, {"text": "互利", "is_correct": false, "explanation": "hù lì 与 hù lǐ 第二音节声调不同（第四声与第三声），意思是互相得利。"}, {"text": "狐狸", "is_correct": false, "explanation": "hú lí 与 hù lǐ 两个音节的声调都不同，意思是狐狸。"}], "explanations": {"护理": "正确。护理：照看生病的人，帮他快点好起来。", "助理": "zhù lǐ 与 hù lǐ 声母不同（zh 与 h），意思是助理，不是照看病人。", "物理": "wù lǐ 与 hù lǐ 声母不同（w 与 h），意思是物理，不是护理。", "互利": "hù lì 与 hù lǐ 第二音节声调不同（第四声与第三声），意思是互相得利。", "狐狸": "hú lí 与 hù lǐ 两个音节的声调都不同，意思是狐狸。"}, "sentence_index": null, "correct_answer": "护理"}, "level_3": {"options": [{"text": "护理", "is_correct": true, "explanation": "正确。妈妈发烧，我在床边照看她一晚上，“护理”符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、场所，不能说在床边打扫一个人。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋，不能说在床边装修一个人。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与床边照看病人的语境不合。"}], "explanations": {"护理": "正确。妈妈发烧，我在床边照看她一晚上，“护理”符合语境。", "打扫": "搭配：“打扫”用于房间、场所，不能说在床边打扫一个人。", "装修": "搭配：“装修”用于房屋，不能说在床边装修一个人。", "翻译": "语义：“翻译”指转换语言，与床边照看病人的语境不合。"}, "sentence_index": 0, "correct_answer": "护理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他帮我护理这份重要文件。", "explanation": "这里应该用〈保管〉。护理针对病人，文件等物品要用保管。"}, {"text": "老师在考场护理学生考试。", "explanation": "这里应该用〈监考〉。护理是照料病人，看着学生考试要用监考。"}, {"text": "他替我护理行李。", "explanation": "这里应该用〈照看〉。护理针对病人，行李、物品只能照看，不说护理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "护理", "is_correct": true, "explanation": "正确。大家商量谁来照料奶奶，“谁来护理奶奶”符合语境。"}, {"text": "训练", "is_correct": false, "explanation": "语义：“训练”指教授技能，不能用来指照料奶奶。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物品或场地，不能用于照料奶奶。"}, {"text": "检阅", "is_correct": false, "explanation": "语义：“检阅”指检查队伍，与照料奶奶的语境不合。"}], "explanations": {"护理": "正确。大家商量谁来照料奶奶，“谁来护理奶奶”符合语境。", "训练": "语义：“训练”指教授技能，不能用来指照料奶奶。", "装饰": "搭配：“装饰”用于物品或场地，不能用于照料奶奶。", "检阅": "语义：“检阅”指检查队伍，与照料奶奶的语境不合。"}, "sentence_index": 6, "correct_answer": "护理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客服人员热情护理顾客。", "explanation": "这里应该用〈接待〉。护理的对象是病人或老人，接待顾客要用接待。"}, {"text": "师傅护理了这台冰箱。", "explanation": "这里应该用〈修理〉。护理是照料病人，修理机器要用修理。"}, {"text": "他把这篇文章护理成英文。", "explanation": "这里应该用〈翻译〉。护理是照料病人，把文章转换成另一种语言要用翻译。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把孩子护理很好，孩子很快就退烧了。", "corrected_sentence": "他把孩子护理得很好，孩子很快就退烧了。", "error_description": "错误在“护理”的补语。“把”字句中表示结果或程度的补语要用“得”连接，应说“把孩子护理得很好”，漏掉“得”则句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我护理了过两个发烧的孩子。", "corrected_sentence": "我护理过两个发烧的孩子。", "error_description": "体标错误：“了”与“过”不能同时用在一个动词后，应只用“过”，说“护理过两个发烧的孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
