INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87597, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恐吓是用坏话和凶样子吓别人，让他害怕。", "primary_collocate": null, "pronunciation": "kǒng hè", "ipa": "kʰʊŋ˨˩˦ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "大个子瞪着我恐吓我。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大声恐吓小弟弟。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人恐吓我，说要打我。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别恐吓他，他还小。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏孩子常常恐吓别的孩子。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他板着脸恐吓我们。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么恐吓我的朋友？", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握着拳头恐吓对方。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她恐吓弟弟说，再哭就不给饭吃。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个人恐吓了那个新同学。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐吓了", "label": "体标"}, {"form": "恐吓过", "label": "体标"}, {"form": "恐吓信", "label": "复合"}], "register": "中性", "sense_fingerprint": "恐吓：用凶狠的话和样子吓人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐吓", "is_correct": true, "explanation": "恐吓：用凶狠的样子使人害怕，与“瞪着我”的语境相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱赞赏，与“瞪着我”的凶狠语境相反。"}, {"text": "款待", "is_correct": false, "explanation": "语域：“款待”属正式用语，且热情招待的意思与“瞪着我”的威胁语境不合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，与“瞪着我”的威胁语境不合。"}], "explanations": {"恐吓": "恐吓：用凶狠的样子使人害怕，与“瞪着我”的语境相合。", "欣赏": "语义：“欣赏”是喜爱赞赏，与“瞪着我”的凶狠语境相反。", "款待": "语域：“款待”属正式用语，且热情招待的意思与“瞪着我”的威胁语境不合。", "感谢": "语义：“感谢”表示感激，与“瞪着我”的威胁语境不合。"}, "sentence_index": 0, "correct_answer": "恐吓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌人恐吓我们的边境。", "explanation": "这里应该用〈威胁〉。恐吓的对象是人，要使人害怕；“边境”是地点，应说威胁我们的边境。"}, {"text": "班长恐吓了上课认真听讲的同学，还给他加了分。", "explanation": "这里应该用〈表扬〉。恐吓是用坏话和凶样子吓人，与“还给他加了分”的奖励相反；表扬才是称赞。"}, {"text": "爷爷恐吓我别难过，一切都会好的。", "explanation": "这里应该用〈安慰〉。恐吓是用坏话和凶样子吓人，与“一切都会好的”的宽慰相反；安慰才是让人放心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐吓", "is_correct": true, "explanation": "恐吓：以威胁使人害怕，与“你为什么”的责问语境相合。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：“桌子”是名词，不能带宾语“我的朋友”，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "词性：“颜色”是名词，不能作谓语带宾语“我的朋友”。"}, {"text": "漂亮", "is_correct": false, "explanation": "词性：“漂亮”是形容词，不能直接带宾语“我的朋友”。"}], "explanations": {"恐吓": "恐吓：以威胁使人害怕，与“你为什么”的责问语境相合。", "桌子": "词性：“桌子”是名词，不能带宾语“我的朋友”，句子不通。", "颜色": "词性：“颜色”是名词，不能作谓语带宾语“我的朋友”。", "漂亮": "词性：“漂亮”是形容词，不能直接带宾语“我的朋友”。"}, "sentence_index": 6, "correct_answer": "恐吓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长恐吓了考第一的学生，还给他发了奖状。", "explanation": "这里应该用〈奖励〉。恐吓是用坏话和凶样子吓人，与“发奖状”的嘉奖相反；奖励是给好的表现以奖赏。"}, {"text": "奶奶恐吓我，说我的画画得特别好。", "explanation": "这里应该用〈称赞〉。恐吓是用坏话和凶样子吓人，与“画得特别好”的赞美相反；称赞才是夸奖别人。"}, {"text": "老师恐吓了那个新来的同学，还热情地和他握手。", "explanation": "这里应该用〈欢迎〉。恐吓是用坏话和凶样子吓人，与“热情地握手”的友好相反；欢迎才是表示接纳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那些人恐吓了过我的朋友。", "corrected_sentence": "那些人恐吓过我的朋友。", "error_description": "错误：在动词“恐吓”和体标“过”之间多加了“了”，动词后只能用一个体标。应说“那些人恐吓过我的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些坏人恐吓他过，让他不敢报警。", "corrected_sentence": "那些坏人恐吓过他，让他不敢报警。", "error_description": "错误：体标“过”放在了宾语“他”之后。“过”应紧跟动词，应说“恐吓过他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
