INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用威胁的言语或手段使人害怕。", "primary_collocate": null, "pronunciation": "kǒng hè", "ipa": "kʰʊŋ˨˩˦ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他用刀恐吓路人。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人写信恐吓这位老板。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了恐吓别人的坏人。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他恐吓过邻居，警察来找他了。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能恐吓小孩子。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人恐吓他，不让他说出去。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想恐吓证人，让他改口。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，恐吓同学是不对的。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论别人怎么恐吓，他都不怕。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的人恐吓他，要他交钱。", "target_word": "恐吓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐吓了", "label": "体标"}, {"form": "恐吓过", "label": "体标"}, {"form": "恐吓信", "label": "复合"}], "register": "中性", "sense_fingerprint": "恐吓：用威胁的话或手段让人害怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4002be13-b123-4b4b-8667-dd242372d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐吓", "is_correct": true, "explanation": "恐吓：用威胁的手段使人害怕，与“用刀”和“路人”的语境相合。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”是让人平静，“用刀”去安慰路人说不通。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“用刀”后不能接“拥抱”，拥抱不需要借助刀具。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”是关心、看护，与“用刀”加“路人”的威胁语境相反。"}], "explanations": {"恐吓": "恐吓：用威胁的手段使人害怕，与“用刀”和“路人”的语境相合。", "安慰": "语义：“安慰”是让人平静，“用刀”去安慰路人说不通。", "拥抱": "搭配：“用刀”后不能接“拥抱”，拥抱不需要借助刀具。", "照顾": "语义：“照顾”是关心、看护，与“用刀”加“路人”的威胁语境相反。"}, "sentence_index": 0, "correct_answer": "恐吓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌人恐吓这座城市的安全。", "explanation": "这里应该用〈威胁〉。恐吓的对象是人，要使人害怕；“安全”是抽象事物，应说威胁这座城市的安全。"}, {"text": "奶奶恐吓了那个帮忙洗碗的孩子，还给他一颗糖。", "explanation": "这里应该用〈奖励〉。恐吓是用威胁使人害怕，与“给他一颗糖”的好意相反；奖励才是对好的表现给予奖赏。"}, {"text": "妈妈恐吓我别哭了，一切都会好的。", "explanation": "这里应该用〈安慰〉。恐吓是用威胁使人害怕，与“一切都会好的”这种让人放心的话相反；安慰才是说话让人宽心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐吓", "is_correct": true, "explanation": "恐吓：以威胁使证人害怕，与“让他改口”的强迫语境相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，与“让他改口”的强迫意图相反。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是庆贺，与“让他改口”的强迫语境不合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，证人受到表扬不会因此改口，语境不合。"}], "explanations": {"恐吓": "恐吓：以威胁使证人害怕，与“让他改口”的强迫语境相合。", "感谢": "语义：“感谢”表示感激，与“让他改口”的强迫意图相反。", "祝贺": "语义：“祝贺”是庆贺，与“让他改口”的强迫语境不合。", "表扬": "语义：“表扬”是称赞，证人受到表扬不会因此改口，语境不合。"}, "sentence_index": 6, "correct_answer": "恐吓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生恐吓病人，说他恢复得很好。", "explanation": "这里应该用〈夸奖〉。恐吓是用威胁使人害怕，与“恢复得很好”的赞许语气相反；夸奖才是称赞别人。"}, {"text": "园长恐吓了那个第一次来的小朋友，还送给他一本图画书。", "explanation": "这里应该用〈善待〉。恐吓是用威胁使人害怕，与“送给他一本图画书”的好意相反；善待才是友好地对待别人。"}, {"text": "老师恐吓了那个答得很好的学生，还给他一朵小红花。", "explanation": "这里应该用〈表扬〉。恐吓是用威胁使人害怕，与“给他一朵小红花”的奖励相反；表扬才是称赞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他恐吓了过我的邻居。", "corrected_sentence": "他恐吓过我的邻居。", "error_description": "错误：在动词“恐吓”和体标“过”之间多加了“了”，动词后只能用一个体标。应说“他恐吓过我的邻居”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人没有恐吓了我。", "corrected_sentence": "那个人没有恐吓过我。", "error_description": "错误：“没有”否定的是已经发生过的动作，体标应用“过”，不能用“了”。应说“那个人没有恐吓过我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '801c3531-1549-41f6-bdf6-9950606d366f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
