INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87599, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，书面语，表示数量很多，差别很大。", "primary_collocate": null, "pronunciation": "dà yǒu", "ipa": "ta˥˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "想学汉语的人大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比他更聪明的学生大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿意帮助你的人大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喜欢爬山的年轻人大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做的老板大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有钱却不快乐的人大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的生活大有不同。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的天气和昨天大有不同。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个人的看法大有差别。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱看这个节目的观众大有人在。", "target_word": "大有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "数量很多、差别很大（大有人在、大有不同）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87599, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大有", "is_correct": true, "explanation": "大有（dà yǒu）是副词，表示数量很多、差别很大，如“大有人在”。"}, {"text": "大雨", "is_correct": false, "explanation": "yǔ（第三声）与 yǒu 韵母不同（ü 与 ou），声调相同，意思是“大雨”。"}, {"text": "带有", "is_correct": false, "explanation": "dài 与 dà 只差韵母（ai 与 a），意思是“带有”。"}, {"text": "但有", "is_correct": false, "explanation": "dàn 与 dà 只差鼻音韵尾（n），意思是“只要有”，与“大有”不同。"}], "explanations": {"大有": "大有（dà yǒu）是副词，表示数量很多、差别很大，如“大有人在”。", "大雨": "yǔ（第三声）与 yǒu 韵母不同（ü 与 ou），声调相同，意思是“大雨”。", "带有": "dài 与 dà 只差韵母（ai 与 a），意思是“带有”。", "但有": "dàn 与 dà 只差鼻音韵尾（n），意思是“只要有”，与“大有”不同。"}, "sentence_index": null, "correct_answer": "大有"}, "level_3": {"options": [{"text": "大有", "is_correct": true, "explanation": "“大有人在”表示数量很多，符合本句。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能与“人在”组合，“很人在”不成立。"}, {"text": "挺", "is_correct": false, "explanation": "搭配：“挺”不能与“人在”组合，“挺人在”不成立。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”不能修饰“人在”，“格外人在”不成立。"}], "explanations": {"大有": "“大有人在”表示数量很多，符合本句。", "很": "搭配：“很”不能与“人在”组合，“很人在”不成立。", "挺": "搭配：“挺”不能与“人在”组合，“挺人在”不成立。", "格外": "搭配：“格外”不能修饰“人在”，“格外人在”不成立。"}, "sentence_index": 0, "correct_answer": "大有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划大有前途。", "explanation": "这里“大有”表示程度很深地有（前途很大），与本词“数量很多、差别很大”的意思不同。"}, {"text": "他的汉语比去年大有进步。", "explanation": "这里“大有”表示程度很深地有（进步很大），与本词“数量很多、差别很大”的意思不同。"}, {"text": "新工作让他大有收获。", "explanation": "这里“大有”表示程度很深地有（收获很多），与本词“数量很多、差别很大”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大有", "is_correct": true, "explanation": "“大有不同”表示差别很大，符合本句。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”表示本人去做某事，不能修饰“不同”。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同做某事，不能修饰“不同”。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示时间上的同步，与表示差别的“不同”不相符。"}], "explanations": {"大有": "“大有不同”表示差别很大，符合本句。", "亲自": "语义：“亲自”表示本人去做某事，不能修饰“不同”。", "一起": "搭配：“一起”表示共同做某事，不能修饰“不同”。", "同时": "语义：“同时”表示时间上的同步，与表示差别的“不同”不相符。"}, "sentence_index": 6, "correct_answer": "大有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个年轻人大有希望。", "explanation": "这里“大有”表示程度很深地有（希望很大），不是“数量很多、差别很大”的意思。"}, {"text": "每天锻炼，对身体大有益处。", "explanation": "这里“大有”表示程度很深地有（益处很多），不是“数量很多、差别很大”的意思。"}, {"text": "这座城市的变化大有看头。", "explanation": "这里“大有”表示程度很深地有（很值得看），不是“数量很多、差别很大”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "参加比赛的同学大有在人。", "corrected_sentence": "参加比赛的同学大有人在。", "error_description": "错误在“人”与“在”的语序颠倒。“大有人在”是固定说法，应说“大有人在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种方案的效果大有了不同。", "corrected_sentence": "这两种方案的效果大有不同。", "error_description": "错误在“大有”后面加了“了”。“大有”是副词，后面不能加“了”，应说“大有不同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
